kit/sim/lane.odin.text:
package kit_sim

// lane — the sim lane on a live session: the driver that turns the engine-
// free parts (input pipeline, ledgers, snapshots, reconcile) into two calls
// a game actually makes.
//
//     ksim.lane_init(&self.lane, &self.ses, size_of(Runner_Input))
//     ksim.lane_set_sim(&self.lane, self, game_sample, game_step)
//     // per spawned sim entity (from the factory / Ev_Spawned):
//     ksim.lane_track(&self.lane, id, entity, desc, owner)
//     // once per frame, beside session_tick:
//     ksim.lane_frame(&self.lane, delta)
//
// ZERO ROLE BRANCHES for the game: the same wiring runs everywhere, and the
// lane derives its role from the session. On the authority a frame pops each
// player's de-jittered input, steps the tick procs, ledgers truth, and ships
// per-client snapshot batches. On a client it samples local intent, predicts
// the same tick procs ahead of the server, ships the redundant input window,
// and reconciles arriving batches — the game's Step_Proc IS the resim proc,
// which is the whole single-player-shaped promise of this lane.
//
// It rides SES_APP like kit/comms: one tag, two message kinds inside it,
// both on the .Stream channel (tick-stamped, self-superseding — a lost one
// is worthless by the time it could be resent):
//
//     SIM_INPUT  client → host   [snap ack][render off][class count]{[class id][input window]}
//     SIM_SNAP   host → client   [snapshot batch]
//
// EVENTS, NOT CALLBACKS: handlers only file bytes into lane-owned state
// (input buffers, the pending batch); every call into game code — sample,
// step, resim — happens inside lane_frame, on the game's own stack. A batch
// arriving mid-pump can never re-enter the sim.
//
// The tick timeline is the SERVER'S. A client starts unanchored: it neither
// ticks nor sends until the first batch names the authoritative tick, then
// anchors ahead of it and lets the lead controller bend the clock from
// there — the batch header's input ack doubles as the feedback signal (how
// far the server's copy of our inputs ran ahead of its sim when the batch
// left), so the loop needs no extra wire and no clock-sync dependency.
//
// What the game's tick code may touch, the resim contract (scriptgen will
// enforce this on @(gd_tick) procs; until then it is discipline):
// predicted fields, lane_input, and per-tick derivables — never wall clocks,
// node state, or un-ledgered randomness.

import "core:fmt"
import "core:mem"
import "core:slice"
import knet "godot:kit/net"
import ksess "godot:kit/session"

_ :: fmt // native-only use (the tolerance warning) — the freestanding build compiles it out

SIM_TAG :: u8(3) // default SES_APP tag (comms holds 0, xfer holds 2)

// This package's wire revision — the lane's formats ONLY (input windows,
// snap batches, verbs, facts). Registered into the session's fingerprint
// salt at load (the session sits below and cannot import upward); a lane
// wire change bumps THIS constant, in the same commit.
WIRE_REV :: u64(4) // 4: ack-safe sparse/AOI snapshot batches

@(init, private = "file")
register_wire_rev :: proc "contextless" () {
	ksess.session_register_wire_rev(WIRE_REV, 16)
}

SIM_INPUT: u8 : 0 // client → host, inside the tag
SIM_SNAP: u8 : 1 // host → client
SIM_CMD: u8 : 2 // client → host, RELIABLE: a tick-stamped verb (command.odin)
SIM_VERDICT: u8 : 3 // host → client, RELIABLE: that verb's accept/reject
// host → client, RELIABLE: an event tick's facts, watch-clock presented.
// WIRE FORMAT (the one place it is written down — the generated encoders in
// every *.gen.odin and the receive case below are matched pairs, and the
// kitsim fact tests drive the full encode→decode path so a drift fails
// loudly):  [SIM_FACT u8][tick u64][anchor Net_Id u32; 0 = anchorless]
//           [kind u16; 0 = the anchor set's tick fx, else a Fact_Desc id]
//           [args: length-prefixed bytes — the fact tuple, wire-primitive
//            encoded in DECLARATION ORDER]
SIM_FACT: u8 : 4

// Fill the LOCAL player's input for `tick` into dst (input_size bytes).
// Read the device here and nowhere else — a resim never calls this.
Sample_Proc :: proc(user: rawptr, tick: u64, dst: rawptr)

// One input TYPE the lane carries: its wire class id, its byte size, the
// sample that fills it (nil on a seat that doesn't play), and the client's
// ring of already-predicted inputs for it. A single-input game holds exactly
// one of these; a game driving two entity kinds holds one per kind, each
// riding its own window on the packet and its own de-jitter buffer per player.
Input_Class :: struct {
	id:       u16,
	size:     int,
	// The input struct's typeid, when the registrar knew it (the generated
	// <game>_lane_init always does; a hand-built lane may leave it nil). It is a
	// LOCAL resolver key only — never on the wire — so lane_input_of can name its
	// class by TYPE instead of by size, which two input kinds can collide on
	// after an innocent field add. nil = fall back to size (see class_for_type).
	type:     typeid,
	sample:   Sample_Proc,
	validate: Input_Validate_Proc, // nil = structural checks only; generated
	// lane wiring installs the typed semantic hook
	ring:     Input_Ring, // client only: local inputs already fed to prediction
	scratch:  []u8, // sample destination (size bytes)
}

// Echo (predict-world) keys last-known inputs by (player, class): a remote
// player driving two kinds echoes one held input per kind.
@(private = "file")
Echo_Key :: struct {
	player: knet.Player_Id,
	class:  u16,
}

// Advance the sim-lane world one tick: read inputs via lane_input, mutate
// predicted fields. Deliberately the same shape as Resim_Proc — the live
// frame and the replay run the identical proc. OPTIONAL once entities carry
// their own tick thunks (lane_track_set): entity ticks run first, in track
// order, then this world pass — the spot for cross-entity work (spawning a
// predicted projectile, resolving a contested pickup).
Step_Proc :: proc(user: rawptr, tick: u64)

// One entity's tick, generated by scriptgen from @(gd_tick) (or hand-built
// in tests): cast, decode nothing (input is already struct bytes), call the
// author's proc — then route its returned PAYLOAD (facts the tick learned:
// fired, dashed, landed) to the name-paired halves, holding the role gates
// so game code never does: `<tick>_then` on the authority, `<tick>_fx` on
// the owning peer's LIVE pass (never a resim). `input` is the owning
// player's input for the tick being stepped — nil when no input drives this
// entity here; `owner` is the driving seat, for the routing and the
// consequence's `by`.
Tick_Thunk :: proc(entity: rawptr, input: rawptr, lane: ^Lane, owner: knet.Player_Id)

// One entity TYPE's every-screen presentation half — the mine-form `_fx`
// (an `_fx` declaring `mine: bool` after `self`), generated by scriptgen:
// decode the fact tuple, call the author's proc. `mine` = this screen's own
// simulation caused it (fired inline from the live pass); false = a watcher
// presenting the authority's word, fired when the watch clock reaches the
// fact's tick so the effect lands beside the delayed avatar that caused it.
Fx_Thunk :: proc(entity: rawptr, lane: ^Lane, mine: bool, args: []u8)

// Per entity TYPE: what the sim lane needs to drive it — the descriptor
// (predict subset) plus the tick entry point. scriptgen emits one per class
// with an @(gd_tick) proc: `runner_sim_set`.
Sim_Set :: struct {
	entity_desc: ^knet.Entity_Desc,
	tick:        Tick_Thunk,
	input_size:  int, // size of the tick proc's input struct (0 = inputless)
	input_class: u16, // WHICH input the tick reads — its class id on the wire. One
	// per distinct @(gd_tick) input TYPE in the package (scriptgen
	// assigns; the primary is 0). A lane ships one window per class
	// a seat drives, so a player controlling two entity KINDS (a
	// walker + a turret) sends both their inputs each tick.
	commands:    []Sim_Cmd, // the class's @(gd_command) verbs, tick-scheduled (command.odin)
	fx:          Fx_Thunk, // the mine-form `_fx` decode thunk (nil = the class declares
	// none): what a watcher fires when a filed SIM_FACT comes of age
	// @(gd_tick="contested"): EVERY peer predicts this entity, owner or not —
	// the predict-the-contested-object pattern (the ball, the crown, the
	// flag). Contact with it resolves on YOUR timeline instantly; the
	// server's word reconciles the fights, and the glide hides the losses.
	// Costs resim CPU per peer and honest mispredicts whenever a REMOTE
	// player (rendered in the past) touches it first — the documented trade.
	contested:   bool,
}

Lane_Config :: struct {
	hz:              int, // sim ticks per second (0 = DEFAULT_SIM_HZ, 60)
	snap_every:      int, // ticks between snapshot batches (0 = 3 → 20 Hz at 60)
	slots:           int, // ledger/ring depth in ticks (0 = 128 — covers ~2s of lead, resim, and ack round trips)
	margin:          int, // target server-side input headroom in ticks (0 = 2)
	redundancy:      int, // inputs per packet (0 = INPUT_REDUNDANCY)
	rewind_max:      int, // lag-comp rewind bound in ticks (0 = hz/4 ≈ 250ms — the favor-the-shooter ceiling)
	lead_max:        int, // furthest client-stamped input/verb tick accepted ahead of authority time
	// (0 = max(margin + rewind_max + 2×snap_every, slots/2, 8)); must fit in slots
	watch_delay:     int, // how far behind the newest batch watched entities RENDER, in ticks (0 = 2×snap_every — almost always a bracketing pair)
	smooth_halflife: f64, // reconcile-correction render error half-life, seconds (0 = 0.063 — the puppet constant)
	smooth_cut:      f32, // an error component past this is a deliberate cut and SNAPS, world units (0 = never cut)
	judge_live:      bool, // A/B knob: lane_rewound queries the LIVE world instead of rewinding —
	// feel lag comp by turning it off; never a game-code fork
	// PREDICT-WORLD (the Rocket League model): batches echo every player's
	// last-known input, and clients tick contested entities owned by REMOTE
	// players with those held inputs — one timeline for everything, no claim
	// dance, constant small glided corrections instead of delayed-but-
	// accurate remote views. Mark the avatars @(gd_tick="contested") too.
	// Costs: resim on nearly every batch (held inputs drift), a few bytes of
	// echo per player per batch. Compile-time config: every peer of a game
	// agrees by construction.
	echo_inputs:     bool,
	tolerance:       f32, // reconcile slack for FLOAT predicted fields, world units
	// (0 = exact). Predict-world's anti-churn: held-input
	// drift below this rides uncorrected until it accumulates
	// past the line; discrete fields always compare exactly.
	snapshot_budget: int, // max snapshot body bytes per recipient/batch (header + rows;
	// 0 = unlimited). AOI and unchanged-row suppression still apply at zero.
}

// Host-side per-player state, created when the authority first snapshots or
// receives traffic for the player.
@(private)
Lane_Peer :: struct {
	bufs:       map[u16]^Input_Buffer, // one de-jitter buffer per input class this player drives
	acked:      u64, // newest VALID issued snap tick they fully applied — their delta baseline
	tag:        u64, // the (ack<<8|off) rider of the input just popped — one packet feeds every
	// class, so every buffer's tag agrees; the rewind reads it here
	snap_first: u64, // first snapshot tick issued while this seat state has existed
	snap_last:  u64, // newest snapshot tick actually issued to this seat
	snap_sent:  map[knet.Net_Id]u64, // entity -> exact batch tick represented for this peer
}

@(private) // command.odin's scheduler walks the track list too
Tracked :: struct {
	id:          knet.Net_Id,
	entity:      rawptr,
	desc:        ^knet.Entity_Desc,
	owner:       knet.Player_Id, // whose inputs drive it (rewound queries spare the shooter's own)
	hist:        ^History, // truth (host) / prediction (client-owned); nil = watched
	watched:     bool, // client-side remote-owned: truth applies directly, no resim
	tick:        Tick_Thunk, // nil = the game's Step_Proc moves this entity
	has_in:      bool, // the thunk wants its owner's input (Sim_Set.input_size > 0)
	in_class:    u16, // which input class drives it (Sim_Set.input_class) — the ring/buffer key
	cmds:        []Sim_Cmd, // tick-scheduled verbs (nil = the class declares none)
	set:         ^Sim_Set, // the class's set (lane_track_set) — nil for hand-tracked entities
	err:         []u8, // render-error blob (predict-subset layout), alloc'd on the first correction
	contested:   bool, // predicted here but NOT mine: presentation follows `claim`
	claim:       f32, // 1 = my sim drives it (present predicted), decaying to 0 (present the watched view)
	// Predicted-spawn bookkeeping (a client-fired projectile, command.odin's
	// lane_spawn_predicted). born = the spawn tick, so ticks before it are
	// gated out of the ledger/rewind/resim (Entry.born). A provisional entity is
	// unmatched until the authority's spawn arrives and rekeys it.
	born:        u64,
	provisional: bool, // spawned locally, not yet matched to an authoritative id
	spawn_seq:   u32, // the firing command's seq — the match key (FIFO breaks on a rejected burst shot)
	spawn_type:  ksess.Entity_Type, // what to match against on the authority's spawn
}

Lane :: struct {
	world:                 ^World_History, // nil keeps the legacy engine-free/value-only path
	ses:                   ^ksess.Session,
	tag:                   u8,
	snap_every:            int,
	slots:                 int,
	margin:                int,
	redundancy:            int,
	rewind_max:            int,
	lead_max:              int,
	watch_delay:           int,
	watch_clock:           f64, // watched-entity render position, in fractional ticks
	presented:             bool, // the game has called lane_present at least once — until
	// then ingest keeps painting watched truth directly (a
	// hand-driven client that never presents must never freeze)
	smooth_halflife:       f64,
	smooth_cut:            f32,
	judge_live:            bool,
	tolerance:             f32,
	snapshot_budget:       int,
	echo_on:               bool,
	echo:                  map[Echo_Key][]u8, // last-known input per REMOTE (player, class) (predict-world)
	ticker:                Sim_Ticker,
	user:                  rawptr,
	// The allocator lane_init was given. EVERY lane entry point installs it
	// as context.allocator, so a handler-side alloc and its frame-side free
	// can never ride different allocators — the param used to cover only the
	// init-time containers, a half-promise a custom-allocator lane paid for
	// in mismatched frees.
	allocator:             mem.Allocator,
	// One input class per distinct @(gd_tick) input TYPE. Single-input games
	// hold exactly one (id 0, its sample from lane_set_sim); a game driving two
	// entity kinds registers the extras with lane_add_input_class. The client
	// samples and ships a window for every class here that has a sample; the
	// host de-jitters each into the matching per-player buffer.
	inputs:                [dynamic]Input_Class,
	step:                  Step_Proc, // the world pass that runs EVERYWHERE (live + resim): pure-sim contact
	step_auth:             Step_Proc, // the host-only world pass: adjudication, respawns (the authority never resims)
	tracked:               [dynamic]Tracked,
	entries:               [dynamic]Entry, // ledgered subset of tracked (host: all; client: mine)

	// client
	rx:                    Snap_Rx,
	pending:               [dynamic]u8, // newest unprocessed batch (copied out of the handler)
	pending_tick:          u64,
	input_ack:             u64, // newest input tick the server confirmed (batch header)
	anchored:              bool,

	// host
	peers:                 map[knet.Player_Id]^Lane_Peer,
	step_tick:             u64, // the tick being stepped/resimmed — lane_input reads it
	// True while a reconcile replay is re-running ticks. Gate PRESENTATION
	// side effects on it (muzzle flashes, sounds, screen shake fire once, on
	// the live pass) — sim mutations must NEVER branch on it, or prediction
	// and replay diverge by construction.
	resimming:             bool,

	// running tallies, game-readable (a resim burst is a netgraph datum)
	stat_resims:           int,
	stat_resim_seconds:    f64, // cumulative wall time spent replaying reconciliation ticks
	stat_reconciles:       int,
	stat_facts_dropped:    int, // world facts refused by a full queue — a moving count means the game presents too rarely (or FACT_QUEUE_CAP is honestly too small)
	stat_render_sat:       int, // render_off8 hit the wire's 31.5-tick ceiling — the authority now rewinds LESS than this screen's true delay (lag comp judges shallow)
	stat_input_drops:      int, // host: input windows dropped for an unknown class id — zero in a same-build session; a moving count is version skew or garbage on the port
	stat_input_rejected:   int, // host: malformed/future input windows rejected before they touched a de-jitter ring
	stat_ack_rejected:     int, // host: snapshot acks rejected as unissued, regressing, misaligned, or implausibly old
	stat_cmd_capped:       int, // host: verbs refused by the per-player CMD_HOST_CAP — an honest client never queues this deep; a moving count names the peer flooding you
	stat_cmd_rate_dropped: int, // host: otherwise-valid verbs refused by the shared per-player action token bucket
	stat_cmd_rejected:     int, // host: verbs refused by syntax, replay, bounds, access, or execution-time reauthorization
	stat_echo_dropped:     int, // host: echo rows omitted at the u8 row ceiling
	stat_snap_rows:        int,
	stat_snap_full:        int,
	stat_snap_delta:       int,
	stat_snap_suppressed:  int, // unchanged rows represented by ack-safe carry-forward
	stat_snap_deferred:    int, // interested rows postponed by the recipient byte budget
	stat_snap_aoi_culled:  int, // rows omitted because this recipient is outside AOI
	stat_snap_bytes:       int, // snapshot body bytes sent (header + rows; excludes app/echo framing)
	// host: rewound queries whose reconstructed view exceeded the authority's
	// observed-link or configured rewind envelope and got clamped to its floor
	// (lane_rewind_view). The counter exists because the
	// clamp was the one failure in this file with no voice at all: the deep-lead
	// surplus bug killed lag comp by pushing every query past this ceiling, the
	// authority judged a half-second-old world, hit nothing, and NOTHING recorded
	// it — the pathology was found in a sibling port's engine acid, not here.
	// Counts QUERIES, not shots: a game that also calls lane_rewind_tick for
	// diagnostics on the same trigger tallies both. A moving count means this
	// shooter's claim is older than the authority can substantiate — either the
	// clock is still cold, their lead is mispaced, their render hint exceeds the
	// configured watch delay, or rewind_max is genuinely too small for the link.
	stat_rewind_clamped:   int,

	// active inline rewind (lane_rewound_begin/end) — live captures to restore
	wound:                 [dynamic]Wound,
	rewound:               bool,

	// tick-scheduled verbs (command.odin): the client's issued ledger and
	// the host's arrival queue
	cmd_seq:               Cmd_Seq, // the client's issued-command counter (command.odin)
	cmd_clock:             u64, // client frame clock: action timeouts advance even when authority loss stalls sim ticks
	cmd_out:               [dynamic]Cmd_Out,
	cmd_in:                [dynamic]Cmd_In,
	cmd_exec_seq:          u32, // the command whose exec is running RIGHT NOW (0 = none) —
	// lane_spawn_predicted tags its projectile with it, so a
	// rejected fire despawns exactly the projectile it spawned

	// every-screen tick facts (mine-form _fx): the authority broadcasts one
	// SIM_FACT per event tick; a client files them here and fires the set's
	// fx thunk when the watch clock reaches the fact's tick (lane_present).
	facts:                 [dynamic]Fact_In,

	// sim-routed @(gd_event) declarations: the package's event table, id →
	// decode thunk, installed by the generated <snake>_lane_init. Kind 0 is
	// reserved for entity-tick facts (routed through the anchor's Sim_Set.fx).
	fact_set:              []Fact_Desc,

	// True while an AUTHORITY-ONLY context is running: the step_auth pass
	// (run_tick sets it) and every generated `_then` half (the tick and verb
	// thunks set it around the authority-gated call). lane_fact reads it for
	// the broadcast's owner skip: an everywhere-pass fact skips the anchor's
	// owner (their own live pass just presented it), but an authority-only
	// context's fact must INCLUDE them — their screen never ran the code that
	// announced it, and skipping them would orphan the fact on exactly the
	// screen it is most about.
	in_auth:               bool,

	// predicted spawns (spawn.odin): a client's own fired projectiles, tracked
	// under provisional ids until the authority's spawn arrives and rekeys them
	spawn_next:            u32, // provisional id counter (client-local, high-bit tagged)
	spawn_free:            Spawn_Free_Proc, // engine layer frees the node on despawn (nil on the core)
	spawn_free_user:       rawptr,

	// A watched entity becomes PRESENTABLE the tick the delayed watch clock
	// reaches its first ledgered pose — the moment a remote muzzle's projectile
	// should actually appear (in step with the delayed barrel that fired it),
	// not the earlier moment its spawn packet merely landed. The engine layer
	// hides the node until then, so a fresh watched spawn is revealed on cue
	// instead of sitting frozen at the muzzle through the render delay.
	present_ready:         Present_Ready_Proc, // nil on the core
	present_ready_user:    rawptr,
}

// Fired once per watched entity, the tick it first becomes presentable (the
// watch clock reaches its earliest ledgered tick). The engine layer reveals
// the node it created hidden.
Present_Ready_Proc :: proc(user: rawptr, id: knet.Net_Id, entity: rawptr)

// A filed SIM_FACT: an event tick's fact tuple, waiting for the watch clock.
@(private = "file")
Fact_In :: struct {
	tick: u64,
	id:   knet.Net_Id, // the anchor (NET_ID_INVALID = an anchorless world fact)
	kind: u16, // 0 = entity-tick fact (the anchor set's fx); else a Fact_Desc id
	args: []u8, // owned — the fact tuple, wire-encoded
}

// One sim-routed @(gd_event): its stable wire id (an FNV-1a hash of the event
// name — the command-id law: reordering declarations never
// renumbers the wire) and its decode thunk. scriptgen emits the package's
// table; the generated lane_init installs it.
Fact_Desc :: struct {
	id:       u16, // never 0 — kind 0 on the wire means "the anchor set's tick fx"
	audience: ksess.Net_Event_Audience,
	fx:       Fx_Thunk, // entity = the anchor (nil for an anchorless world fact)
}

// Install the package's declared-fact table — generated wiring, alongside
// lane_set_sim. Hand-built lanes (tests) may pass their own.
lane_set_facts :: proc(l: ^Lane, table: []Fact_Desc) {
	if lane_world_refuse(l) {return}
	l.fact_set = table
}

@(private = "file")
fact_fx :: proc(l: ^Lane, kind: u16) -> Fx_Thunk {
	for d in l.fact_set {
		if d.id == kind {
			return d.fx
		}
	}
	return nil
}

// The tracked owner of an entity — the seat driving it (PLAYER_ID_INVALID for
// contested/world entities and anything untracked). The generated fact doors
// derive `mine` from it; games may read it wherever the census hook's stamp
// isn't at hand.
lane_owner_of :: proc(l: ^Lane, entity: rawptr) -> knet.Player_Id {
	for &tr in l.tracked {
		if tr.entity == entity {
			return tr.owner
		}
	}
	return knet.PLAYER_ID_INVALID
}

// Does the lane still track `entity` — a body it knows (tracked, not yet
// untracked)? The pointer-keyed twin of spawn.odin's lane_tracks(id), for the
// call sites that hold the entity, not its id. lane_owner_of can't answer it:
// PLAYER_ID_INVALID is also what a tracked world/contested entity owns. The
// generated anchored fact doors
// gate on this FIRST, so a fact announced on a corpse (an entity the game
// already untracked/despawned) shows NOWHERE: lane_fact already skips the
// wire (nobody to tell), fire_facts already drops a filed fact whose anchor
// died, and without this gate the authority's own screen was the one place
// it still fired (mine=false through the door's authority clause) — a
// presentation nobody else gets, on exactly the screen the author watches,
// masking the real bug (a fact meant to be seen is announced BEFORE the
// despawn). Games may read it too, wherever a handle might outlive its body.
lane_tracks_entity :: proc(l: ^Lane, entity: rawptr) -> bool {
	for &tr in l.tracked {
		if tr.entity == entity {
			return true
		}
	}
	return false
}

// Resolve between the two stable identities a generated event needs. The
// anchor itself rides SIM_FACT's header; any additional typed entity
// parameters ride as Net_Id values in the event tuple and are resolved again
// when the receiving screen's watch clock presents the event.
lane_entity_id :: proc(l: ^Lane, entity: rawptr) -> (knet.Net_Id, bool) {
	for &tr in l.tracked {
		if tr.entity == entity {
			return tr.id, true
		}
	}
	return knet.NET_ID_INVALID, false
}

lane_entity :: proc(l: ^Lane, id: knet.Net_Id) -> (rawptr, bool) {
	for &tr in l.tracked {
		if tr.id == id {
			return tr.entity, true
		}
	}
	return nil, false
}

// The most unfired facts a client holds — an untrusted-input bound far above
// any honest burst (the watch clock drains the queue within a watch_delay).
@(private = "file")
FACT_QUEUE_CAP :: 256
FACT_ARGS_MAX_BYTES :: 4096

// Bind to a session (host or client, before or after it starts). The app
// ROUTE survives session re-init like every pre-start hookup — but lane
// STATE does not reset with the session: a lane that must follow a fresh
// authority (new ticks, new anchor) takes lane_destroy → lane_init, the
// reset story. `input_size` is the game's input struct size, identical on
// every peer by construction (the same compiled struct).
lane_init :: proc(
	l: ^Lane,
	ses: ^ksess.Session,
	input_size: int,
	tag := SIM_TAG,
	cfg := Lane_Config{},
	allocator := context.allocator,
) {
	assert(
		l.ses == nil,
		"lane_init on a live lane — lane_destroy first (re-init without teardown leaks every container and keeps a stale anchor)",
	)
	assert(
		cfg.hz >= 0 &&
		cfg.snap_every >= 0 &&
		cfg.slots >= 0 &&
		cfg.margin >= 0 &&
		cfg.redundancy >= 0 &&
		cfg.rewind_max >= 0 &&
		cfg.lead_max >= 0 &&
		cfg.watch_delay >= 0 &&
		cfg.smooth_halflife >= 0 &&
		cfg.smooth_cut >= 0 &&
		cfg.tolerance >= 0 &&
		cfg.snapshot_budget >= 0,
		"Lane_Config uses zero for defaults; negative timing, size, and tolerance values are invalid",
	)
	assert(cfg.slots == 0 || cfg.slots >= 2, "Lane_Config.slots must hold at least two ticks")
	l.allocator = allocator
	l.ses = ses
	l.tag = tag
	hz := cfg.hz > 0 ? cfg.hz : DEFAULT_SIM_HZ
	l.snap_every = cfg.snap_every > 0 ? cfg.snap_every : 3
	l.slots = max(cfg.slots > 0 ? cfg.slots : 128, 2)
	assert(l.snap_every < l.slots, "Lane_Config.snap_every must fit inside the tick ring")
	l.snap_every = clamp(l.snap_every, 1, l.slots - 1)
	l.margin = cfg.margin > 0 ? cfg.margin : 2
	l.redundancy = cfg.redundancy > 0 ? cfg.redundancy : INPUT_REDUNDANCY
	l.rewind_max = cfg.rewind_max > 0 ? cfg.rewind_max : max(hz / 4, 1)
	assert(l.margin < l.slots, "Lane_Config.margin must fit inside the tick ring")
	assert(
		l.redundancy <= MAX_INPUT_REDUNDANCY,
		"Lane_Config.redundancy exceeds MAX_INPUT_REDUNDANCY",
	)
	assert(l.rewind_max < l.slots, "Lane_Config.rewind_max must fit inside the tick ring")
	l.margin = clamp(l.margin, 1, l.slots - 1)
	l.redundancy = clamp(l.redundancy, 1, min(MAX_INPUT_REDUNDANCY, l.slots))
	l.rewind_max = clamp(l.rewind_max, 1, l.slots - 1)
	// A cold client can temporarily jump deep while shedding clock surplus
	// (especially before clock-sync RTT exists). Half the ring admits that
	// recovery path without allowing a tick to lap the authority's current slot.
	derived_lead_max := max(l.margin + l.rewind_max + 2 * l.snap_every, max(l.slots / 2, 8))
	l.lead_max = cfg.lead_max > 0 ? cfg.lead_max : derived_lead_max
	assert(l.lead_max < l.slots, "Lane_Config.lead_max must fit inside the tick ring")
	l.lead_max = clamp(l.lead_max, 1, l.slots - 1)
	l.watch_delay = cfg.watch_delay > 0 ? cfg.watch_delay : 2 * l.snap_every
	// The render offset rides the wire in EIGHTHS of a tick in one byte
	// (render_off8): 31 ticks is the most a screen can DECLARE. A config past
	// it would make every rewind judge shallow — refuse while a dev is
	// looking, clamp where asserts are stripped (stat_render_sat still counts
	// the saturation there).
	assert(
		l.watch_delay <= 31,
		"Lane_Config.watch_delay exceeds the 31-tick render-offset wire ceiling (render_off8)",
	)
	assert(l.watch_delay < l.slots, "Lane_Config.watch_delay must fit inside the tick ring")
	l.watch_delay = clamp(l.watch_delay, 1, min(31, l.slots - 1))
	l.smooth_halflife = cfg.smooth_halflife > 0 ? cfg.smooth_halflife : 0.063
	l.smooth_cut = cfg.smooth_cut
	l.judge_live = cfg.judge_live
	l.echo_on = cfg.echo_inputs
	l.echo = make(map[Echo_Key][]u8, allocator)
	l.tolerance = cfg.tolerance
	l.snapshot_budget = cfg.snapshot_budget
	assert(
		l.snapshot_budget == 0 || l.snapshot_budget >= SNAP_HEADER_BYTES,
		"Lane_Config.snapshot_budget must fit the fixed snapshot header",
	)
	if l.echo_on && l.tolerance == 0 {
		// Predict-world without slack: every held-input drift mismatches the
		// exact compare and buys a full resim — nearly every batch. Legal but
		// never what anyone means; one line at init beats a silent CPU tax.
		// (Native only: the wasm fmt has no stdio — println doesn't exist
		// there, and this line broke the whole web build once.)
		when ODIN_OS != .Freestanding {
			fmt.println(
				"kit/sim: echo_inputs with tolerance=0 resims on nearly every batch — set Lane_Config.tolerance (world units of acceptable held-input drift)",
			)
		}
	}
	l.ticker = sim_ticker_make(hz)
	l.tracked = make([dynamic]Tracked, allocator)
	l.entries = make([dynamic]Entry, allocator)
	l.inputs = make([dynamic]Input_Class, allocator)
	if input_size > 0 {
		// The primary input class (id 0). lane_set_sim attaches its sample;
		// extra classes ride lane_add_input_class; its TYPE (for lane_input_of)
		// is stamped by lane_class_set_type — the generated lane_init does so.
		lane_class_add(l, 0, input_size, nil, allocator)
	}
	l.rx = snap_rx_make(l.slots, allocator)
	l.pending = make([dynamic]u8, allocator)
	l.peers = make(map[knet.Player_Id]^Lane_Peer, allocator)
	l.wound = make([dynamic]Wound, allocator)
	l.cmd_out = make([dynamic]Cmd_Out, allocator)
	l.cmd_in = make([dynamic]Cmd_In, allocator)
	l.facts = make([dynamic]Fact_In, allocator)
	ksess.session_app_route(ses, tag, l, lane_handle)
}

// Register an ADDITIONAL input class beyond lane_init's primary (id 0) — a
// second entity kind the same player drives, with its own input struct. The
// generated <class>_lane_init emits one per extra @(gd_tick) input type; a
// hand-built lane calls it right after lane_init. `id` must be unique and
// agree with the Sim_Set.input_class the tracked entities of that kind carry.
lane_add_input_class :: proc(
	l: ^Lane,
	id: u16,
	size: int,
	sample: Sample_Proc,
	allocator := mem.Allocator{},
) {
	if lane_world_refuse(l) {return}
	assert(id != 0, "class 0 is lane_init's primary input — pass its size to lane_init")
	assert(size > 0, "an input class needs a non-zero size (inputless entities take no class)")
	lane_class_add(l, id, size, sample, allocator)
}

// Record a registered class's input STRUCT TYPE, so lane_input_of can name its
// class by type instead of by size (two kinds can share a size after a field
// add). The generated <game>_lane_init stamps every class right after it
// registers; a hand-built lane may stamp its own or leave them size-resolved.
// A `typeid` parameter can't carry a nil default in this Odin, which is why this
// is a separate stamp rather than an argument on lane_init/lane_add_input_class
// — and keeping it separate leaves the teaching signatures of those two clean.
lane_class_set_type :: proc(l: ^Lane, id: u16, type: typeid) {
	if lane_world_refuse(l) {return}
	ic := lane_class(l, id)
	assert(ic != nil, "lane_class_set_type: no input class with this id — register it first")
	// Two classes claiming one type is no better a key than the size it replaced
	// (distinct types of the same SIZE are exactly what this resolves).
	other := class_for_type_exact(l, type)
	assert(
		other == nil || other == ic,
		"two input classes share an input struct type — each kind needs its own",
	)
	ic.type = type
}

// Install semantic admission for one input class. Generated lane wiring calls
// this for `@(gd_sample="validate")`; hand-built lanes can use it directly.
lane_class_set_validate :: proc(l: ^Lane, id: u16, validate: Input_Validate_Proc) {
	if lane_world_refuse(l) {return}
	ic := lane_class(l, id)
	assert(ic != nil, "lane_class_set_validate: no input class with this id — register it first")
	ic.validate = validate
}

@(private = "file")
lane_class_add :: proc(
	l: ^Lane,
	id: u16,
	size: int,
	sample: Sample_Proc,
	allocator := mem.Allocator{},
) {
	if lane_world_refuse(l) {return}
	// Zero allocator (the default at every layer) = the LANE'S — these
	// containers free in lane_destroy under l.allocator, and an ambient
	// default here silently mismatched them for custom-allocator lanes.
	allocator := allocator.procedure != nil ? allocator : l.allocator
	assert(lane_class(l, id) == nil, "input class id registered twice")
	assert(
		len(l.inputs) < MAX_INPUT_CLASSES_PER_SEAT,
		"a sim lane exceeds MAX_INPUT_CLASSES_PER_SEAT — combine related intent into one @(gd_input) struct",
	)
	ic := Input_Class {
		id     = id,
		size   = size,
		sample = sample,
	}
	if size > 0 {
		ic.ring = input_ring_make(size, l.slots, allocator)
		ic.scratch = make([]u8, size, allocator)
	}
	append(&l.inputs, ic)
	lane_assert_input_packet_bound(l)
}

// Exact worst-case size of the client→host SIM_INPUT payload for the classes
// this build samples: kind + snap ack + render offset + class count, then each
// class id + fixed window header + `redundancy` blobs.
@(private = "file")
lane_input_packet_bound :: proc(l: ^Lane) -> int {
	n := 1 + 8 + 1 + 1
	for &ic in l.inputs {
		if ic.sample != nil && ic.size > 0 {
			n += 2 + 8 + 1 + 2 + l.redundancy * ic.size
		}
	}
	return n
}

@(private = "file")
lane_assert_input_packet_bound :: proc(l: ^Lane) {
	assert(
		lane_input_packet_bound(l) <= MAX_INPUT_PACKET_BYTES,
		"sampled input classes exceed MAX_INPUT_PACKET_BYTES at this redundancy — reduce fields/classes or Lane_Config.redundancy",
	)
}

// The one constructor for host-side per-seat simulation state. Snapshot issue,
// input admission, and command dedup must share its lifetime or a command sent
// before the first input could bypass replay protection.
@(private)
lane_peer_ensure :: proc(l: ^Lane, player: knet.Player_Id) -> ^Lane_Peer {
	if p, ok := l.peers[player]; ok {
		return p
	}
	p := new(Lane_Peer, l.allocator)
	p.bufs = make(map[u16]^Input_Buffer, l.allocator)
	p.snap_sent = make(map[knet.Net_Id]u64, l.allocator)
	l.peers[player] = p
	return p
}

// An acknowledgement is useful only if the authority actually issued that
// batch during this seat lifetime. Keep a finite age too: an ancient but real
// tick is safe as a delta baseline in theory, but accepting it lets a delayed or
// hostile packet keep claiming evidence outside this lane's useful horizon.
@(private = "file")
peer_snap_ack_valid :: proc(l: ^Lane, p: ^Lane_Peer, ack: u64) -> bool {
	if ack == 0 {
		return p.acked == 0
	}
	if p.snap_first == 0 ||
	   ack < p.snap_first ||
	   ack > p.snap_last ||
	   ack < p.acked ||
	   ack % u64(l.snap_every) != 0 {
		return false
	}
	max_age := u64(min(l.slots - 1, l.margin + 2 * l.rewind_max + 4 * l.snap_every))
	return p.snap_last - ack <= max_age
}

@(private)
lane_class :: proc(l: ^Lane, id: u16) -> ^Input_Class {
	for &ic in l.inputs {
		if ic.id == id {
			return &ic
		}
	}
	return nil
}

// The class that registered exactly `type`, or nil — the exact-match half of
// class_for_type, split out so lane_class_add can assert uniqueness with it.
@(private = "file")
class_for_type_exact :: proc(l: ^Lane, type: typeid) -> ^Input_Class {
	for &ic in l.inputs {
		if ic.type != nil && ic.type == type {
			return &ic
		}
	}
	return nil
}

// The class lane_input_of means when handed a typed T. Resolves by TYPE first —
// scriptgen records every class's input typeid, so the common case is exact and
// unambiguous even when two kinds share a size (the footgun this replaced: add a
// field to one input struct until it matches another's size, and the old
// size-keyed resolver asserted or, worse, silently picked the wrong class). A
// hand-built lane that registered no type falls back to size, which is
// unambiguous only if no two classes share it — the old behaviour, kept for
// consumers who never gave a type to resolve by.
@(private = "file")
class_for_type :: proc(l: ^Lane, type: typeid, size: int) -> u16 {
	if ic := class_for_type_exact(l, type); ic != nil {
		return ic.id
	}
	id: u16
	n := 0
	for &ic in l.inputs {
		if ic.size == size {
			id = ic.id
			n += 1
		}
	}
	assert(
		n == 1,
		"lane_input_of: input size ambiguous across classes and no type recorded — use lane_input with an explicit class id, or register the class with its type (the generated lane_init does)",
	)
	return id
}

lane_destroy :: proc(l: ^Lane) {
	if lane_world_busy(l) {lane_world_refuse(l); return}
	if l.world != nil {_ = lane_world_detach(l)}
	if l.allocator.procedure != nil {
		context.allocator = l.allocator // free under what allocated (a zero lane keeps ambient)
	}
	if l.ses != nil {
		ksess.session_app_route(l.ses, l.tag, nil, nil)
	}
	for &tr in l.tracked {
		if tr.hist != nil {
			history_destroy(tr.hist)
			free(tr.hist)
		}
		delete(tr.err)
	}
	delete(l.tracked)
	delete(l.entries)
	for &ic in l.inputs {
		if ic.size > 0 {
			input_ring_destroy(&ic.ring)
			delete(ic.scratch)
		}
	}
	delete(l.inputs)
	snap_rx_destroy(&l.rx)
	delete(l.pending)
	for _, p in l.peers {
		for _, buf in p.bufs {
			input_buffer_destroy(buf)
			free(buf)
		}
		delete(p.bufs)
		delete(p.snap_sent)
		free(p)
	}
	delete(l.peers)
	for _, blob in l.echo {
		delete(blob)
	}
	delete(l.echo)
	delete(l.wound)
	for &c in l.cmd_out {
		cmd_out_free(&c)
	}
	delete(l.cmd_out)
	for c in l.cmd_in {
		delete(c.args)
	}
	delete(l.cmd_in)
	for f in l.facts {
		delete(f.args)
	}
	delete(l.facts)
	// A destroyed lane is a ZERO lane: destroy → lane_init is the reset
	// story (a re-keyed authority, back-to-lobby). Without the wipe, stale
	// anchor/rx state would drop every batch from a fresh-tick authority
	// forever, and a double init would silently leak the first containers.
	l^ = {}
}

// The game procs. `sample` may be nil on a seat that plays nobody (a
// dedicated server). Up to TWO world passes, either nil, both run after the
// entity thunks:
//
//   `step`      runs EVERYWHERE, live and resim alike — the PURE-SIM pass
//               (contact for pairs this peer has inputs for). With
//               lane_track_set entities it's often nil: entity thunks carry
//               the per-entity simulation, the step keeps only cross-entity work.
//   `step_auth` runs on the AUTHORITY alone — the role gate an authority-work
//               pass (respawn queues, adjudication sweeps, a match clock) used
//               to open with by hand. The host never resims, so it fires once
//               per real tick. A game needing both keeps them separate instead
//               of folding `if lane_is_authority()` into one pass.
lane_set_sim :: proc(
	l: ^Lane,
	user: rawptr,
	sample: Sample_Proc,
	step: Step_Proc = nil,
	step_auth: Step_Proc = nil,
) {
	if lane_world_refuse(l) {return}
	l.user = user
	l.step = step
	l.step_auth = step_auth
	if sample != nil {
		// The sample fills the primary class (id 0). A game with extra input
		// kinds passes their samples through lane_add_input_class.
		if ic := lane_class(l, 0); ic != nil {
			ic.sample = sample
			lane_assert_input_packet_bound(l)
		} else {
			assert(
				false,
				"lane_set_sim: a sample needs an input class — pass input_size > 0 to lane_init",
			)
		}
	}
}

// Put an entity on the sim lane — call where the entity is born on this peer
// (the factory / Ev_Spawned handler), with the owner from the spawn. The one
// role decision the lane makes lives here: the authority ledgers truth for
// everyone; a client ledgers predictions for its OWN entities and merely
// watches the rest (their truth lands from batches; lane_present draws them
// on the delayed watch clock, blending bracketing batches per field).
lane_track :: proc(
	l: ^Lane,
	id: knet.Net_Id,
	entity: rawptr,
	desc: ^knet.Entity_Desc,
	owner: knet.Player_Id,
	allocator := mem.Allocator{},
) {
	if lane_world_refuse(l) {return}
	allocator := allocator.procedure != nil ? allocator : l.allocator // zero = the lane's (see lane_class_add)
	assert(
		!l.rewound,
		"lane_track inside a rewound block — the restore holds pointers into the track list; lane_rewound_end first",
	)
	assert(
		predict_size(desc) > 0,
		"lane_track: entity predicts nothing — tag fields gd:\"predict\"",
	)
	assert(
		predict_wire_size(desc) <= int(max(u16)),
		"lane_track: predicted wire state exceeds the snapshot row's u16 length",
	)
	assert(
		l.snapshot_budget == 0 ||
		SNAP_HEADER_BYTES + SNAP_ROW_HEADER_BYTES + predict_wire_size(desc) <= l.snapshot_budget,
		"lane_track: Lane_Config.snapshot_budget cannot fit one full row for this entity type",
	)
	if l.ses.is_host {
		hist := new(History, allocator)
		hist^ = history_make(desc, l.slots, allocator)
		append(
			&l.tracked,
			Tracked{id = id, entity = entity, desc = desc, owner = owner, hist = hist},
		)
		append(&l.entries, Entry{id = id, entity = entity, hist = hist})
		return
	}
	snap_rx_add(&l.rx, id, desc, allocator)
	if owner == l.ses.me {
		hist := new(History, allocator)
		hist^ = history_make(desc, l.slots, allocator)
		append(
			&l.tracked,
			Tracked{id = id, entity = entity, desc = desc, owner = owner, hist = hist},
		)
		append(&l.entries, Entry{id = id, entity = entity, hist = hist})
	} else {
		append(
			&l.tracked,
			Tracked{id = id, entity = entity, desc = desc, owner = owner, watched = true},
		)
	}
}

// lane_track with the generated Sim_Set: the entity now DRIVES ITSELF — its
// tick thunk runs every simulated tick (live and resim alike) with its
// owner's input, in track order, before the game's world pass. This is the
// call the scriptgen surface reduces the game to:
//
//     ksim.lane_track_set(&self.lane, id, runner, &runner_sim_set, owner)
//
// Each input-driven set names its input CLASS (Sim_Set.input_class) — the id
// its window rides on the wire. That class must be registered (lane_init's
// primary or a lane_add_input_class extra) and agree on size; a player driving
// two entity KINDS ships one window per class each tick.
lane_track_set :: proc(
	l: ^Lane,
	id: knet.Net_Id,
	entity: rawptr,
	set: ^Sim_Set,
	owner: knet.Player_Id,
	allocator := mem.Allocator{},
) {
	if lane_world_refuse(l) {return}
	allocator := allocator.procedure != nil ? allocator : l.allocator // zero = the lane's (see lane_class_add)
	assert(set.tick != nil, "lane_track_set: a Sim_Set carries the tick entry point")
	if set.input_size > 0 {
		ic := lane_class(l, set.input_class)
		assert(
			ic != nil && ic.size == set.input_size,
			"lane_track_set: this set's input class is unregistered or its size disagrees — register it with lane_init/lane_add_input_class",
		)
	}
	for &cmd in set.commands {
		assert(
			cmd.action.model == .Scheduled,
			"lane_track_set: sim actions declare model=.Scheduled",
		)
		assert(
			knet.action_desc_valid(cmd.action, .Scheduled),
			"lane_track_set: invalid scheduled action descriptor",
		)
		assert(cmd.exec != nil, "lane_track_set: each action needs one typed exec thunk")
	}
	lane_track(l, id, entity, set.entity_desc, owner, allocator)
	tr := &l.tracked[len(l.tracked) - 1]
	tr.tick = set.tick
	tr.has_in = set.input_size > 0
	tr.in_class = set.input_class
	tr.cmds = set.commands
	tr.set = set
	if set.contested && tr.watched {
		// Contested: this client predicts it like its own — ledger, entries,
		// reconcile — instead of watching it from the past. PRESENTATION
		// stays claim-weighted (lane_present): the predicted timeline while
		// MY sim drives it, the watched view otherwise — so a remote touch
		// lands beside the remote avatar that made it, not a lead early.
		tr.watched = false
		tr.contested = true
		tr.hist = new(History, allocator)
		tr.hist^ = history_make(tr.desc, l.slots, allocator)
		append(&l.entries, Entry{id = id, entity = entity, hist = tr.hist})
	}
}

// MY simulation is influencing this contested entity right now — touching
// it, inside reach of it, just kicked it. Call it every tick the influence
// holds (the world pass's contact block is the natural spot): the claim
// rises INSTANTLY, so your first touch presents from your predicted
// timeline with zero delay, and decays over ~a quarter second once the
// influence stops, easing the entity back onto the watched view. This is
// net.md's "did MY simulation cause this?" boolean — the one fact the lane
// cannot derive — asked continuously.
lane_claim :: proc(l: ^Lane, id: knet.Net_Id) {
	if lane_world_refuse(l) {return}
	for &tr in l.tracked {
		if tr.id == id {
			tr.claim = 1
			return
		}
	}
}

// How strongly `id` presents from MY predicted timeline right now: 1 while my sim
// is claiming it (lane_claim this tick), decaying to 0 over ~a quarter second
// after the influence stops (then it draws the watched view). A read of the same
// weight lane_present blends by — for a claim-mode game's own telemetry (a
// netgraph tint, a debug overlay) or an acid proving the claim rose on a touch.
lane_claimed :: proc(l: ^Lane, id: knet.Net_Id) -> f32 {
	for &tr in l.tracked {
		if tr.id == id {
			return tr.claim
		}
	}
	return 0
}

// Broadcast a fact to every screen that didn't simulate it live — the
// generated thunks (an entity tick's mine-form `_fx` or a sim-routed
// @(gd_event) door) call this on the authority. Reliable (events are one-shots, like
// verdicts). Receivers file it and fire the matching fx thunk when their
// watch clock reaches `l.step_tick` — beside the delayed avatar that caused
// it. `kind` 0 = an entity-tick fact (routed to the anchor set's fx); a
// declared fact ships its Fact_Desc id. `entity` nil = an anchorless world
// fact (kind facts only) — no owner, everyone watches.
//
// The owner skip is PROVENANCE-AWARE: a fact from the everywhere pass skips
// the anchor's owner (their own live pass just presented it, mine=true, and
// the echo would double the flash) — but a fact minted in the AUTHORITY pass
// (l.in_auth) includes them, because their everywhere pass never ran the
// code that announced it.
//
// THE TRADE the everywhere-pass skip makes, named so it is not rediscovered as
// a bug: it ASSUMES the owner's own everywhere pass fired the same fact from the
// same input. True in the common case — the owner's input reached the host and
// both passes ran it — but it BREAKS under input loss on the firing tick: the
// host, missing that packet, HELD the owner's last input and its everywhere pass
// fired the fact from the extrapolation, while the owner's client ran its own
// FRESH input and may not have fired it. Skipped, the owner then never sees that
// one-shot. It stays a skip, not a detect, on purpose: including the owner
// whenever their input was held would DOUBLE-flash the (far more common) case
// where the held input fired the same fact on both sides — a rare miss traded
// for a rare double, no clear win, and facts are cosmetic one-shots the
// "friends, not forensics" stance already lets loss drop. The guarantee, when a
// game needs it (a fact the owner MUST see regardless of loss): fire it from the
// AUTHORITY pass instead of the everywhere pass — l.in_auth includes them by the
// rule above. That is the knob, not a flag on this call.
lane_fact :: proc(l: ^Lane, entity: rawptr, args: []u8, kind: u16 = 0) {
	if lane_world_refuse(l) {return}
	assert(
		l.ses.is_host,
		"facts broadcast from the authority — the generated thunk holds this gate",
	)
	assert(
		len(args) <= FACT_ARGS_MAX_BYTES,
		"fact payload exceeds FACT_ARGS_MAX_BYTES — facts are presentation tuples, not bulk messages",
	)
	id := knet.NET_ID_INVALID
	owner := knet.PLAYER_ID_INVALID
	if entity != nil {
		for &tr in l.tracked {
			if tr.entity == entity {
				id = tr.id
				owner = tr.owner
				break
			}
		}
		if id == knet.NET_ID_INVALID {
			// Untracked (mid-despawn): nobody left to tell. The generated doors
			// gate on lane_tracks_entity before reaching here, so their local
			// showing is skipped too; this is the belt for a hand-written caller.
			return
		}
	} else {
		assert(
			kind != 0,
			"an entity-tick event always has its entity — nil anchors belong to anchorless @(gd_event) doors",
		)
	}
	skip := l.in_auth ? knet.PLAYER_ID_INVALID : owner
	audience := ksess.Net_Event_Audience.Everyone
	if kind != 0 {
		for d in l.fact_set {
			if d.id == kind {
				audience = d.audience
				break
			}
		}
	}
	for p in ksess.session_roster(l.ses) {
		if !p.connected || p.id == l.ses.me {
			continue
		}
		is_owner := owner != knet.PLAYER_ID_INVALID && p.id == owner
		include := false
		switch audience {
		case .Everyone:
			include = skip == knet.PLAYER_ID_INVALID || p.id != skip
		case .Owner:
			// An everywhere-pass event already fired on the owner's live
			// simulation. Authority-pass events did not, so include it there.
			include = is_owner && l.in_auth
		case .Observers:
			include = !is_owner
		}
		if !include {continue}
		w := ksess.session_app_begin(l.ses, l.tag)
		knet.write_u8(w, SIM_FACT)
		knet.write_u64(w, l.step_tick)
		knet.write_net_id(w, id)
		knet.write_u16(w, kind)
		knet.write_bytes(w, args)
		ksess.session_app_flush(l.ses, p.peer) // reliable: facts are one-shots
	}
}

lane_untrack :: proc(l: ^Lane, id: knet.Net_Id) -> bool {
	if lane_world_refuse(l) {return false}
	assert(
		!l.rewound,
		"lane_untrack inside a rewound block — the restore holds pointers into the track list; lane_rewound_end first",
	)
	// Reliable commands can arrive before a despawn/untrack event is drained.
	// Retire both authority and prediction ledgers now; no queued verb may later
	// execute against a recycled id or keep an owned argument buffer alive.
	cmd_forget_entity(l, id)
	for _, peer in l.peers {
		delete_key(&peer.snap_sent, id)
	}
	if !l.ses.is_host {
		snap_rx_remove(&l.rx, id)
	}
	for &e, i in l.entries {
		if e.id == id {
			ordered_remove(&l.entries, i)
			break
		}
	}
	for &tr, i in l.tracked {
		if tr.id == id {
			if tr.hist != nil {
				history_destroy(tr.hist)
				free(tr.hist)
			}
			delete(tr.err)
			ordered_remove(&l.tracked, i)
			return true
		}
	}
	return false
}

// Sim-lane ownership transfer — possession, the carry, the ball changing
// hands. LOCAL state transition only: the session already broadcasts the
// authoritative Ev_Owner_Changed on the reliable lane; every peer forwards
// it here (the host too — its call is what flips whose input buffer drives
// the entity and whom rewound queries spare). On a client the entity swaps
// prediction modes: gaining it starts a fresh ledger seeded from the newest
// received truth (predictions begin next tick — a one-lead-deep resim later
// corrects the seam); losing it drops the ledger and the entity becomes
// watched, presented from batches like everyone else's.
lane_set_owner :: proc(
	l: ^Lane,
	id: knet.Net_Id,
	owner: knet.Player_Id,
	allocator := mem.Allocator{},
) -> bool {
	allocator := allocator.procedure != nil ? allocator : l.allocator // zero = the lane's (see lane_class_add)
	for &tr, i in l.tracked {
		if tr.id != id {
			continue
		}
		if tr.owner == owner {
			return true
		}
		tr.owner = owner
		if l.ses.is_host {
			return true // truth ledgers don't care who steers
		}
		gaining := owner == l.ses.me
		if gaining {
			tr.contested = false // mine now: the predicted timeline, no claim dance
		}
		if gaining && tr.watched {
			tr.watched = false
			// Mine now: a predicted entity is shown at once. If the reveal-gate
			// still had it hidden (a possession handed over during its first
			// render-delay of life, before the watched present loop uncovered
			// it), uncover it here — that loop no longer runs for it.
			if l.present_ready != nil {
				l.present_ready(l.present_ready_user, id, tr.entity)
			}
			tr.hist = new(History, allocator)
			tr.hist^ = history_make(tr.desc, l.slots, allocator)
			if e := find_rx(&l.rx, id); e != nil {
				if blob, ok := history_read(&e.hist, l.rx.newest); ok {
					predict_restore(tr.entity, tr.desc, blob)
					history_note_bytes(tr.hist, l.ticker.tick, blob) // the seam's baseline
				}
			}
			append(&l.entries, Entry{id = id, entity = tr.entity, hist = tr.hist})
		} else if !gaining && !tr.watched {
			for &e, j in l.entries {
				if e.id == id {
					ordered_remove(&l.entries, j)
					break
				}
			}
			history_destroy(tr.hist)
			free(tr.hist)
			tr.hist = nil
			delete(tr.err)
			tr.err = nil
			tr.watched = true
		}
		_ = i
		return true
	}
	return false
}

// A departed player's input state. kboot's event drain forwards
// Ev_Player_Left here (the same no-game-ever-forgets rule as ownership
// moves); hand-driven sessions call it from their own handler — skipping it
// leaks a few KB per departed seat and keeps popping their buffers per tick.
lane_drop_player :: proc(l: ^Lane, player: knet.Player_Id) {
	if lane_world_refuse(l) {return}
	if lane_world_refuse(l) {return}
	context.allocator = l.allocator
	cmd_forget_player(l, player)
	if p, ok := l.peers[player]; ok {
		for _, buf in p.bufs {
			input_buffer_destroy(buf)
			free(buf)
		}
		delete(p.bufs)
		delete(p.snap_sent)
		free(p)
		delete_key(&l.peers, player)
	}
}

// The input driving `player`'s entities of `class` for the tick being stepped
// — valid ONLY inside your Step_Proc (live or resim, same answer). ok=false
// means no input exists here for that player+class this tick: a client asking
// about remote players (predict-self — coast them, their truth is on the way),
// a held gap on the host (the returned bytes then repeat their last real
// input). `class` defaults to 0, the single-input lane's only class.
lane_input :: proc(l: ^Lane, player: knet.Player_Id, class: u16 = 0) -> (input: []u8, ok: bool) {
	if l.world != nil && l.world.network != nil {return world_net_input(l, player, class)}
	if player == l.ses.me {
		if ic := lane_class(l, class); ic != nil && ic.size > 0 {
			return input_read(&ic.ring, l.step_tick)
		}
		return nil, false
	}
	if l.ses.is_host {
		if p, found := l.peers[player]; found {
			if buf, has := p.bufs[class]; has {
				return buf.held, buf.fresh
			}
		}
		return nil, false
	}
	if l.echo_on {
		// Predict-world: a remote player's LAST-KNOWN input for this class (the
		// batch echo) — held, never fresh; the extrapolation every peer ticks
		// remotes with, corrected by the next batch's truth.
		if held, found := l.echo[Echo_Key{player, class}]; found {
			return held, false
		}
	}
	return nil, false
}

// The typed view of lane_input, for the world pass:
//
//	input, drives := ksim.lane_input_of(&g.lane, owner, Kicker_Input)
//	if !drives {continue} // a pair this peer doesn't simulate
//
// `drives` means an input EXISTS to drive with — held gaps repeat the last
// real one, because driving through loss is the point; the raw lane_input's
// ok is the FRESHNESS bit, for the rare caller that cares. The class is
// resolved from T's TYPE (scriptgen records it at registration), so two input
// kinds that happen to share a size no longer collide; a hand-built lane that
// registered no type falls back to size and must call lane_input with an
// explicit id if two kinds share one.
lane_input_of :: proc(l: ^Lane, player: knet.Player_Id, $T: typeid) -> (input: T, drives: bool) {
	bytes, _ := lane_input(l, player, class_for_type(l, T, size_of(T)))
	if bytes == nil {
		return {}, false
	}
	assert(len(bytes) == size_of(T), "lane_input_of: not this lane's input struct (size mismatch)")
	return (cast(^T)raw_data(bytes))^, true
}

// The tick being stepped — for tick procs that derive per-tick values
// (ksim RNG seeds, cooldown arithmetic) without touching a wall clock.
lane_now :: proc(l: ^Lane) -> u64 {
	return l.step_tick
}

// Accessors for GENERATED thunk routing (games rarely need them): the sim
// hookup's user pointer (the game — `<tick>_then`/`<tick>_fx` receive it
// typed), whether this peer is the authority, and who this peer is.
lane_game :: proc(l: ^Lane) -> rawptr {
	return l.user
}

lane_is_authority :: proc(l: ^Lane) -> bool {
	return l.ses.is_host
}

lane_me :: proc(l: ^Lane) -> knet.Player_Id {
	return l.ses.me
}

// lane_lead — the client's WORKING LEAD in ticks: how far its predicted head
// runs ahead of the server's newest input ack. The headroom the whole model
// rests on (inputs for tick T must land just before the server sims T); a
// healthy lead hovers near Lane_Config.margin, a starved one dips toward zero
// under a spike. Zero on the host (it IS the server) and before the first
// batch anchors the client. A netgraph datum — see kit/ui/netgraph.
lane_lead :: proc(l: ^Lane) -> int {
	if l.world != nil {return l.ses.is_host ? 0 : int(l.world.head - l.world.confirmed)}
	if l.ses.is_host || l.input_ack == 0 {
		return 0
	}
	return int(l.ticker.tick) - int(l.input_ack)
}

// One stable operational read for dashboards, logs, and benchmark harnesses.
// It deliberately aggregates private per-seat rings here so applications do
// not need to understand Lane_Peer or duplicate host/client interpretations.
Lane_Net_Stats :: struct {
	lead:                int,
	input_gaps:          u64,
	ack_age:             int,
	rewind_depth:        int,
	resim_ticks:         int,
	resim_seconds:       f64,
	command_queue:       int,
	command_rejected:    int,
	snapshot_rows:       int,
	snapshot_full:       int,
	snapshot_delta:      int,
	snapshot_suppressed: int,
	snapshot_deferred:   int,
	aoi_culled:          int,
	snapshot_bytes:      int,
}

lane_net_stats :: proc(l: ^Lane) -> Lane_Net_Stats {
	stats := Lane_Net_Stats {
		lead                = lane_lead(l),
		resim_ticks         = l.stat_resims,
		resim_seconds       = l.stat_resim_seconds,
		command_queue       = len(l.cmd_in) + len(l.cmd_out),
		command_rejected    = l.stat_cmd_rejected + l.stat_cmd_capped + l.stat_cmd_rate_dropped,
		snapshot_rows       = l.stat_snap_rows,
		snapshot_full       = l.stat_snap_full,
		snapshot_delta      = l.stat_snap_delta,
		snapshot_suppressed = l.stat_snap_suppressed,
		snapshot_deferred   = l.stat_snap_deferred,
		aoi_culled          = l.stat_snap_aoi_culled,
		snapshot_bytes      = l.stat_snap_bytes,
	}
	if l.ses.is_host {
		for player, p in l.peers {
			for _, buf in p.bufs {
				stats.input_gaps += buf.held_count
			}
			if p.snap_last >= p.acked {
				stats.ack_age = max(stats.ack_age, int(p.snap_last - p.acked))
			}
			stats.rewind_depth = max(stats.rewind_depth, lane_rewind_envelope(l, player))
		}
	} else if l.rx.newest >= l.rx.acked {
		stats.ack_age = int(l.rx.newest - l.rx.acked)
	}
	return stats
}

// lane_live — is this the LIVE pass, whose side effects should fire ONCE
// (prints, sounds, particles), as opposed to a resim replay of history? The
// gate every game hand-wrote as `!lane.resimming` inside tick and step
// bodies. Entity-tick facts get it FREE through their `_fx` halves (the
// generated thunk holds this gate); inline presentation in a tick body or a
// world pass (@(gd_step)) reads it here — never the raw field.
lane_live :: proc(l: ^Lane) -> bool {
	return l.world != nil && l.world.presenting ? true : !l.resimming && !lane_world_busy(l)
}

// ---------------------------------------------------------------------------
// The frame drive.

// Advance the sim lane; call once per frame beside session_tick. Returns how
// many sim ticks ran. A client returns 0 until the first batch anchors it to
// the server's timeline.
lane_frame :: proc(l: ^Lane, dt: f64) -> int {
	context.allocator = l.allocator // lane work rides the lane's allocator (see the field)
	if l.world != nil {return world_frame(l, dt)}
	if l.ses.is_host {
		return host_frame(l, dt)
	}
	return client_frame(l, dt)
}

// One simulated tick, everywhere ticks happen — the live host loop, the live
// client loop, and the resim replay all funnel here so an entity can never
// behave differently between a prediction and its replay. Entity thunks
// first (track order — deterministic per peer because spawns ride the
// reliable ordered channel), then the game's world pass.
@(private)
run_tick :: proc(l: ^Lane, t: u64) {
	l.step_tick = t
	// Index-based, re-fetching each iteration: a tick's _fx/_then may SPAWN a
	// projectile (lane_spawn_predicted / lane_track_set), which appends to
	// l.tracked and can REALLOCATE it — a `for &tr` pointer would dangle. A
	// freshly appended entity is born THIS tick, so the born gate below skips it.
	for i := 0; i < len(l.tracked); i += 1 {
		tr := &l.tracked[i]
		if tr.tick == nil || tr.watched {
			continue
		}
		if tr.born != 0 && t <= tr.born {
			// Not born yet, or the spawn tick itself (which holds the unticked
			// spawn state — a predicted spawn is created AFTER the thunk pass, in
			// run_cmds). During a resim that crosses the spawn, reseed from the
			// ledger so flight restarts from the spawn state, not the stale head
			// a failed rewind left behind.
			if l.resimming && t == tr.born && tr.hist != nil {
				history_restore(tr.hist, tr.born, tr.entity)
			}
			continue
		}
		in_ptr: rawptr
		if tr.has_in {
			if in_bytes, _ := lane_input(l, tr.owner, tr.in_class); in_bytes != nil {
				in_ptr = raw_data(in_bytes)
			}
		}
		tr.tick(tr.entity, in_ptr, l, tr.owner)
	}
	// Tick-scheduled verbs: after entity thunks, before the world pass —
	// ticks integrate, verbs mutate the settled state, the world pass
	// adjudicates (command.odin).
	run_cmds(l, t)
	// The everywhere pass first (contact settles), then the authority pass
	// reads that settled state to adjudicate. The host is never resimming, so
	// its authority pass fires exactly once per real tick. The in_auth flag
	// marks the pass for lane_fact's provenance-aware owner skip.
	if l.step != nil {
		l.step(l.user, t)
	}
	if l.world != nil {
		w := l.world
		if w.status != .Ok {return}
		w.status = world_admit(l, w.candidate, 0, 0, 0, 0, true)
		if w.status != .Ok {return}
		w.status = w.provider.step(w.provider.user, w.candidate, t)
		if w.status != .Ok {return}
		if w.config.settle != nil {w.config.settle(l.user, t)}
	}
	if l.step_auth != nil && l.ses.is_host {
		l.in_auth = true
		l.step_auth(l.user, t)
		l.in_auth = false
	}
}

// Sample every input class this seat plays (each with a sample proc), noting
// the result into that class's ring — the local half of prediction. Runs on
// both the host (for its own avatar) and the client. A class the seat doesn't
// actually drive still samples harmlessly (neutral bytes drive nothing), which
// keeps the wire shape identical on every peer.
@(private)
sample_inputs :: proc(l: ^Lane, t: u64) {
	for &ic in l.inputs {
		if ic.sample != nil && ic.size > 0 {
			// A sampler commonly writes only active fields. Neutralize the whole
			// POD first so an omitted button/axis never inherits its previous tick.
			mem.zero(raw_data(ic.scratch), len(ic.scratch))
			ic.sample(l.user, t, raw_data(ic.scratch))
			if ic.validate != nil && !ic.validate(l.user, raw_data(ic.scratch)) {
				// A bad local device sample predicts neutral and ships neutral. The
				// authority applies the same validator to received bytes.
				mem.zero(raw_data(ic.scratch), len(ic.scratch))
			}
			input_note(&ic.ring, t, raw_data(ic.scratch))
		}
	}
}

@(private = "file")
host_frame :: proc(l: ^Lane, dt: f64) -> int {
	n := sim_ticker_advance(&l.ticker, dt)
	for t := l.ticker.tick - u64(n) + 1; t <= l.ticker.tick; t += 1 {
		sample_inputs(l, t)
		for _, p in l.peers {
			// One packet feeds every class, so the riders USUALLY agree — but
			// a held gap on one class retains its stale rider while another
			// advances, and "last wins" in map order let iteration order pick
			// this seat's rewind depth. Take the newest deterministically:
			// the tag is (ack<<8)|off, so the plain max is the freshest ack.
			best := u64(0)
			for _, buf in p.bufs {
				input_buffer_pop(buf, t) // sets buf.fresh
				best = max(best, buf.tag)
			}
			// Held buffers retain their old tag. A fresh input whose ack failed
			// validation deliberately carries zero and must CLEAR the old evidence.
			p.tag = best
		}
		run_tick(l, t)
		note_all(l.entries[:], t)
		if t % u64(l.snap_every) == 0 {
			snap_broadcast(l, t)
		}
	}
	return n
}

// One batch per connected client, each against ITS acked baseline, carrying
// ITS input ack. The host player itself never gets one (no transport
// loopback, and it holds the truth already).
@(private = "file")
snap_broadcast :: proc(l: ^Lane, tick: u64) {
	for p in ksess.session_roster(l.ses) {
		if !p.connected || p.id == l.ses.me {
			continue
		}
		lp := lane_peer_ensure(l, p.id)
		if lp.snap_first == 0 {
			lp.snap_first = tick
		}
		lp.snap_last = tick
		acked := lp.acked
		input_ack := peer_input_ack(lp)
		Snap_Pick :: struct {
			entry: Entry,
			owned: bool,
			stale: u64,
			d2:    f32,
		}
		picks := make([dynamic]Snap_Pick, 0, len(l.entries), context.temp_allocator)
		for e in l.entries {
			tr := cmd_tracked(l, e.id)
			owned := tr != nil && tr.owner == p.id
			if !owned && !ksess.session_interest_contains(l.ses, p.id, e.id) {
				l.stat_snap_aoi_culled += 1
				continue
			}
			last, sent := lp.snap_sent[e.id]
			stale := sent ? tick - last : max(u64)
			d2, distance_known := ksess.session_interest_distance_sq(l.ses, p.id, e.id)
			if !distance_known {
				d2 = 0
			}
			append(&picks, Snap_Pick{entry = e, owned = owned, stale = stale, d2 = d2})
		}
		if l.snapshot_budget > 0 && len(picks) > 1 {
			slice.stable_sort_by(picks[:], proc(a, b: Snap_Pick) -> bool {
				if a.owned != b.owned {return a.owned}
				if a.stale != b.stale {return a.stale > b.stale}
				return a.d2 < b.d2
			})
		}
		entries := make([]Entry, len(picks), context.temp_allocator)
		for pick, i in picks {
			entries[i] = pick.entry
		}
		w := ksess.session_app_begin(l.ses, l.tag)
		knet.write_u8(w, SIM_SNAP)
		stats := snap_write_recipient(
			w,
			entries,
			tick,
			acked,
			input_ack,
			l.snapshot_budget,
			&lp.snap_sent,
		)
		l.stat_snap_rows += stats.rows
		l.stat_snap_full += stats.full
		l.stat_snap_delta += stats.delta
		l.stat_snap_suppressed += stats.suppressed
		l.stat_snap_deferred += stats.deferred
		l.stat_snap_bytes += stats.bytes
		if l.echo_on {
			echo_write(l, w, tick)
		}
		ksess.session_app_flush(l.ses, p.peer, .Stream)
	}
}

// The input ack a batch ships is the MIN newest across the player's class
// buffers — the client leads enough for its most-starved input and trims every
// ring by this conservative floor. 0 until the player has sent anything.
@(private = "file")
peer_input_ack :: proc(p: ^Lane_Peer) -> u64 {
	m := max(u64)
	any := false
	for _, buf in p.bufs {
		if !any || buf.newest < m {
			m = buf.newest
			any = true
		}
	}
	return any ? m : 0
}

// The predict-world rider: every player's input AS THE SERVER SIMULATED IT
// this tick (its own from the rings, each peer's from the hold-last buffers),
// appended after the batch rows — [count u8] count × [player u64][class u16]
// [bytes]. One row per (player, class): a player driving two kinds echoes both.
// Clients tick remote contested entities from these held inputs, which is
// what puts every avatar on one predicted timeline.
@(private = "file")
echo_write :: proc(l: ^Lane, w: ^knet.Writer, tick: u64) {
	count_at := len(w.buf)
	knet.write_u8(w, 0)
	count := 0
	for &ic in l.inputs {
		if ic.sample != nil && ic.size > 0 {
			if blob, ok := input_read(&ic.ring, tick); ok {
				if count >= int(max(u8)) {
					l.stat_echo_dropped += 1
					continue
				}
				knet.write_player_id(w, l.ses.me)
				knet.write_u16(w, ic.id)
				append(&w.buf, ..blob)
				count += 1
			}
		}
	}
	for pid, p in l.peers {
		for cid, buf in p.bufs {
			if count >= int(max(u8)) {
				l.stat_echo_dropped += 1
				continue
			}
			knet.write_player_id(w, pid)
			knet.write_u16(w, cid)
			append(&w.buf, ..buf.held)
			count += 1
		}
	}
	w.buf[count_at] = u8(count)
}

@(private = "file")
client_frame :: proc(l: ^Lane, dt: f64) -> int {
	client_ingest(l)
	if !l.anchored {
		return 0
	}
	if l.cmd_clock < max(u64) {
		l.cmd_clock += 1
	}
	cmd_settle(l) // land verdicts/timeouts on the frame, not in a handler
	lane_spawn_sweep(l) // reap lost predicted spawns (a fire no authority spawn claimed)
	n := sim_ticker_advance(&l.ticker, dt)
	if n > 0 {
		// Fields may hold last frame's PRESENTED values (sim + decaying
		// error) — the ledger is the sim truth, so re-seed from it before
		// ticking. This one restore is what lets presentation vandalize the
		// fields freely between frames.
		head := l.ticker.tick - u64(n)
		for &e in l.entries {
			_ = history_restore(e.hist, head, e.entity)
		}
	}
	for t := l.ticker.tick - u64(n) + 1; t <= l.ticker.tick; t += 1 {
		sample_inputs(l, t)
		run_tick(l, t)
		note_all(l.entries[:], t)
	}
	plays := false
	for &ic in l.inputs {
		if ic.sample != nil && ic.size > 0 {
			plays = true
			break
		}
	}
	if n > 0 && plays {
		// Ack FIRST: the receiver tags every input in this packet with it —
		// the snap ack is the sender's world view, and binding them is what
		// lets a rewound query judge the view each input was AIMED with. The
		// render offset beside it says WHERE INSIDE that view the watch clock
		// was drawing (fractional ticks behind the ack, 1/8-tick fixed point):
		// a bounded claim — the server accepts only a recent ack it actually
		// issued, then clamps the offset and final rewind — that lets the rewind
		// BLEND the same bracket the shooter's
		// screen blended, instead of quantizing to a tick.
		//
		// Then one window PER CLASS this seat plays — a class count, then each
		// class's id and its redundant input window. A single-input game writes
		// count 1; a player driving two kinds writes both. Every ring trims by
		// the same min ack (l.input_ack), the conservative floor.
		w := ksess.session_app_begin(l.ses, l.tag)
		payload_at := len(w.buf)
		knet.write_u8(w, SIM_INPUT)
		snap_ack_write(w, &l.rx)
		knet.write_u8(w, render_off8(l))
		count_at := len(w.buf)
		knet.write_u8(w, 0) // class count, patched below
		cnt := 0
		for &ic in l.inputs {
			if ic.sample != nil && ic.size > 0 {
				knet.write_u16(w, ic.id)
				input_write(w, &ic.ring, l.input_ack, l.redundancy)
				cnt += 1
			}
		}
		assert(cnt <= int(max(u8)), "input class count exceeds its u8 wire field")
		w.buf[count_at] = u8(cnt)
		if len(w.buf) - payload_at > MAX_INPUT_PACKET_BYTES {
			// Registration catches this while developing. Keep stripped builds
			// bounded too if a hand-built lane mutates its config/classes later.
			l.stat_input_drops += 1
			return n
		}
		ksess.session_app_flush(l.ses, ksess.HOST_PEER, .Stream)
	}
	return n
}

// How far behind the acked batch this screen is DRAWING watched entities, in
// 1/8-tick units. Falls back to the watch target when the clock hasn't run
// (a game that never presents keeps the old single-tick behavior).
@(private = "file")
render_off8 :: proc(l: ^Lane) -> u8 {
	off := f64(l.watch_delay)
	if l.watch_clock > 0 && f64(l.rx.acked) > l.watch_clock {
		off = f64(l.rx.acked) - l.watch_clock
	}
	if off > 31.5 {
		// The wire ceiling (u8 in 1/8 ticks): a screen running further behind
		// than this REPORTS the ceiling, so the authority's lag comp rewinds
		// less than the shooter's true delay and shots judge shallow. Counted
		// — a moving tally is a stall/overload symptom, not a tuning knob.
		l.stat_render_sat += 1
	}
	off = clamp(off, 0, min(f64(2 * l.watch_delay + 4), 31.5))
	return u8(off * 8)
}

// Process the newest batch the handler filed: anchor or reconcile the
// predicted set, land watched truth, and bend the clock off the ack echo.
@(private = "file")
client_ingest :: proc(l: ^Lane) {
	if l.world !=
	   nil {if len(l.pending) != 0 {l.world.status = .Missing_Attachment; l.world.resync = true}; return}
	if len(l.pending) == 0 {
		return
	}
	truths := make([dynamic]Truth, context.temp_allocator)
	r := knet.reader_make(l.pending[:])
	tick, input_ack, _ := snap_rx_apply(&l.rx, &r, &truths)
	if tick != 0 && l.echo_on {
		// The predict-world rider follows the rows: last-known inputs for
		// every (player, class), last-value by batch (older batches dropped).
		// The class id gives the byte width — the receiver knows every class.
		ec := int(knet.read_u8(&r))
		for _ in 0 ..< ec {
			pid := knet.read_player_id(&r)
			cid := knet.read_u16(&r)
			ic := lane_class(l, cid)
			sz := ic != nil ? ic.size : 0
			if r.err || sz == 0 {
				break
			}
			blob := knet.reader_view(&r, sz)
			if r.err {
				break
			}
			if pid == l.ses.me {
				continue // my inputs live in my rings
			}
			key := Echo_Key{pid, cid}
			held, ok := l.echo[key]
			if !ok {
				held = make([]u8, sz)
				l.echo[key] = held
			}
			copy(held, blob)
		}
	}
	clear(&l.pending)
	l.pending_tick = 0
	if tick == 0 {
		return
	}
	ack_advanced := input_ack > l.input_ack // the server is still HEARING us
	l.input_ack = input_ack

	if !l.anchored {
		// First contact: adopt the truth outright and start predicting AHEAD
		// of it — the transit the input must cover (rtt/2 + jitter allowance,
		// from the session's clock sync) plus `margin` ticks of server-side
		// headroom. The old anchor used margin alone, so a distant client's
		// first seconds ran short and the controller grew the lead one nudge
		// at a time — inputs arriving late exactly while first impressions
		// form. A cold clock (no pong yet) reads rtt 0 and the margin stands;
		// the controller trims whatever the seed overshoots.
		for tr in truths {
			apply_truth(l, tr)
			if e := find_lane_entry(l, tr.id); e != nil {
				history_note_bytes(e.hist, tick, tr.blob)
			}
		}
		lead := l.margin
		if clock := ksess.session_clock(l.ses, ksess.HOST_PEER); clock.rtt > 0 {
			lead = max(lead, lead_target(&clock, l.ticker.dt, slack_ticks = l.margin))
		}
		l.ticker.tick = tick + u64(lead) + 1
		l.anchored = true
		return
	}

	// Pre-bracket (fewer than two applied batches) OR a game that has never
	// called lane_present: ingest paints watched truth directly. The latch
	// keeps the render_off8 promise honest — before it, a hand-driven client
	// that skipped lane_present froze every watched entity at the second
	// batch forever, because nobody else would ever paint them again.
	watched_fallback := l.rx.applied_count < 2 || !l.presented
	l.stat_reconciles += 1
	// What the screen last showed, per predicted entity — the continuity a
	// correction must glide from. Fields hold last present's visual (or the
	// sim state if the game never presents; either way, what was drawn).
	shown := make([][]u8, len(l.entries), context.temp_allocator)
	for &e, i in l.entries {
		shown[i] = make([]u8, e.hist.size, context.temp_allocator)
		predict_capture(shown[i], e.entity, e.hist.desc)
	}
	mism := make([dynamic]knet.Net_Id, context.temp_allocator)
	l.resimming = true
	resim_started := knet.now_s()
	l.stat_resims += reconcile(
		l.entries[:],
		truths[:],
		tick,
		l.ticker.tick,
		l,
		client_resim,
		&mism,
		l.tolerance,
	)
	l.stat_resim_seconds += max(knet.now_s() - resim_started, 0)
	l.resimming = false
	cmd_retire(l, tick) // ticks at or before the truth are settled history
	for id in mism {
		for &tr, i in l.tracked {
			if tr.id != id || tr.hist == nil {
				continue
			}
			if tr.err == nil {
				tr.err = make([]u8, tr.hist.size)
			}
			// Fields now hold the corrected head state; err = shown − truth
			// (which folds any prior error in — continuity is transitive).
			truth_now := make([]u8, tr.hist.size, context.temp_allocator)
			predict_capture(truth_now, tr.entity, tr.desc)
			for &e, j in l.entries {
				if e.id == id {
					predict_error(tr.err, shown[j], truth_now, tr.desc, l.smooth_cut)
					break
				}
			}
			break
		}
	}
	// Watched fields belong to the PRESENTER once a bracket exists: between
	// ingest and lane_present they must keep holding last frame's DELAYED
	// view — that is what the player's screen shows, what their aim samples
	// mean, and what the server's rewound judgment reconstructs. Painting
	// fresh truth here would let a sample read a future nobody rendered.
	// Before two batches exist there is nothing to blend, so ingest paints.
	if watched_fallback {
		for tr in truths {
			if find_lane_entry(l, tr.id) == nil {
				apply_truth(l, tr)
			}
		}
	}

	// input_ack − tick = how far our inputs ran ahead of the server's sim
	// when this batch left: the observed lead. Small errors BEND the clock;
	// a hole too deep to bend out of inside a second — the fresh anchor
	// under real transit (the batch we anchored to was already a transit
	// old), or a long stall — JUMPS the head instead. Skipped ticks are
	// never simulated or ledgered: the server holds-last through the gap
	// and the next reconcile seeds the new timeline. Until the first input
	// ack exists there is nothing to measure, so probe forward briskly.
	// A FROZEN ack is the other story — an upstream blackout, not a lead
	// deficit — and jumping on it would run away forward; there the bend's
	// saturation is the honest response and redundancy does the healing.
	observed := f64(i64(input_ack) - i64(tick))
	err := f64(l.margin) - observed
	if input_ack == 0 {
		l.ticker.tick += 3 // nothing acked yet: probe forward briskly
		lead_control(&l.ticker, 0)
	} else if err > LEAD_DEEP_TICKS && ack_advanced {
		l.ticker.tick += u64(err) // deep DEFICIT: jump the head, the gap holds last
		lead_control(&l.ticker, 0)
	} else if err < -LEAD_DEEP_TICKS && ack_advanced {
		// Deep SURPLUS: we are needlessly far ahead and every tick of it is
		// input latency the player pays for nothing. This cannot jump — the
		// head only moves forward (tick.odin's LEAD_DEEP_TICKS says why) — so
		// it bends HARD instead, and hands back to the fine bend at the same
		// threshold its mirror does. Gated on ack_advanced for the same reason
		// the deficit rung is: a frozen ack drives `observed` down, never up,
		// so a surplus measured against a dead upstream is not a surplus.
		lead_control(&l.ticker, err, SCALE_NUDGE_DEEP)
	} else {
		lead_control(&l.ticker, err)
	}
}

@(private = "file")
client_resim :: proc(user: rawptr, tick: u64) {
	l := cast(^Lane)user
	run_tick(l, tick) // the SAME tick path as the live frame — no sampling, no sends
}

@(private = "file")
apply_truth :: proc(l: ^Lane, tr: Truth) {
	for &t in l.tracked {
		if t.id == tr.id {
			predict_restore(t.entity, t.desc, tr.blob)
			return
		}
	}
}

@(private = "file")
find_lane_entry :: proc(l: ^Lane, id: knet.Net_Id) -> ^Entry {
	for &e in l.entries {
		if e.id == id {
			return &e
		}
	}
	return nil
}

// ---------------------------------------------------------------------------
// Lag compensation: judge a shot where the SHOOTER saw the target.
//
// The rewind tick is bounded, never trusted outright: the authority first
// proves the ack names a batch it issued in this seat lifetime, then binds that
// ack to the input packet. Visibility credit additionally requires the
// authority's own RTT sample. Ack age is capped by RTT + 2*jitter, input margin,
// and one snapshot cadence; the client render offset is only a hint, capped at
// the configured watch delay plus one cadence of interpolation phase. rewind_max
// remains the absolute ceiling.

REWIND_JITTER_MULT :: 2.0

// Maximum credible age of an issued snapshot acknowledgement when the input
// carrying it is finally executed. A healthy input may legitimately arrive one
// round trip after the snapshot, wait in the authority's input margin, and name
// the preceding snapshot cadence. Anything older is still safe as a DELTA
// baseline (peer_snap_ack_valid owns that question), but it is not evidence that
// earns an older hit-test world.
@(private = "file")
lane_rewind_ack_age :: proc(l: ^Lane, shooter: knet.Player_Id) -> (ticks: int, observed: bool) {
	p, seated := ksess.session_player(l.ses, shooter)
	if !seated || !p.connected || p.peer == ksess.NO_PEER {
		return 0, false
	}
	c := ksess.session_clock(l.ses, p.peer)
	if !c.initialized || c.rtt < 0 || c.jitter < 0 || c.rtt != c.rtt || c.jitter != c.jitter {
		return 0, false
	}
	// Cap in seconds before converting to int: even a deliberately delayed pong
	// cannot overflow conversion or expand credit past the configured ceiling.
	max_seconds := f64(l.rewind_max) * l.ticker.dt
	seconds := min(c.rtt + c.jitter * REWIND_JITTER_MULT, max_seconds)
	network_ticks := int((seconds + l.ticker.dt - 1e-9) / l.ticker.dt)
	ticks = min(network_ticks + l.margin + l.snap_every, l.rewind_max)
	return max(ticks, 0), true
}

// The authority-derived maximum rewind for this shooter right now, in ticks.
// Zero means the authority has no warm link observation and judges live. This
// is useful beside stat_rewind_clamped in a netgraph or adjudication trace.
lane_rewind_envelope :: proc(l: ^Lane, shooter: knet.Player_Id) -> int {
	assert(l.ses.is_host, "lag compensation is the authority's job")
	if shooter == l.ses.me {
		return 0
	}
	ack_age, observed := lane_rewind_ack_age(l, shooter)
	if !observed {
		return 0
	}
	render_cap := min(l.watch_delay + l.snap_every, 31)
	return min(ack_age + render_cap, l.rewind_max)
}

// The view a rewound query for `shooter` reconstructs (host, inside a step):
// the bracketing lower tick and the blend fraction toward the next — the
// SAME pair-and-alpha shape their watch clock drew with. Sources, in trust
// order: the validated issued ack bound to the INPUT BEING EXECUTED (it rode the
// trigger's packet; the shooter's latest ack is a whole lead-plus-transit
// fresher and describes a world they never saw), minus the render offset
// that rode beside it (a claim, clamped inside the issued/ring horizon).
lane_rewind_view :: proc(l: ^Lane, shooter: knet.Player_Id) -> (lo: u64, alpha: f32) {
	assert(l.ses.is_host, "lag compensation is the authority's job")
	t := l.step_tick
	if shooter == l.ses.me {
		return t, 0 // the host's own screen IS the live world
	}
	tag := u64(0)
	if p, ok := l.peers[shooter]; ok {
		tag = p.tag
	}
	ack := tag >> 8
	if ack == 0 || ack >= t {
		return t, 0 // no confirmed view yet: judge live
	}
	ack_age, observed := lane_rewind_ack_age(l, shooter)
	if !observed {
		// An issued ack remains a valid replication baseline, but until a pong
		// gives the authority its own link observation it earns no rewind credit.
		l.stat_rewind_clamped += 1
		return t, 0
	}
	clamped := false
	claimed_off := f64(tag & 0xFF) / 8
	// The target is watch_delay, but its correction breathes around batches.
	// One server-known cadence admits that honest interpolation phase without
	// turning a client-reported stall into deeper hit-test credit.
	render_cap := min(l.watch_delay + l.snap_every, 31)
	off := min(claimed_off, f64(render_cap))
	if off < claimed_off {
		clamped = true
	}
	ack_floor := t > u64(ack_age) ? t - u64(ack_age) : 1
	credible_ack := ack
	if credible_ack < ack_floor {
		credible_ack = ack_floor
		clamped = true
	}
	view := f64(credible_ack) - off
	floor_ := t > u64(l.rewind_max) ? t - u64(l.rewind_max) : 1
	if view <= f64(floor_) {
		view = f64(floor_)
		clamped = true
	}
	if clamped {
		l.stat_rewind_clamped += 1
	}
	if view == f64(floor_) {
		return floor_, 0
	}
	lo = u64(view)
	return lo, f32(view - f64(lo))
}

// The whole-tick floor of the view — kept for callers that only need the
// bound (diagnostics, damage falloff by age).
lane_rewind_tick :: proc(l: ^Lane, shooter: knet.Player_Id) -> u64 {
	lo, _ := lane_rewind_view(l, shooter)
	return lo
}

Rewound_Query :: proc(user: rawptr)

@(private = "file")
Wound :: struct {
	tr:   ^Tracked,
	live: []u8,
}

// Run `query` against the world as `shooter` rendered it: every tracked
// entity EXCEPT the shooter's own is wound back to lane_rewind_tick for the
// duration, then the live state returns — snapshots via the truth ledger,
// the exact same bytes the shooter's screen was drawn from. Entities whose
// ledger no longer holds the tick stay live (a fresh spawn the shooter
// couldn't have seen anyway). Host-only, inside your Step_Proc; returns the
// tick the world was judged at.
//
// This is exactly lane_rewound_begin + query + lane_rewound_end — take the
// inline pair when a context struct just to cross the rawptr boundary would
// outweigh the hit test itself.
lane_rewound :: proc(
	l: ^Lane,
	shooter: knet.Player_Id,
	user: rawptr,
	query: Rewound_Query,
) -> u64 {
	if lane_world_refuse(l) {return 0}
	judged := lane_rewound_begin(l, shooter)
	query(user)
	lane_rewound_end(l)
	return judged
}

// The inline form: wind the world back to what `shooter`'s screen showed,
// write the hit test right here, then put the world back —
//
//	judged := ksim.lane_rewound_begin(&g.lane, by)
//	for id, gun in g.gunners { ... }  // every OTHER entity stands where the
//	                                  // shooter saw it; their own stay live
//	ksim.lane_rewound_end(&g.lane)
//
// Same contract as lane_rewound: host-only, inside your step; returns the
// judged tick. Begin and end must pair within the same frame (captures ride
// the temp allocator), never nest, and nothing may track/untrack lane
// entities in between (the restore holds pointers into the track list).
lane_rewound_begin :: proc(l: ^Lane, shooter: knet.Player_Id) -> u64 {
	if lane_world_refuse(l) {return 0}
	assert(
		!l.rewound,
		"lane_rewound_begin: the world is already rewound — pair every begin with lane_rewound_end",
	)
	l.rewound = true
	lo, alpha := lane_rewind_view(l, shooter)
	if l.judge_live {
		lo = l.step_tick // the A/B knob: judge the live world
	}
	if lo >= l.step_tick {
		return l.step_tick
	}
	// Wind every target back to the BLENDED pose the shooter's screen drew —
	// the same bracket pair and fraction their watch clock used, from the
	// truth ledger (single-tick rewind quantized against the interpolation
	// and cost near-tangent shots; the duel acid measured it).
	for &tr in l.tracked {
		if tr.owner == shooter || tr.hist == nil {
			continue
		}
		a, aok := history_read(tr.hist, lo)
		if !aok {
			continue // the ledger no longer holds it (fresh spawn): test live
		}
		live := make([]u8, tr.hist.size, context.temp_allocator)
		predict_capture(live, tr.entity, tr.desc)
		b, bok := history_read(tr.hist, lo + 1)
		if alpha > 0.001 && bok {
			predict_blend(tr.entity, tr.desc, a, b, alpha)
		} else {
			predict_restore(tr.entity, tr.desc, a)
		}
		append(&l.wound, Wound{tr = &tr, live = live})
	}
	return lo
}

lane_rewound_end :: proc(l: ^Lane) {
	if lane_world_refuse(l) {return}
	assert(l.rewound, "lane_rewound_end without a begin")
	l.rewound = false
	for w in l.wound {
		predict_restore(w.tr.entity, w.tr.desc, w.live)
	}
	clear(&l.wound)
}

// ---------------------------------------------------------------------------
// Watched-entity presentation: the render clock for other people's avatars.
//
// Ingest lands watched truth as it arrives — correct, but stepping at the
// snap rate. lane_present renders them on a delayed tick timeline instead:
// a watch clock trails the newest applied batch by watch_delay ticks (so a
// bracketing PAIR of batches almost always exists), advances with frame
// time, and gets pulled gently toward its target — jitter becomes a slowly
// breathing delay, not a stutter. Blending honors Lerp_Kind per field
// (predict_blend); past the newest batch it clamps and HOLDS, never
// extrapolates. Call once per frame AFTER lane_frame, client-side (host and
// unanchored clients no-op). Predicted (own) entities are untouched — their
// freshness is the whole point of prediction.

lane_present :: proc(l: ^Lane, dt: f64) {
	if lane_world_busy(l) {lane_world_refuse(l); return}
	context.allocator = l.allocator // same rule as lane_frame
	l.presented = true // the presenter owns watched fields from here (see watched_fallback)
	if l.ses.is_host || !l.anchored || l.rx.applied_count == 0 {
		return
	}
	target := f64(l.rx.applied[l.rx.applied_count - 1]) - f64(l.watch_delay)
	if l.watch_clock == 0 {
		l.watch_clock = target // first frame: start on target
	}
	l.watch_clock += dt / l.ticker.dt // advance in tick units
	drift := target - l.watch_clock
	if abs(drift) > f64(2 * l.watch_delay) {
		l.watch_clock = target // a real discontinuity (stall, rejoin): cut
	} else {
		l.watch_clock += drift * 0.1 // breathe toward the target
	}

	// The OWN avatar: sim truth plus the decaying reconcile error — authority
	// snapped at ingest, the eye glides here. Restoring from the ledger first
	// makes a double present harmless (idempotent per frame).
	if l.smooth_halflife > 0 {
		for &tr in l.tracked {
			if tr.watched || tr.hist == nil || tr.err == nil {
				continue
			}
			if !history_restore(tr.hist, l.ticker.tick, tr.entity) {
				continue
			}
			// Per-field half-life: each field decays at its own glide (or the
			// lane default). The gate above stays a lane-level fast out.
			predict_error_decay(tr.err, tr.desc, dt, l.smooth_halflife)
			predict_error_apply(tr.entity, tr.desc, tr.err)
		}
	}

	prev, next, ok := snap_rx_bracket(&l.rx, l.watch_clock)
	if !ok {
		fire_facts(l) // ingest's snap stands, but ripe facts still present
		return // fewer than two batches (or pre-window)
	}
	for &tr in l.tracked {
		if !tr.watched && !tr.contested {
			continue
		}
		if tr.contested {
			// PREDICT-WORLD (echo mode): one timeline — every contested
			// entity presents its predicted pose (glide included), because
			// every avatar that could touch it is predicted too. The claim
			// dance exists only for MIXED timelines.
			if l.echo_on {
				continue
			}
			// The claim-weighted timeline. Fully mine: the predicted pose
			// (already in the fields, glide included) stands — your dribble
			// answers your feet. Unclaimed: the watched view, so a REMOTE
			// touch moves the ball beside the remote avatar that made it
			// instead of a whole lead early (the mixed-timelines artifact).
			// Between: blend, easing ~a quarter second back to watched.
			tr.claim = max(tr.claim - f32(dt / 0.25), 0)
			if tr.claim >= 0.999 {
				continue
			}
		}
		e := find_rx(&l.rx, tr.id)
		if e == nil {
			continue
		}
		// Reveal on cue: the tick the delayed clock reaches this entity's first
		// ledgered pose is the tick it should APPEAR — a remote muzzle's shot
		// emerges as the delayed barrel fires it, not a render delay early. The
		// boot created the node hidden; this uncovers it, exactly once.
		if !e.revealed && e.first != 0 && l.watch_clock >= f64(e.first) {
			e.revealed = true
			if l.present_ready != nil {
				l.present_ready(l.present_ready_user, tr.id, tr.entity)
			}
		}
		// Clamp the bracket UP to the entity's first ledgered tick. A fresh
		// watched spawn (a projectile that just left a remote muzzle) has no
		// truth before `first`, and the delayed watch clock sits a `watch_delay`
		// behind it — so hold it AT that first pose (the muzzle) until the clock
		// arrives, then let it fly. Without this it holds the node's stale value
		// (its scene default) and pops into place a watch_delay late, off the
		// barrel that fired it. Long-lived entities have `first` far in the past,
		// so lo/hi are prev/next and this is a no-op for them.
		lo, hi := prev, next
		if lo < e.first {
			lo = e.first
		}
		if hi < e.first {
			hi = e.first
		}
		a, aok := history_read(&e.hist, lo)
		b, bok := history_read(&e.hist, hi)
		if !aok || !bok {
			continue // a skipped row at one end: hold ingest's last apply
		}
		alpha := f32(0)
		if hi > lo {
			alpha = clamp(f32((l.watch_clock - f64(lo)) / f64(hi - lo)), 0, 1)
		}
		if tr.contested && tr.claim > 0.001 {
			// Mid-fade: capture the predicted pose, paint the watched view,
			// then blend the two by the claim.
			pred := make([]u8, tr.hist.size, context.temp_allocator)
			predict_capture(pred, tr.entity, tr.desc)
			predict_blend(tr.entity, tr.desc, a, b, alpha)
			watched := make([]u8, tr.hist.size, context.temp_allocator)
			predict_capture(watched, tr.entity, tr.desc)
			predict_blend(tr.entity, tr.desc, watched, pred, tr.claim)
			continue
		}
		predict_blend(tr.entity, tr.desc, a, b, alpha)
	}
	// Facts fire AFTER the blend, so a muzzle flash reads the same delayed
	// pose the screen draws this frame — the flash lands ON the barrel.
	fire_facts(l)
}

// Land every filed fact whose tick the watch clock has reached: fire the
// matching fx thunk with mine=false — kind 0 routes to the anchor set's
// tick fx, a declared kind to the package fact table. An entity untracked
// since filing (a despawn racing the render delay) drops its facts — the
// edge-outlives-observers law is the game's to honor (dwell the despawn,
// sim.md). An ANCHORLESS fact (id 0) has nothing to outlive and always fires.
@(private = "file")
fire_facts :: proc(l: ^Lane) {
	if l.watch_clock == 0 {
		return // the render clock hasn't started: hold facts until it exists
	}
	for i := 0; i < len(l.facts); {
		f := &l.facts[i]
		if f64(f.tick) > l.watch_clock {
			i += 1
			continue
		}
		// Copy the handles out before calling game code: presentation may not
		// track/untrack, but a dangling &tr across a call is not a bet.
		fx: Fx_Thunk
		entity: rawptr
		anchored := f.id != knet.NET_ID_INVALID
		if anchored {
			for &tr in l.tracked {
				if tr.id == f.id {
					if f.kind == 0 && tr.set != nil {
						fx = tr.set.fx
					}
					entity = tr.entity
					break
				}
			}
		}
		if f.kind != 0 && (!anchored || entity != nil) {
			fx = fact_fx(l, f.kind)
		}
		args := f.args
		ordered_remove(&l.facts, i)
		if fx != nil {
			fx(entity, l, false, args)
		}
		delete(args)
	}
}


// ---------------------------------------------------------------------------
// The receive side: bytes into lane state, game code never re-entered here.

@(private = "file")
lane_handle :: proc(
	user: rawptr,
	from: knet.Player_Id,
	from_peer: ksess.Peer_Id,
	r: ^knet.Reader,
) {
	l := cast(^Lane)user
	if l.world != nil {world_network_receive(l, from, from_peer, r); return}
	context.allocator = l.allocator // handler-side allocs must free under the same allocator later
	kind := knet.read_u8(r)
	if r.err {
		return
	}
	switch kind {
	case SIM_INPUT:
		if 1 + len(knet.reader_remaining(r)) > MAX_INPUT_PACKET_BYTES {
			l.stat_input_rejected += 1
			r.err = true
			return
		}
		// Host only; the session already resolved the seat (unseated peers
		// never reach a handler with a valid `from`). A watching seat drives
		// nobody — its windows are refused before a buffer ever exists.
		if !l.ses.is_host || from == knet.PLAYER_ID_INVALID {
			return
		}
		if sp, seated := ksess.session_player(l.ses, from); seated && sp.spectator {
			return
		}
		p := lane_peer_ensure(l, from)
		acked := snap_ack_read(r)
		off8 := knet.read_u8(r)
		ack_ok := !r.err && peer_snap_ack_valid(l, p, acked)
		if !ack_ok {
			l.stat_ack_rejected += 1
		}
		// One rider per input: the ack AND the render offset that traveled
		// with it, packed (ticks fit 56 bits by ~38 million years). An invalid
		// ack carries no rewind evidence; the input itself remains admissible.
		tag := ack_ok && acked != 0 ? (acked << 8) | u64(off8) : 0
		// One window per class the sender drives, into the matching per-player
		// buffer (created on first sight, sized from the class the build
		// registered). An unknown class can't be length-skipped safely, so it
		// drops the packet's tail — every peer runs the same build regardless.
		ccount := int(knet.read_u8(r))
		if r.err {
			return
		}
		expected := 0
		for &ic in l.inputs {
			if ic.size > 0 {
				expected += 1
			}
		}
		if ccount > MAX_INPUT_CLASSES_PER_SEAT || ccount > expected {
			l.stat_input_rejected += 1
			r.err = true
			return
		}
		max_input_tick := max(u64)
		if l.ticker.tick <= max(u64) - u64(l.lead_max) {
			max_input_tick = l.ticker.tick + u64(l.lead_max)
		}
		// First pass: validate the complete multi-class packet and reject
		// duplicate/unknown classes before ANY de-jitter buffer is mutated.
		probe := r^
		seen := make([dynamic]u16, context.temp_allocator)
		for _ in 0 ..< ccount {
			cid := knet.read_u16(&probe)
			ic := lane_class(l, cid)
			if probe.err || ic == nil || ic.size == 0 {
				l.stat_input_drops += 1
				l.stat_input_rejected += 1
				r.err = true
				return
			}
			duplicate := false
			for prev in seen {
				if prev == cid {
					duplicate = true
					break
				}
			}
			if duplicate ||
			   !input_window_validate(&probe, ic.size, max_input_tick, ic.validate, l.user) {
				l.stat_input_rejected += 1
				r.err = true
				return
			}
			append(&seen, cid)
		}
		if len(knet.reader_remaining(&probe)) != 0 {
			l.stat_input_rejected += 1
			r.err = true
			return
		}
		for _ in 0 ..< ccount {
			cid := knet.read_u16(r)
			if r.err {
				return // truncation — the session's malformed counter owns it
			}
			ic := lane_class(l, cid)
			if ic == nil || ic.size == 0 {
				l.stat_input_drops += 1 // preflight above should make this unreachable
				return
			}
			buf, has := p.bufs[cid]
			if !has {
				buf = new(Input_Buffer)
				buf^ = input_buffer_make(ic.size, l.slots)
				p.bufs[cid] = buf
			}
			input_buffer_apply(buf, r, tag = tag, max_tick = max_input_tick)
		}
		if r.err {
			l.stat_input_rejected += 1
			return
		}
		if ack_ok && acked > p.acked {
			p.acked = acked
		}
	case SIM_CMD:
		// Host only; the session already resolved the seat.
		if !l.ses.is_host || from == knet.PLAYER_ID_INVALID {
			return
		}
		cmd_handle(l, from, from_peer, r)
	case SIM_VERDICT:
		// Client only, and only the authority's word counts.
		if l.ses.is_host || from_peer != ksess.HOST_PEER {
			return
		}
		cmd_handle_verdict(l, r)
	case SIM_FACT:
		// Client only, and only the authority's word counts. Handler
		// discipline: file the bytes; the firing waits for the watch clock
		// (lane_present), on the game's own stack.
		if l.ses.is_host || from_peer != ksess.HOST_PEER {
			return
		}
		tick := knet.read_u64(r)
		id := knet.read_net_id(r)
		kind := knet.read_u16(r)
		blob := knet.read_bytes_limited(r, FACT_ARGS_MAX_BYTES)
		if r.err || len(knet.reader_remaining(r)) != 0 {
			r.err = true
			return
		}
		if len(l.facts) >= FACT_QUEUE_CAP {
			l.stat_facts_dropped += 1 // counted, never silent — netgraph's sim row shows it
			return
		}
		args := make([]u8, len(blob))
		copy(args, blob)
		append(&l.facts, Fact_In{tick = tick, id = id, kind = kind, args = args})
	case SIM_SNAP:
		// Client only, and only the authority's word counts.
		if l.ses.is_host || from_peer != ksess.HOST_PEER {
			return
		}
		rest := r.data[r.off:]
		if len(rest) < 8 {
			return
		}
		peek := knet.reader_make(rest)
		tick := knet.read_u64(&peek)
		if tick <= l.pending_tick || tick <= l.rx.newest {
			return // an older batch than one already filed/applied: superseded
		}
		clear(&l.pending)
		append(&l.pending, ..rest)
		l.pending_tick = tick
	}
}

kit/sim/input.odin.text:
package kit_sim

// input — the inputs-only-up pipeline: client ring, redundant packets, and
// the server's per-player de-jitter buffer.
//
// The trust model of this lane: clients send INPUTS, never state. An input is
// a small fixed-size POD blob (the gd:"input" struct, once scriptgen lands;
// hand-built until then), sampled once per predicted tick.
//
// THE LOSS STORY IS REDUNDANCY, NOT RETRANSMIT. Every packet carries the last
// few unacked inputs (INPUT_REDUNDANCY, default 8), so at a 60 Hz send rate a
// single input survives ~7 consecutive packet losses before it is genuinely
// gone — at which point the server's hold-last policy repeats the previous
// input for the gap tick and FLAGS it, and the client's own prediction for
// that tick reconciles like any other mispredict. No reliable channel, no
// head-of-line blocking, nothing to wait for: the same last-value taste as
// owner streams, applied to intent.
//
// De-jitter is a BUFFER DEPTH, not a delay line: the server consumes exactly
// one input per player per tick (input_buffer_pop). The lead-control loop
// closes over the batch header's input-ack echo — the client measures how
// far its inputs ran ahead of the server's sim and bends its clock
// (lane.odin's ingest + tick.odin's lead_control); nothing extra is shipped.

import "base:intrinsics"
import "core:math"
import knet "godot:kit/net"

// How many trailing inputs ride every packet. 8 at 60 Hz ≈ 133ms of loss
// absorbed per packet — friendslop-grade generous, and still tiny bytes.
INPUT_REDUNDANCY :: 8

// Hard cap a receiver enforces on count/size before touching its buffers —
// remote input is untrusted by default, exactly like kit/net's Reader rules.
MAX_INPUT_REDUNDANCY :: 64
MAX_INPUT_SIZE :: 256

// Aggregate admission limits. Per-window bounds alone still let a seat fan a
// packet out over hundreds of registered classes, or combine several legal
// windows into one oversized message. These caps cover the whole SIM_INPUT
// payload (kind byte included) before the host allocates a per-seat buffer.
MAX_INPUT_CLASSES_PER_SEAT :: 16
MAX_INPUT_PACKET_BYTES :: 32 * 1024

// Frame-safe semantic admission for one typed input blob. scriptgen wraps an
// authored `@(gd_sample="validate")` pair in this raw runtime shape. The proc
// may clamp/normalize through `input` and returns whether the result is legal;
// it must not retain the pointer (packet/sample scratch lifetime only).
Input_Validate_Proc :: proc(user: rawptr, input: rawptr) -> bool

// Small typed building blocks used by scriptgen's @(gd_input) sanitizers. They
// live here so generated game code needs no math/reflection imports of its own.
input_finite_f16 :: proc(x: f16) -> bool {return !math.is_nan(x) && !math.is_inf(x)}
input_finite_f32 :: proc(x: f32) -> bool {return !math.is_nan(x) && !math.is_inf(x)}
input_finite_f64 :: proc(x: f64) -> bool {return !math.is_nan(x) && !math.is_inf(x)}
input_finite :: proc {
	input_finite_f16,
	input_finite_f32,
	input_finite_f64,
}

input_unit_f32 :: proc(v: ^[$N]f32) -> bool {
	len2: f32
	for x in v^ {
		if !input_finite(x) {return false}
		len2 += x * x
	}
	if !input_finite(len2) {return false}
	if len2 > 1 {
		scale := 1 / math.sqrt(len2)
		for &x in v^ {x *= scale}
	}
	return true
}

input_unit_f64 :: proc(v: ^[$N]f64) -> bool {
	len2: f64
	for x in v^ {
		if !input_finite(x) {return false}
		len2 += x * x
	}
	if !input_finite(len2) {return false}
	if len2 > 1 {
		scale := 1 / math.sqrt(len2)
		for &x in v^ {x *= scale}
	}
	return true
}

input_unit :: proc {
	input_unit_f32,
	input_unit_f64,
}

// Raw packet bytes can contain an enum's underlying integer even when no enum
// member owns that value. Iterating an enum visits its declared values, including
// sparse enums; this does not mistake min..max for membership.
input_enum_valid :: proc(value: $T) -> bool where intrinsics.type_is_enum(T) {
	for valid in T {
		if value == valid {return true}
	}
	return false
}

// Raw fixed-size blob append/view — the packet layout carries the size once
// in its header, so per-input length prefixes would be dead bytes. The view
// read applies the Reader's sticky-error bounds rule by hand, the same move
// registry_apply_streams makes for length-skipped stream payloads.
@(private = "file")
write_blob :: proc(w: ^knet.Writer, blob: []u8) {
	append(&w.buf, ..blob)
}


// ---------------------------------------------------------------------------
// Client side: the ring of inputs already fed to prediction.

Input_Ring :: struct {
	ring: Tick_Ring, // the tick-indexed store (ring.odin)
	head: u64, // newest tick noted (0 = none yet)
	tail: u64, // oldest tick still held — the first note anchors it (a
	// client joins mid-timeline, so tick 1 usually never existed
	// here), lapping advances it
}

// `slots` must cover the resim window (the client's maximum lead) — a replay
// that reaches for a lapped input has already lost the tick it would explain.
input_ring_make :: proc(size: int, slots: int, allocator := context.allocator) -> Input_Ring {
	assert(size > 0 && size <= MAX_INPUT_SIZE)
	return Input_Ring{ring = tick_ring_make(size, slots, allocator)}
}

input_ring_destroy :: proc(r: ^Input_Ring) {
	tick_ring_destroy(&r.ring)
}

// Note the input SAMPLED FOR `tick`, right before predicting that tick — the
// same bytes a reconcile replay will hand back for it. Ticks are noted in
// order (the sim loop owns the counter); noting backwards is a caller bug.
input_note :: proc(r: ^Input_Ring, tick: u64, input: rawptr) {
	assert(tick > r.head, "inputs are noted in tick order")
	tick_ring_note(&r.ring, tick, ([^]u8)(input)[:r.ring.size])
	if r.head == 0 {
		r.tail = tick
	}
	r.head = tick
	if r.head - r.tail >= u64(r.ring.slots) {
		r.tail = r.head - u64(r.ring.slots) + 1
	}
}

// The input noted for `tick` (a view — valid until that slot laps). ok=false
// for never-noted or lapped — THE LEDGER CONTRACT (ring.odin).
input_read :: proc(r: ^Input_Ring, tick: u64) -> (input: []u8, ok: bool) {
	return tick_ring_read(&r.ring, tick)
}

// Append one input packet: the unacked window, newest-tick-inclusive.
//
//   [first_tick u64][count u8][size u16]  count × size raw input bytes
//
// `acked` is the newest tick the server has confirmed receiving (0 = none):
// everything at or before it is dead weight and drops out of the window, so
// a healthy link ships ~1-2 inputs per packet and a lossy one automatically
// widens toward `redundancy`. Returns the input count written. A 0-count
// window STILL writes the header — the sim lane composes this with the snap
// ack in one packet, and a conditionally-absent segment would desync every
// read behind it.
input_write :: proc(
	w: ^knet.Writer,
	r: ^Input_Ring,
	acked: u64,
	redundancy := INPUT_REDUNDANCY,
) -> int {
	assert(
		redundancy >= 0 && redundancy <= MAX_INPUT_REDUNDANCY,
		"input redundancy exceeds the receiver's u8/bounded-work contract",
	)
	// Keep release builds safe too: a bad hand-written caller must never wrap
	// the u8 count or make a receiver do more work than its advertised cap.
	redundancy_limit := clamp(redundancy, 0, MAX_INPUT_REDUNDANCY)
	// The window is the CONTIGUOUS run of noted ticks ending at head, walked
	// downward — never assumed. The ring legitimately has holes: a lead-
	// controller JUMP skips ticks wholesale (they were never simulated), and
	// the wire format can only describe a gapless run.
	first := r.head + 1 // the empty window, self-describing
	count := 0
	if r.head > 0 {
		red := min(redundancy_limit, r.ring.slots)
		for t := r.head; count < red && t > acked; t -= 1 {
			if _, ok := input_read(r, t); !ok {
				break // a hole (jump / lap): the window ends here
			}
			count += 1
			first = t
			if t == 1 {
				break
			}
		}
		if count == 0 {
			first = r.head + 1
		}
	}
	knet.write_u64(w, first)
	knet.write_u8(w, u8(count))
	knet.write_u16(w, u16(r.ring.size))
	for t := first; t < first + u64(count); t += 1 {
		blob, _ := input_read(r, t)
		write_blob(w, blob)
	}
	return count
}

// ---------------------------------------------------------------------------
// Server side: one Input_Buffer per player.

Input_Buffer :: struct {
	ring:        Tick_Ring, // the tick-indexed store (ring.odin)
	tags:        []u64, // per-tick rider, one per ring slot: the value `apply` was given for
	// the packet that delivered the tick (the sim lane rides the snap ack
	// here — it binds each input to the WORLD VIEW its sender aimed with)
	tag:         u64, // the last popped tick's rider, held-last across gaps like the input
	newest:      u64, // newest tick ever received — the ack the client trims by
	popped:      u64, // last tick consumed (0 = none): older arrivals are stale
	held:        []u8, // the hold-last copy a gap tick repeats (zeroed = neutral input until the first pop)
	fresh_count: u64, // pops that found the exact tick
	held_count:  u64, // pops that fell back to hold-last (the gap stat)
	fresh:       bool, // did the LAST pop find its tick (the driver's freshness bit) —
	// per-class now, so it rides the buffer instead of the peer
}

input_buffer_make :: proc(size: int, slots: int, allocator := context.allocator) -> Input_Buffer {
	assert(size > 0 && size <= MAX_INPUT_SIZE)
	return Input_Buffer {
		ring = tick_ring_make(size, slots, allocator),
		tags = make([]u64, slots, allocator),
		held = make([]u8, size, allocator),
	}
}

input_buffer_destroy :: proc(b: ^Input_Buffer) {
	tick_ring_destroy(&b.ring)
	delete(b.tags)
	delete(b.held)
	b.tags = nil
	b.held = nil
}

// Apply one received input packet (the input_write layout). Malformed or
// mis-sized packets set r.err and buffer nothing — remote input is untrusted.
// Duplicates (redundancy re-delivering, out-of-order arrival) and stale ticks
// (≤ popped) are skipped silently; that is the redundancy story working, not
// an error. Returns how many genuinely new inputs were buffered.
@(private)
Input_Window_Header :: struct {
	first: u64,
	count: int,
	size:  int,
}

// Read and preflight one window without consuming its blob bytes. lane_handle
// uses this on a copy of the Reader to validate an entire multi-class packet
// before applying any class; input_buffer_apply uses the same gate for direct
// callers and tests.
@(private)
input_window_header :: proc(
	r: ^knet.Reader,
	expected_size: int,
	max_tick: u64,
) -> Input_Window_Header {
	h := Input_Window_Header {
		first = knet.read_u64(r),
		count = int(knet.read_u8(r)),
		size  = int(knet.read_u16(r)),
	}
	if r.err || h.count > MAX_INPUT_REDUNDANCY || h.size != expected_size {
		r.err = true
		return h
	}
	// Validate the WHOLE window before touching the ring. Besides bounding how
	// far an untrusted client may write into the future, this catches u64 tick
	// wrap and truncation transactionally: malformed input buffers nothing,
	// rather than committing the prefix that happened to decode first.
	if h.count > 0 {
		last_delta := u64(h.count - 1)
		if h.first == 0 ||
		   h.first > max(u64) - last_delta ||
		   h.first + last_delta > max_tick ||
		   len(knet.reader_remaining(r)) < h.count * h.size {
			r.err = true
		}
	}
	return h
}

@(private)
input_window_validate :: proc(
	r: ^knet.Reader,
	expected_size: int,
	max_tick := max(u64),
	validate: Input_Validate_Proc = nil,
	user: rawptr = nil,
) -> bool {
	h := input_window_header(r, expected_size, max_tick)
	if r.err {
		return false
	}
	for _ in 0 ..< h.count {
		blob := knet.reader_view(r, h.size)
		if r.err || (validate != nil && !validate(user, raw_data(blob))) {
			r.err = true
			return false
		}
	}
	return !r.err
}

input_buffer_apply :: proc(
	b: ^Input_Buffer,
	r: ^knet.Reader,
	tag: u64 = 0,
	max_tick := max(u64),
	validate: Input_Validate_Proc = nil,
	user: rawptr = nil,
) -> int {
	// Direct callers get the same all-before-any semantic gate as lane_handle.
	// The probe's blob views alias the packet, so a sanitizer's clamped bytes
	// are exactly the bytes copied into the ring below.
	if validate != nil {
		probe := r^
		if !input_window_validate(&probe, b.ring.size, max_tick, validate, user) {
			r.err = true
			return 0
		}
	}
	h := input_window_header(r, b.ring.size, max_tick)
	if r.err {
		return 0
	}
	fresh := 0
	for k in 0 ..< h.count {
		t := h.first + u64(k)
		blob := knet.reader_view(r, h.size)
		if r.err {
			return fresh
		}
		if t == 0 {
			continue
		}
		if t > b.newest {
			// The ack tracks RECEIPT, stale or not: a client digging out of a
			// lead deficit needs its late inputs acknowledged to MEASURE the
			// hole (the lane's catch-up jump), and acked inputs leave the
			// redundant window either way.
			b.newest = t
		}
		if t <= b.popped {
			continue // stale: its tick already simulated (hold-last covered it)
		}
		// The buffer's own arrival guards read the stored stamp directly, then
		// note over the core (which restamps the same slot); tags rides beside.
		i := tick_ring_slot(&b.ring, t)
		if b.ring.tick[i] == t {
			continue // duplicate re-delivery
		}
		if b.ring.tick[i] > t {
			continue // slot holds a NEWER tick — never lap backwards
		}
		tick_ring_note(&b.ring, t, blob)
		b.tags[i] = tag
		fresh += 1
	}
	return fresh
}

// Consume the input for `tick` — the server calls this exactly once per
// player per simulated tick, monotonically. fresh=false means the tick never
// arrived (yet): the returned input is the hold-last copy (zeroed before the
// first pop — the neutral input) and the tick proc should treat the player as
// coasting; if the real input shows up later it is stale by definition and
// dropped. The returned slice is a view valid until the next pop.
input_buffer_pop :: proc(b: ^Input_Buffer, tick: u64) -> (input: []u8, fresh: bool) {
	assert(tick > b.popped, "pops advance one tick at a time, forward only")
	b.popped = tick
	if blob, ok := tick_ring_read(&b.ring, tick); ok {
		copy(b.held, blob)
		b.tag = b.tags[tick_ring_slot(&b.ring, tick)]
		b.fresh_count += 1
		b.fresh = true
		return b.held, true
	}
	b.held_count += 1 // b.tag holds the last real rider, like the input itself
	b.fresh = false
	return b.held, false
}

// Whole-world input resolution. Accepted authority values always win, including
// for this client's own player. Only an unknown row may use a local sample or a
// held predecessor. Complete checkpoints install that predecessor explicitly.
@(private)
world_net_input_codec :: proc(n: ^World_Network, class: u16) -> ^World_Value_Codec {
	for &c in n.config.codec.inputs {if c.class == class {return &c.codec}}
	return nil
}
@(private)
world_net_data :: proc(n: ^World_Network, data: []u8, tick: u64) -> []u8 {
	i := int(tick % WORLD_HISTORY_FRAMES) * n.value_bytes
	return data[i:i + n.value_bytes]
}
@(private)
world_net_driver_bytes :: proc(n: ^World_Network, data: []u8, driver: int) -> []u8 {
	c := world_net_input_codec(n, n.drivers[driver].class)
	return data[n.offsets[driver]:n.offsets[driver] + c.local_bytes]
}
@(private)
world_net_input :: proc(l: ^Lane, player: knet.Player_Id, class: u16) -> ([]u8, bool) {
	n := l.world.network
	for d, i in n.drivers {if d.player == player && d.class == class {
			for j := n.stage_count - 1; j >= 0; j -= 1 {if n.staged[j].tick == l.step_tick {
					data := n.staged_data[j * n.value_bytes:(j + 1) * n.value_bytes]
					return world_net_driver_bytes(n, data, i), true
				}}
			row := &n.used[l.step_tick % WORLD_HISTORY_FRAMES]
			if row.valid &&
			   row.tick ==
				   l.step_tick {return world_net_driver_bytes(n, world_net_data(n, n.used_data, l.step_tick), i), row.origin[i] != .Unknown}
		}}
	return nil, false
}
// Read the exact canonical accepted decision, never a held prediction disguised
// as authority. The returned local bytes are borrowed until the ledger wraps.
lane_world_accepted_input :: proc(
	l: ^Lane,
	tick: u64,
	player: knet.Player_Id,
	class: u16,
) -> (
	[]u8,
	World_Input_Origin,
	u64,
	World_Error,
) {
	if l == nil || l.world == nil || l.world.network == nil {return nil, .Unknown, 0, .Unsupported}
	n := l.world.network; row := &n.accepted[tick % WORLD_HISTORY_FRAMES]
	if !row.valid || row.tick != tick {return nil, .Unknown, 0, .History_Missing}
	for d, i in n.drivers {if d.player == player && d.class == class && row.origin[i] != .Unknown {return world_net_driver_bytes(n, world_net_data(n, n.accepted_data, tick), i), row.origin[i], row.sequence[i], .Ok}}
	return nil, .Unknown, 0, .History_Missing
}
@(private)
world_net_operation_begin :: proc(l: ^Lane, tick: u64) -> World_Error {
	n := l.world.network; if n == nil {return .Ok}
	n.stage_count = 0
	row := &n.used[tick % WORLD_HISTORY_FRAMES]
	if !row.valid || row.tick != tick {return .History_Missing}
	n.staged[0] = row^; copy(n.staged_data[:n.value_bytes], world_net_data(n, n.used_data, tick)); n.stage_count = 1
	return .Ok
}
@(private)
world_net_prepare :: proc(l: ^Lane, tick: u64) -> World_Error {
	n := l.world.network; if n == nil {return .Ok}
	if n.stage_count == 0 || n.stage_count >= len(n.staged) {return .Capacity}
	index := n.stage_count; prior := &n.staged[index - 1]
	if prior.tick + 1 != tick {return .History_Missing}
	row := &n.staged[index]; row^ = {
		tick  = tick,
		valid = true,
	}
	dst := n.staged_data[index * n.value_bytes:(index + 1) * n.value_bytes]
	previous := n.staged_data[(index - 1) * n.value_bytes:index * n.value_bytes]
	accepted := &n.accepted[tick % WORLD_HISTORY_FRAMES]
	proposed := &n.proposed[tick % WORLD_HISTORY_FRAMES]
	for d, i in n.drivers {
		value := world_net_driver_bytes(n, dst, i)
		if accepted.valid && accepted.tick == tick && accepted.origin[i] != .Unknown {
			copy(
				value,
				world_net_driver_bytes(n, world_net_data(n, n.accepted_data, tick), i),
			); row.origin[i] = accepted.origin[i]; row.sequence[i] = accepted.sequence[i]
		} else if l.ses.is_host &&
		   proposed.valid &&
		   proposed.tick == tick &&
		   proposed.origin[i] == .Submitted {
			copy(
				value,
				world_net_driver_bytes(n, world_net_data(n, n.proposed_data, tick), i),
			); row.origin[i] = .Submitted; row.sequence[i] = proposed.sequence[i]
		} else if d.player == l.ses.me {
			ic := lane_class(l, d.class); if ic == nil {return .Incompatible}
			local, have := input_read(&ic.ring, tick); if !have {return .History_Missing}
			copy(value, local); row.origin[i] = l.ses.is_host ? .Authority : .Unknown
			row.sequence[i] = tick // stable local sample identity across retransmission
		} else {
			hold :=
				true; for c in n.config.codec.inputs {if c.class == d.class {hold = c.prediction == .Hold}}
			if hold {copy(value, world_net_driver_bytes(n, previous, i))} else {for &b in value {b = 0}}; row.origin[i] = l.ses.is_host ? .Held : .Unknown; row.sequence[i] = prior.sequence[i]
		}
	}
	n.stage_count += 1
	return .Ok
}
@(private)
world_net_commit_inputs :: proc(l: ^Lane) {
	n := l.world.network; if n == nil {return}
	for row, i in n.staged[:n.stage_count] {
		n.used[row.tick % WORLD_HISTORY_FRAMES] = row
		data := n.staged_data[i * n.value_bytes:(i + 1) * n.value_bytes]
		copy(world_net_data(n, n.used_data, row.tick), data)
		if l.ses.is_host {n.accepted[row.tick % WORLD_HISTORY_FRAMES] = row; copy(world_net_data(n, n.accepted_data, row.tick), data)}
	}
}

kit/sim/snapshot.odin.text:
package kit_sim

// snapshot — the authority's wire: tick-stamped predict-set batches, delta-
// compressed against the last state the client CONFIRMED holding.
//
// Despite the name, most of what follows is the sim lane's ack-baselined DELTA
// codec (mask + dirty fields, diffed against an acked baseline); the full-row
// SNAPSHOT is only the fallback case — the row a client gets when no baseline
// is shared yet (a fresh spawn, a lapped ledger). "snapshot" names the batch's
// job, not the shape most rows take.
//
// The loop this file closes (the sim lane's whole conversation):
//
//   client → server   [input window]           (input.odin)  [snap ack u64]
//   server → client   [snap batch: tick, baseline, input ack, rows]
//
// THE BASELINE IS AN ACK, NOT A GUESS. The server deltas every entity against
// its ledgered truth at `baseline` — a tick the client explicitly acked, so
// both sides hold byte-identical state for it. Unreliable, unordered, last-
// value: a lost batch is superseded by the next one, a stale or duplicate
// batch is dropped by tick. What keeps the scheme honest through loss,
// reordering, and late joins is one invariant:
//
//   A CLIENT ACKS A BATCH ONLY WHEN IT APPLIED EVERY ROW.
//
// A row it had to skip (an entity whose spawn is still in flight on the
// reliable lane, a malformed length) leaves the ack where it was; the server
// keeps deltaing against the older confirmed tick — and for any entity whose
// ledger no longer reaches that tick (freshly spawned, or the client stalled
// past the ledger window) it falls back to a FULL row. Fulls decode with no
// baseline at all, so the client that finally learns the entity catches up on
// the next batch and the ack advances again. Self-healing in both directions,
// no keyframe request message, no retransmit.
//
// Rows ride length-prefixed like stream batches (an unknown id is skipped by
// length, never abandons the batch). The lane composes them PER RECIPIENT:
// owner first, then stalest/nearest interested entities within the byte budget.
// An unchanged entity costs zero row bytes: both ends carry its acknowledged
// value forward to this batch tick. AOI/budget omissions are different — the
// server does not mark them represented, so a later re-entry is forced FULL.
// Thus absence saves bytes without ever pretending the client holds a baseline
// it did not receive.
//
// Batch layout:
//   [tick u64][baseline u64][input_ack u64][count u16]
//     count × [net_id u32][flags u8][len u16][payload]
//   full row payload:   the predict subset, wire-encoded, field order
//   delta row payload:  [mask][dirty fields wire-encoded]  (mask bit i = i-th
//                       PREDICTED field, ceil(n/8) bytes)
//
// input_ack rides the batch header because batches are already composed
// per-client (the baseline is per-client) — the input ring's trim signal
// costs eight bytes in a message that was going to that client anyway.

import "core:mem"
import bd "godot:box3d/diagnostics"
import knet "godot:kit/net"
import ksess "godot:kit/session"

SNAP_FULL: u8 : 1 << 0 // row flag: payload is the whole subset, no baseline needed
SNAP_HEADER_BYTES :: 8 + 8 + 8 + 2
SNAP_ROW_HEADER_BYTES :: 4 + 1 + 2

Snap_Write_Stats :: struct {
	rows:       int,
	full:       int,
	delta:      int,
	suppressed: int,
	deferred:   int,
	bytes:      int,
}

// Byte size of one predict-set snapshot ON THE WIRE (Wire_Kind encodings
// applied) — what a full row's payload occupies. The stream_wire_size of
// this lane.
predict_wire_size :: proc(desc: ^knet.Entity_Desc) -> int {
	return knet.subset_view(desc, .Predicted).wire_bytes
}

// ---------------------------------------------------------------------------
// Server side: ledger → wire. Pure — per-client ack state lives in the
// driver (a map[peer]u64 beside the input buffers); this proc just writes
// one client's batch given the tick to ship and the tick that client acked.

// Write one snapshot batch from the entries' TRUTH ledgers. `tick` must be
// ledgered for every entry (the sim loop's contract: note_all, then snap) —
// entities that predict nothing are skipped. `baseline` is the target
// client's newest fully-applied tick (0 = nothing acked yet → all fulls).
// Returns the row count.
snap_write :: proc(
	w: ^knet.Writer,
	entries: []Entry,
	tick: u64,
	baseline: u64,
	input_ack: u64,
) -> int {
	stats := snap_write_recipient(w, entries, tick, baseline, input_ack, 0, nil, false)
	return stats.rows
}

// Per-recipient writer used by Lane. `budget` is the maximum snapshot body
// size (header + rows; zero is unlimited). `sent` records the exact batch tick
// in which each entity was represented for this peer. A delta is legal only
// when that row was represented in the peer's ACKED baseline batch; otherwise
// re-entry/deferred work is a full row. Unchanged rows advance `sent` without
// bytes because the receiver carries its baseline bytes forward to `tick`.
snap_write_recipient :: proc(
	w: ^knet.Writer,
	entries: []Entry,
	tick: u64,
	baseline: u64,
	input_ack: u64,
	budget: int,
	sent: ^map[knet.Net_Id]u64,
	suppress_unchanged := true,
) -> Snap_Write_Stats {
	assert(len(entries) <= int(max(u16)), "snapshot entity count exceeds its u16 wire field")
	assert(
		len(entries) <= knet.MAX_CONTAINER_ITEMS,
		"snapshot entity count exceeds MAX_CONTAINER_ITEMS",
	)
	start := len(w.buf)
	knet.write_u64(w, tick)
	knet.write_u64(w, baseline)
	knet.write_u64(w, input_ack)
	count_at := len(w.buf)
	knet.write_u16(w, 0) // patched below
	stats: Snap_Write_Stats
	for &e in entries {
		desc := e.hist.desc
		if e.hist.size == 0 {
			continue // predicts nothing — not this lane's entity
		}
		now, have_now := history_read(e.hist, tick)
		assert(have_now, "snap_write ships ledgered ticks: note_all before snapping")
		base, have_base := history_read(e.hist, baseline)
		if sent != nil && have_base {
			last, represented := sent^[e.id]
			have_base = represented && last == baseline
		}

		pred := knet.subset_view(desc, .Predicted)
		assert(
			pred.wire_bytes <= knet.MAX_REPLICATED_ENTITY_BYTES,
			"full snapshot row exceeds MAX_REPLICATED_ENTITY_BYTES",
		)
		if have_base && suppress_unchanged && mem.compare(now, base) == 0 {
			stats.suppressed += 1
			if sent != nil {
				sent^[e.id] = tick
			}
			continue
		}
		row := knet.writer_make(SNAP_ROW_HEADER_BYTES + pred.wire_bytes, context.temp_allocator)
		knet.write_net_id(&row, e.id)
		if !have_base {
			// New entity or lapped baseline: the full row that needs nothing.
			knet.write_u8(&row, SNAP_FULL)
			knet.write_u16(&row, u16(pred.wire_bytes))
			knet.subset_write_blob(&row, pred, now)
			stats.full += 1
		} else {
			knet.write_u8(&row, 0)
			len_at := len(row.buf)
			knet.write_u16(&row, 0) // patched below
			payload_from := len(row.buf)
			knet.subset_delta_write(&row, pred, now, base)
			payload := len(row.buf) - payload_from
			assert(payload <= int(max(u16)))
			knet.writer_patch_u16(&row, len_at, u16(payload))
			stats.delta += 1
		}
		if budget > 0 && len(w.buf) - start + len(row.buf) > budget {
			stats.deferred += 1
			if have_base {
				stats.delta -= 1
			} else {
				stats.full -= 1
			}
			continue
		}
		append(&w.buf, ..row.buf[:])
		stats.rows += 1
		if sent != nil {
			sent^[e.id] = tick
		}
	}
	assert(stats.rows <= int(max(u16)))
	knet.writer_patch_u16(w, count_at, u16(stats.rows))
	stats.bytes = len(w.buf) - start
	return stats
}

// ---------------------------------------------------------------------------
// Client side: wire → RECEIVED ledger → Truths for the reconcile.
//
// The received ledger is distinct from the prediction ledger on purpose:
// deltas decode against what the server SENT (and the client acked), never
// against what the client guessed — a mispredict must not corrupt the
// decode baseline.

Rx_Entry :: struct {
	id:       knet.Net_Id,
	hist:     History, // received truth, owned by the Snap_Rx
	first:    u64, // the first tick this entity was ever ledgered here (0 = none yet) —
	// a fresh watched spawn has no truth before it, so the presenter holds
	// it at this pose (the muzzle) until the delayed watch clock arrives,
	// instead of leaving the node at its stale/default value
	revealed: bool, // has the present_ready hook fired (the watch clock reached `first`) —
	// the engine layer reveals the hidden node exactly once, on cue
}

// How many recent batch ticks the receiver remembers for bracket lookups
// (lane_present interpolates watched entities between two of them). At the
// default 20 Hz snap rate this is ~800ms of history — the stream ring's
// depth, by the stream ring's reasoning.
SNAP_APPLIED_CAP :: knet.INTERP_CAP

Snap_Rx :: struct {
	entries:       [dynamic]Rx_Entry,
	slots:         int, // ledger depth for entities added later
	newest:        u64, // newest batch tick applied (stale/duplicate gate)
	acked:         u64, // newest FULLY-applied batch tick — THE ack to send
	// Ring of applied batch ticks, oldest first — batches apply in tick
	// order (stale ones drop), so this is sorted by construction.
	applied:       [SNAP_APPLIED_CAP]u64,
	applied_count: int,
}

// `slots` must cover the ack round trip in batch ticks (an acked tick stays
// the decode baseline until the server hears the next ack).
snap_rx_make :: proc(slots: int, allocator := context.allocator) -> Snap_Rx {
	return Snap_Rx{entries = make([dynamic]Rx_Entry, allocator), slots = slots}
}

snap_rx_destroy :: proc(rx: ^Snap_Rx) {
	for &e in rx.entries {
		history_destroy(&e.hist)
	}
	delete(rx.entries)
	rx.entries = nil
}

// Track an entity (at spawn, from the reliable lane). Rows for ids nobody
// tracks are skipped by length — and stall the ack, which is the mechanism
// that keeps the server's baselines honest while this call is in flight.
snap_rx_add :: proc(
	rx: ^Snap_Rx,
	id: knet.Net_Id,
	desc: ^knet.Entity_Desc,
	allocator := context.allocator,
) {
	assert(find_rx(rx, id) == nil, "snap_rx_add: id tracked twice")
	append(&rx.entries, Rx_Entry{id = id, hist = history_make(desc, rx.slots, allocator)})
}

snap_rx_remove :: proc(rx: ^Snap_Rx, id: knet.Net_Id) -> bool {
	for &e, i in rx.entries {
		if e.id == id {
			history_destroy(&e.hist)
			ordered_remove(&rx.entries, i)
			return true
		}
	}
	return false
}

// Apply one received batch. Returns tick = 0 for stale/duplicate/malformed
// (nothing changed); otherwise the batch tick, the server's input ack (feed
// input_write), and how many rows applied. Truth rows for the applied
// entities are appended to `truths` — blobs are views into the received
// ledger, valid until the next apply; hand them straight to reconcile.
snap_rx_apply :: proc(
	rx: ^Snap_Rx,
	r: ^knet.Reader,
	truths: ^[dynamic]Truth,
) -> (
	tick: u64,
	input_ack: u64,
	applied: int,
) {
	// Validate the entire batch before noting any history row. This keeps a
	// truncated/malformed suffix from leaving phantom tick state behind.
	probe := r^
	probe_tick := knet.read_u64(&probe)
	_ = knet.read_u64(&probe)
	_ = knet.read_u64(&probe)
	probe_count := int(knet.read_u16(&probe))
	if probe.err || probe_tick <= rx.newest || !knet.reader_admit_count(&probe, probe_count, 7) {
		if probe.err {
			r.err = true
		}
		return 0, 0, 0
	}
	for _ in 0 ..< probe_count {
		_ = knet.read_net_id(&probe)
		flags := knet.read_u8(&probe)
		n := int(knet.read_u16(&probe))
		if flags & ~SNAP_FULL != 0 || n > knet.MAX_REPLICATED_ENTITY_BYTES {
			probe.err = true
			break
		}
		_ = knet.reader_view(&probe, n)
	}
	if probe.err {
		r.err = true
		return 0, 0, 0
	}
	tick = knet.read_u64(r)
	baseline := knet.read_u64(r)
	input_ack = knet.read_u64(r)
	count := int(knet.read_u16(r))
	if r.err || tick <= rx.newest {
		return 0, 0, 0 // stale or duplicate: superseded, drop whole batch
	}
	skipped := 0
	for _ in 0 ..< count {
		id := knet.read_net_id(r)
		flags := knet.read_u8(r)
		n := int(knet.read_u16(r))
		payload := knet.reader_view(r, n)
		if r.err {
			return 0, 0, 0
		}

		e := find_rx(rx, id)
		if e == nil {
			skipped += 1 // spawn still in flight on the reliable lane
			continue
		}
		pred := knet.subset_view(e.hist.desc, .Predicted)
		scratch := make([]u8, e.hist.size, context.temp_allocator)
		if flags & SNAP_FULL != 0 {
			if !knet.subset_decode_full(pred, scratch, payload) {
				skipped += 1
				continue
			}
		} else {
			base, have := history_read(&e.hist, baseline)
			if !have {
				skipped += 1 // we never confirmed that baseline; a full will come
				continue
			}
			copy(scratch, base)
			if !knet.subset_delta_apply(pred, scratch, payload) {
				skipped += 1
				continue
			}
		}
		history_note_bytes(&e.hist, tick, scratch)
		if e.first == 0 {
			e.first = tick // the earliest pose the presenter can hold this entity at
		}
		blob, _ := history_read(&e.hist, tick)
		append(truths, Truth{id = id, blob = blob})
		applied += 1
	}
	rx.newest = tick
	if skipped == 0 {
		// A recipient batch may omit rows because they are unchanged, outside
		// AOI, or over budget. Carry the acknowledged baseline forward locally;
		// the server's per-entity sent ledger decides whether that carry is exact
		// (eligible for a future delta) or stale (must receive a full on re-entry).
		for &e in rx.entries {
			if _, have_tick := history_read(&e.hist, tick); have_tick {
				continue
			}
			if base, have_base := history_read(&e.hist, baseline); have_base {
				history_note_bytes(&e.hist, tick, base)
				carried, _ := history_read(&e.hist, tick)
				append(truths, Truth{id = e.id, blob = carried})
			}
		}
		rx.acked = tick // every row landed: this tick is a valid future baseline
	}
	if rx.applied_count < SNAP_APPLIED_CAP {
		rx.applied[rx.applied_count] = tick
		rx.applied_count += 1
	} else {
		copy(rx.applied[:SNAP_APPLIED_CAP - 1], rx.applied[1:])
		rx.applied[SNAP_APPLIED_CAP - 1] = tick
	}
	return tick, input_ack, applied
}

// The applied batch ticks bracketing time `at` (in ticks, fractional).
// ok=false when fewer than two batches have applied or `at` predates the
// window; at-or-past the newest returns (newest, newest) — the clamp-and-
// hold rule, never extrapolation.
snap_rx_bracket :: proc(rx: ^Snap_Rx, at: f64) -> (prev: u64, next: u64, ok: bool) {
	if rx.applied_count < 2 {
		return 0, 0, false
	}
	newest := rx.applied[rx.applied_count - 1]
	if at >= f64(newest) {
		return newest, newest, true
	}
	if at < f64(rx.applied[0]) {
		return 0, 0, false
	}
	for i in 1 ..< rx.applied_count {
		if f64(rx.applied[i]) >= at {
			return rx.applied[i - 1], rx.applied[i], true
		}
	}
	return newest, newest, true // unreachable given the clamps; safe fallback
}

// The eight-byte client→server half of the ack loop (the driver appends it
// to the input packet).
snap_ack_write :: proc(w: ^knet.Writer, rx: ^Snap_Rx) {
	knet.write_u64(w, rx.acked)
}

snap_ack_read :: proc(r: ^knet.Reader) -> u64 {
	return knet.read_u64(r)
}

@(private) // lane.odin's presenter and fact paths resolve rx entries too
find_rx :: proc(rx: ^Snap_Rx, id: knet.Net_Id) -> ^Rx_Entry {
	for &e in rx.entries {
		if e.id == id {
			return &e
		}
	}
	return nil
}

// Complete whole-world protocol encoding. Unlike SIM_SNAP, no recipient body
// filtering, raw typeid, host pointer, struct padding, or per-entity truth delta
// is a valid full physics attachment.
@(private)
world_wire_effect :: proc(n: ^World_Network, kind: u16) -> ^World_Effect_Def {
	for &e in n.effects {if e.kind == kind {return &e}}
	return nil
}
@(private)
world_wire_game :: proc(l: ^Lane, f: ^World_Frame) -> ([]u8, World_Error) {
	n :=
		l.world.network; writer := knet.writer_make(256, l.allocator); defer knet.writer_destroy(&writer)
	knet.write_u32(&writer, u32(len(n.config.codec.fields)))
	for binding in l.world.bindings {
		for field in n.config.codec.fields {if field.id == binding.id {
				wire, err := make(
					[]u8,
					field.codec.wire_bytes,
					l.allocator,
				); if err != nil {return nil, .Allocation_Failed}
				e := field.codec.encode(
					field.codec.user,
					f.fields[binding.offset:binding.offset + binding.size],
					wire,
				)
				if e != .Ok {delete(wire); return nil, e}
				knet.write_net_id(
					&writer,
					field.id,
				); knet.write_u32(&writer, u32(len(wire))); for b in wire {knet.write_u8(&writer, b)}; delete(wire)
			}}
	}
	knet.write_u8(&writer, u8(len(n.drivers)))
	for d in n.drivers {knet.write_player_id(&writer, d.player); knet.write_u16(&writer, d.class)}
	first := f.tick
	for first > 0 &&
	    f.tick - first <
		    WORLD_REPAIR_TICKS -
			    1 {prior := &n.accepted[(first - 1) % WORLD_HISTORY_FRAMES]; if !prior.valid || prior.tick != first - 1 {break}; first -= 1}
	knet.write_u64(&writer, first); knet.write_u8(&writer, u8(f.tick - first + 1))
	for tick := first; tick <= f.tick; tick += 1 {
		row := &n.accepted[tick % WORLD_HISTORY_FRAMES]; if !row.valid || row.tick != tick {return nil, .History_Missing}
		data := world_net_data(n, n.accepted_data, tick)
		for d, i in n.drivers {
			c := world_net_input_codec(n, d.class); wire: [MAX_INPUT_SIZE]u8
			if e := c.encode(c.user, world_net_driver_bytes(n, data, i), wire[:c.wire_bytes]);
			   e != .Ok {return nil, e}
			knet.write_u8(
				&writer,
				u8(row.origin[i]),
			); knet.write_u64(&writer, row.sequence[i]); for b in wire[:c.wire_bytes] {knet.write_u8(&writer, b)}
		}
		if tick == max(u64) {break}
	}
	result, err := make(
		[]u8,
		len(knet.writer_bytes(&writer)),
		l.allocator,
	); if err != nil {return nil, .Allocation_Failed}; copy(result, knet.writer_bytes(&writer)); return result, .Ok
}
@(private)
world_wire_occurrences :: proc(l: ^Lane, f: ^World_Frame) -> ([]u8, World_Error) {
	n :=
		l.world.network; writer := knet.writer_make(64, l.allocator); defer knet.writer_destroy(&writer)
	knet.write_u8(&writer, u8(f.effect_count))
	for &e in f.effects[:f.effect_count] {
		def := world_wire_effect(
			n,
			e.kind,
		); if def == nil || e.count != def.codec.local_bytes {return nil, .Incompatible}
		wire: [WORLD_EFFECT_BYTES]u8
		if err := def.codec.encode(def.codec.user, e.args[:e.count], wire[:def.codec.wire_bytes]);
		   err != .Ok {return nil, err}
		knet.write_u16(
			&writer,
			e.kind,
		); knet.write_u64(&writer, e.key); for b in wire[:def.codec.wire_bytes] {knet.write_u8(&writer, b)}
	}
	result, err := make(
		[]u8,
		len(knet.writer_bytes(&writer)),
		l.allocator,
	); if err != nil {return nil, .Allocation_Failed}; copy(result, knet.writer_bytes(&writer)); return result, .Ok
}

@(private)
world_wire_parts :: proc(l: ^Lane, f: ^World_Frame) -> (parts: [bd.Part][]u8, error: World_Error) {
	n := l.world.network; success := false
	defer {if !success {for part in parts {delete(part)}}}
	for p in ([?]bd.Part{.Solver, .Side, .Observations}) {
		count, e := n.config.codec.encode(n.config.codec.user, f.image, p, nil)
		if e !=
		   .Ok {return parts, e}; if count < 0 || count > WORLD_NETWORK_BYTES {return parts, .Capacity}
		part, allocation_error := make(
			[]u8,
			count,
			l.allocator,
		); if allocation_error != nil {return parts, .Allocation_Failed}
		parts[p] = part
		_, e = n.config.codec.encode(
			n.config.codec.user,
			f.image,
			p,
			part,
		); if e != .Ok {return parts, e}
	}
	parts[.Game], error = world_wire_game(l, f); if error != .Ok {return parts, error}
	parts[.Occurrences], error = world_wire_occurrences(
		l,
		f,
	); if error != .Ok {return parts, error}
	total :=
		bd.SIGNATURE_BYTES; for part in parts {if len(part) > WORLD_NETWORK_BYTES - total {return parts, .Capacity}; total += len(part)}
	success = true; return parts, .Ok
}
// A complete export is an owning byte buffer; caller deletes it with the Lane
// allocator. It survives source Lane/provider/world destruction. No local image
// pointer or process schema fingerprint appears in the wire bytes.
lane_world_export :: proc(l: ^Lane, tick: u64) -> ([]u8, World_Error) {
	if l == nil || l.world == nil || l.world.network == nil {return nil, .Unsupported}
	w :=
		l.world; n := w.network; if !l.ses.is_host {return nil, .Rejected}; if w.busy || w.presenting {return nil, .Busy}
	f := world_record(w, tick); if f == nil {return nil, .History_Missing}
	if e := w.provider.admit_detached(
		world_external_bytes(l) + WORLD_NETWORK_BYTES * 2,
		w.config.reservation_bytes,
	); e != .Ok {return nil, e}
	n.outbound_bytes +=
		WORLD_NETWORK_BYTES * 2; defer {n.outbound_bytes -= WORLD_NETWORK_BYTES * 2}
	parts, e := world_wire_parts(
		l,
		f,
	); if e != .Ok {return nil, e}; defer {for part in parts {delete(part)}}
	sig, se := bd.sign(
		{n.config.identity, n.epoch, tick, parts},
	); if se != .None {return nil, .Incompatible}
	recovery_count, re := n.config.codec.recovery_encode(n.config.codec.user, f.image, nil)
	if re !=
	   .Ok {return nil, re}; if recovery_count <= 0 || recovery_count > WORLD_NETWORK_BYTES {return nil, .Capacity}
	recovery, allocation_error := make(
		[]u8,
		recovery_count,
		l.allocator,
	); if allocation_error != nil {return nil, .Allocation_Failed}; defer delete(recovery, l.allocator)
	_, re = n.config.codec.recovery_encode(
		n.config.codec.user,
		f.image,
		recovery,
	); if re != .Ok {return nil, re}
	total :=
		bd.SIGNATURE_BYTES +
		4 +
		recovery_count; for part in parts {if len(part) > WORLD_NETWORK_BYTES - total {return nil, .Capacity}; total += len(part)}
	result, err := make([]u8, total, l.allocator); if err != nil {return nil, .Allocation_Failed}
	_, se = bd.signature_encode(
		sig,
		result[:bd.SIGNATURE_BYTES],
	); if se != .None {delete(result); return nil, .Invalid}
	for i in 0 ..< 4 {result[bd.SIGNATURE_BYTES + i] = u8(u32(recovery_count) >> uint(i * 8))}
	copy(result[bd.SIGNATURE_BYTES + 4:], recovery)
	at :=
		bd.SIGNATURE_BYTES +
		4 +
		recovery_count; for part in parts {copy(result[at:], part); at += len(part)}
	return result, .Ok
}
lane_world_send_checkpoint :: proc(
	l: ^Lane,
	to: ksess.Peer_Id,
	mode: World_Transfer_Mode,
) -> World_Error {
	if l == nil || l.world == nil || l.world.network == nil || !l.ses.is_host {return .Unsupported}
	n := l.world.network; if n.sequence == max(u64) {return .Capacity}
	bytes, e := lane_world_export(
		l,
		l.world.head,
	); if e != .Ok {world_network_fail(l, e); return e}; defer delete(bytes, l.allocator)
	n.outbound_bytes += u64(len(bytes)); defer {n.outbound_bytes -= u64(len(bytes))}
	n.sequence += 1; digest := bd.hash_bytes(bytes); chunks := (len(bytes) + WORLD_NETWORK_CHUNK - 1) / WORLD_NETWORK_CHUNK
	for index in 0 ..< chunks {
		writer := ksess.session_app_begin(l.ses, l.tag); knet.write_u8(writer, SIM_WORLD_CHUNK)
		knet.write_u32(
			writer,
			WORLD_NETWORK_REV,
		); knet.write_u8(writer, u8(mode)); knet.write_u64(writer, n.sequence); knet.write_u64(writer, n.epoch); knet.write_u64(writer, l.world.head); knet.write_u32(writer, u32(len(bytes))); knet.write_u16(writer, u16(index)); knet.write_u16(writer, u16(chunks))
		for b in digest {knet.write_u8(writer, b)}
		for b in bytes[index * WORLD_NETWORK_CHUNK:min(len(bytes), (index + 1) * WORLD_NETWORK_CHUNK)] {knet.write_u8(writer, b)}
		ksess.session_app_flush(l.ses, to, .Reliable)
	}
	return .Ok
}
@(private)
world_wire_decode :: proc(
	l: ^Lane,
	bytes: []u8,
) -> (
	cp: World_Checkpoint,
	baseline: World_Input_Row,
	values: []u8,
	signature: bd.Signature,
	error: World_Error,
) {
	w := l.world; n := w.network
	if len(bytes) < bd.SIGNATURE_BYTES ||
	   len(bytes) > WORLD_NETWORK_BYTES {return cp, baseline, nil, signature, .Invalid}
	sig, se := bd.signature_decode(
		bytes[:bd.SIGNATURE_BYTES],
	); if se != .None || sig.identity != n.config.identity {return cp, baseline, nil, signature, .Incompatible}
	parts, recovery, parse_error := world_wire_view(
		bytes,
		sig,
	); if parse_error != .Ok {return cp, baseline, nil, signature, parse_error}
	actual, ae := bd.sign(
		{sig.identity, sig.epoch, sig.tick, parts},
	); if ae != .None || bd.compare(sig, actual) != .Match {return cp, baseline, nil, signature, .Invalid}
	charge := u64(
		w.field_bytes + size_of(World_Checkpoint),
	); need := charge + u64(n.value_bytes * WORLD_REPAIR_TICKS)
	if need > WORLD_MEMORY_BYTES ||
	   world_external_bytes(l) >
		   WORLD_MEMORY_BYTES - need {return cp, baseline, nil, signature, .Budget}
	if e := w.provider.admit_detached(world_external_bytes(l) + need, w.config.reservation_bytes);
	   e != .Ok {return cp, baseline, nil, signature, e}
	n.outbound_bytes += need; defer {n.outbound_bytes -= need}
	fields, err := make(
		[]u8,
		w.field_bytes,
		w.allocator,
	); if err != nil {return cp, baseline, nil, signature, .Allocation_Failed}
	values, err = make(
		[]u8,
		n.value_bytes * WORLD_REPAIR_TICKS,
		w.allocator,
	); if err != nil {delete(fields); return cp, baseline, nil, signature, .Allocation_Failed}
	success :=
		false; defer {if !success {delete(fields); delete(values); if cp.image != nil {w.provider.release(cp.image)}}}
	r := knet.reader_make(
		parts[.Game],
	); count := int(knet.read_u32(&r)); if r.err || count != len(w.bindings) {return cp, baseline, values, signature, .Incompatible}
	for b in w.bindings {
		id := knet.read_net_id(
			&r,
		); length := int(knet.read_u32(&r)); if r.err || id != b.id {return cp, baseline, values, signature, .Incompatible}
		for field in n.config.codec.fields {if field.id == b.id {
				if length !=
				   field.codec.wire_bytes {return cp, baseline, values, signature, .Incompatible}
				wire := knet.reader_view(
					&r,
					length,
				); if r.err {return cp, baseline, values, signature, .Invalid}
				if e := field.codec.decode(
					field.codec.user,
					wire,
					fields[b.offset:b.offset + b.size],
				); e != .Ok {return cp, baseline, values, signature, e}
			}}
	}
	drivers := int(
		knet.read_u8(&r),
	); if drivers != len(n.drivers) {return cp, baseline, values, signature, .Incompatible}
	for d in n.drivers {player := knet.read_player_id(&r); class := knet.read_u16(&r); if r.err || player != d.player || class != d.class {return cp, baseline, values, signature, .Incompatible}}
	first := knet.read_u64(&r); window_count := int(knet.read_u8(&r))
	if r.err ||
	   window_count < 1 ||
	   window_count > WORLD_REPAIR_TICKS ||
	   first > max(u64) - u64(window_count - 1) ||
	   first + u64(window_count - 1) != sig.tick {return cp, baseline, values, signature, .Invalid}
	n.incoming_count = 0
	for j in 0 ..< window_count {
		row := World_Input_Row {
			tick  = first + u64(j),
			valid = true,
		}
		for d, i in n.drivers {
			origin := World_Input_Origin(knet.read_u8(&r)); sequence := knet.read_u64(&r)
			if r.err ||
			   origin == .Unknown ||
			   origin > .Authority ||
			   sequence > row.tick ||
			   (origin != .Held &&
					   sequence != row.tick) {return cp, baseline, values, signature, .Invalid}
			c := world_net_input_codec(
				n,
				d.class,
			); wire := knet.reader_view(&r, c.wire_bytes); if r.err {return cp, baseline, values, signature, .Invalid}
			if e := c.decode(
				c.user,
				wire,
				world_net_driver_bytes(n, values[j * n.value_bytes:(j + 1) * n.value_bytes], i),
			); e != .Ok {return cp, baseline, values, signature, e}
			row.origin[i] = origin; row.sequence[i] = sequence
		}
		n.incoming[j] = row; baseline = row
	}
	n.incoming_count = window_count
	if len(knet.reader_remaining(&r)) != 0 {return cp, baseline, values, signature, .Invalid}
	r = knet.reader_make(
		parts[.Occurrences],
	); cp.effects_known = true; cp.effect_count = int(knet.read_u8(&r)); if r.err || cp.effect_count > WORLD_EFFECTS_PER_TICK {return cp, baseline, values, signature, .Invalid}
	for &event, i in cp.effects[:cp.effect_count] {
		kind := knet.read_u16(
			&r,
		); key := knet.read_u64(&r); def := world_wire_effect(n, kind); if r.err || def == nil || key == 0 {return cp, baseline, values, signature, .Invalid}
		for prior in cp.effects[:i] {if prior.key == key {return cp, baseline, values, signature, .Conflict}}
		event = {
			kind  = kind,
			key   = key,
			fire  = def.fire,
			user  = def.user,
			count = def.codec.local_bytes,
		}; wire := knet.reader_view(&r, def.codec.wire_bytes)
		if r.err {return cp, baseline, values, signature, .Invalid}; if e := def.codec.decode(def.codec.user, wire, event.args[:event.count]); e != .Ok {return cp, baseline, values, signature, e}
	}
	if len(knet.reader_remaining(&r)) != 0 {return cp, baseline, values, signature, .Invalid}
	cp.image, error = n.config.codec.decode(
		n.config.codec.user,
		recovery,
		parts[.Side],
		parts[.Observations],
	); if error != .Ok {return cp, baseline, values, signature, error}
	// Logical diagnostic bytes are never imported. Independently reconstructed
	// native state must reproduce every signed logical solver byte before use.
	normalized_count, encode_error := n.config.codec.encode(
		n.config.codec.user,
		cp.image,
		.Solver,
		nil,
	)
	if encode_error != .Ok ||
	   normalized_count !=
		   len(parts[.Solver]) {return cp, baseline, values, signature, .Incompatible}
	if e := w.provider.admit_detached(
		world_external_bytes(l) + u64(normalized_count),
		w.config.reservation_bytes,
	); e != .Ok {return cp, baseline, values, signature, e}
	n.outbound_bytes += u64(normalized_count); defer {n.outbound_bytes -= u64(normalized_count)}
	comparison, comparison_error := make(
		[]u8,
		normalized_count,
		w.allocator,
	); if comparison_error != nil {return cp, baseline, values, signature, .Allocation_Failed}; defer delete(comparison, w.allocator)
	_, encode_error = n.config.codec.encode(n.config.codec.user, cp.image, .Solver, comparison)
	if encode_error != .Ok ||
	   mem.compare(comparison, parts[.Solver]) !=
		   0 {return cp, baseline, values, signature, .Incompatible}
	cp.tick =
		sig.tick; cp.asset_id = w.provider.asset_id; cp.field_schema = w.field_schema; cp.side_type = w.provider.side_type; cp.fields = fields; cp.clone = w.provider.clone; cp.release = w.provider.release; cp.equal = w.provider.equal; cp.allocator = w.allocator; cp.admit_detached = w.provider.admit_detached; cp.charge_bytes = charge; cp.reservation_bytes = w.config.reservation_bytes
	g_world_checkpoint_bytes += charge; success = true; return cp, baseline, values, sig, .Ok
}

@(private)
world_wire_view :: proc(
	bytes: []u8,
	sig: bd.Signature,
) -> (
	parts: [bd.Part][]u8,
	recovery: []u8,
	error: World_Error,
) {
	if len(bytes) < bd.SIGNATURE_BYTES + 4 {return parts, nil, .Invalid}
	r := knet.reader_make(bytes[bd.SIGNATURE_BYTES:]); count := int(knet.read_u32(&r))
	if r.err || count <= 0 || count > WORLD_NETWORK_BYTES {return parts, nil, .Missing_Attachment}
	recovery = knet.reader_view(&r, count); if r.err {return parts, nil, .Invalid}
	for p in bd.Part {if sig.lengths[p] > u64(len(knet.reader_remaining(&r))) {return parts, nil, .Invalid}; parts[p] = knet.reader_view(&r, int(sig.lengths[p]))}
	if r.err || len(knet.reader_remaining(&r)) != 0 {return parts, nil, .Invalid}
	return parts, recovery, .Ok
}

kit/sim/physics.odin.text:
package kit_sim

// Optional whole-world participant. This file imports no native backend. Every
// opaque image owns complete solver+typed Side state; field bytes stay in Kit's
// existing prediction/history path. Callers must not copy owning checkpoints.
import "core:mem"
import "core:reflect"
import "core:time"
import bd "godot:box3d/diagnostics"
import knet "godot:kit/net"

WORLD_HISTORY_FRAMES :: 128
WORLD_REPAIR_TICKS :: 8
WORLD_EFFECTS_PER_TICK :: 32
WORLD_EFFECT_BYTES :: 128
WORLD_WORK_NS :: u64(4_000_000)
WORLD_MEMORY_BYTES :: u64(64 * 1024 * 1024)

World_Error :: enum {
	Ok,
	Invalid,
	Unsupported,
	Incompatible,
	History_Missing,
	Missing_Attachment,
	Prediction_Limit,
	Repair_Limit,
	Capacity,
	Allocation_Failed,
	Step_Failed,
	Rejected,
	Busy,
	Budget,
	Settled,
	Conflict,
}
World_Admission :: struct {
	prediction_ticks, correction_ticks:                                         u32,
	additional_owned_bytes, reserved_bytes, normal_work_ns, correction_work_ns: u64,
}
World_Provider :: struct {
	user:              rawptr, // managed owner/config, never uncheckpointed game state
	side_type:         typeid,
	asset_id:          u64,
	initial_execution: rawptr, // ownership transfers only on successful attach
	capture:           proc(user, execution: rawptr) -> (rawptr, World_Error),
	clone:             proc(image: rawptr) -> (rawptr, World_Error),
	equal:             proc(left, right: rawptr) -> (bool, World_Error),
	release:           proc(image: rawptr), // self-contained; source provider may be gone
	open:              proc(user, image: rawptr) -> (rawptr, World_Error),
	close:             proc(execution: rawptr),
	bind:              proc(user, execution: rawptr),
	publish:           proc(user, execution: rawptr), // infallible selection, no allocation
	step:              proc(user, execution: rawptr, tick: u64) -> World_Error,
	admit:             proc(user, execution: rawptr, request: World_Admission) -> World_Error,
	admit_detached:    proc(additional_owned_bytes, reserved_bytes: u64) -> World_Error,
}
World_Field_Type :: struct {
	id:   knet.Net_Id,
	type: typeid,
}
world_field_type :: proc(id: knet.Net_Id, $T: typeid) -> World_Field_Type {return {id, T}}

// Alpha proxies are fixed pointer-free state structs, not arbitrary Godot nodes.
world_value_supported :: proc(t: typeid) -> bool {return world_value_info_supported(
		type_info_of(t),
	)}
@(private)
world_value_info_supported :: proc(source: ^reflect.Type_Info) -> bool {
	if source == nil {return false}
	info := reflect.type_info_base(source)
	if info == nil {return false}
	#partial switch v in info.variant {
	case reflect.Type_Info_Integer,
	     reflect.Type_Info_Rune,
	     reflect.Type_Info_Float,
	     reflect.Type_Info_Boolean:
		return true
	case reflect.Type_Info_Enum:
		return world_value_info_supported(v.base)
	case reflect.Type_Info_Bit_Set:
		return world_value_info_supported(v.underlying)
	case reflect.Type_Info_Array:
		return world_value_info_supported(v.elem)
	case reflect.Type_Info_Enumerated_Array:
		return world_value_info_supported(v.elem)
	case reflect.Type_Info_Struct:
		if v.soa_kind != .None || .raw_union in v.flags {return false}
		for t in v.types[:v.field_count] {if !world_value_info_supported(t) {return false}}
		return true
	}
	return false
}
World_Effect_Proc :: proc(user: rawptr, tick, key: u64, args: []u8)
World_Effect :: struct {
	kind:  u16, // immutable network catalog ID; zero only in local-only mode
	key:   u64,
	fire:  World_Effect_Proc,
	user:  rawptr,
	count: int,
	args:  [WORLD_EFFECT_BYTES]u8,
}
World_Frame :: struct {
	tick:         u64,
	valid:        bool,
	image:        rawptr,
	fields:       []u8,
	effect_count: int,
	effects:      [WORLD_EFFECTS_PER_TICK]World_Effect,
}
World_Checkpoint :: struct {
	effects_known:                   bool,
	effect_count:                    int,
	effects:                         [WORLD_EFFECTS_PER_TICK]World_Effect,
	tick, asset_id, field_schema:    u64,
	side_type:                       typeid,
	image:                           rawptr,
	fields:                          []u8,
	clone:                           proc(_: rawptr) -> (rawptr, World_Error),
	release:                         proc(_: rawptr),
	equal:                           proc(left, right: rawptr) -> (bool, World_Error),
	allocator:                       mem.Allocator,
	admit_detached:                  proc(
		additional_owned_bytes, reserved_bytes: u64,
	) -> World_Error,
	charge_bytes, reservation_bytes: u64,
}
@(private)
g_world_checkpoint_bytes: u64
World_Binding :: struct {
	id:           knet.Net_Id,
	entity:       rawptr,
	desc:         ^knet.Entity_Desc,
	hist:         ^History,
	offset, size: int,
}
World_Input_Backup :: struct {
	data:       []u8,
	tick:       []u64,
	scratch:    []u8,
	head, tail: u64,
}
World_Config :: struct {
	settle:                 Step_Proc, // after fixed native step, before authority-only pass
	additional_owned_bytes: u64, // game/proxy/runtime-owned allocations not above
	reservation_bytes:      u64, // measured upper allowance BEFORE open/capture
}
World_History :: struct {
	network:                              ^World_Network,
	provider:                             World_Provider,
	config:                               World_Config,
	allocator:                            mem.Allocator,
	published, candidate:                 rawptr,
	head, confirmed, field_schema:        u64,
	epoch:                                u64,
	work:                                 World_Work_Stats,
	status:                               World_Error,
	busy, publishing, presenting, resync: bool,
	field_bytes:                          int,
	bindings:                             []World_Binding,
	live_backup:                          []u8,
	input_backup:                         []World_Input_Backup,
	frames:                               [WORLD_HISTORY_FRAMES]World_Frame,
	staged:                               [WORLD_REPAIR_TICKS + 1]World_Frame,
	staged_count:                         int,
	current_effect_count:                 int,
	current_effects:                      [WORLD_EFFECTS_PER_TICK]World_Effect,
}

World_Work_Stats :: struct {
	normal_latest_ns, correction_latest_ns, normal_peak_ns, correction_peak_ns: u64,
}
lane_world_work_stats :: proc(l: ^Lane) -> World_Work_Stats {return(
		l.world != nil ? l.world.work : World_Work_Stats{} \
	)}
lane_world_epoch :: proc(l: ^Lane) -> u64 {return l.world != nil ? l.world.epoch : 0}
lane_world_confirmed :: proc(l: ^Lane) -> u64 {return l.world != nil ? l.world.confirmed : 0}
// Requested external ownership used in shared alpha observation; excludes RSS.
lane_world_owned_bytes :: proc(l: ^Lane) -> u64 {return(
		l.world != nil ? world_external_bytes(l) : 0 \
	)}
lane_world_status :: proc(l: ^Lane) -> World_Error {return(
		l.world != nil ? l.world.status : .Unsupported \
	)}
lane_world_needs_resync :: proc(l: ^Lane) -> bool {return l.world != nil && l.world.resync}
lane_world_busy :: proc(l: ^Lane) -> bool {return(
		l.world != nil &&
		(l.world.busy || l.world.presenting) \
	)}
// Unsupported operations call this BEFORE touching tracks, commands or scenes.
lane_world_refuse :: proc(l: ^Lane) -> bool {
	if l.world == nil {return false}
	l.world.status = .Unsupported
	l.world.resync = true
	return true
}
lane_world_fail :: proc(l: ^Lane, error: World_Error) {
	if l.world != nil && error != .Ok {l.world.status = error}
}

@(private)
world_field_guard :: proc(user: rawptr) -> bool {
	w := cast(^World_History)user
	if !w.publishing {w.status = .Unsupported; w.resync = true; return false}
	return true
}
@(private)
world_external_bytes :: proc(l: ^Lane) -> u64 {
	w :=
		l.world; n := u64(size_of(World_History) + len(w.bindings) * size_of(World_Binding) + len(w.live_backup))
	n += w.config.additional_owned_bytes + g_world_checkpoint_bytes
	for b in w.bindings {n += u64(size_of(History) + len(b.hist.data) + len(b.hist.tick) * size_of(u64))}
	for f in w.frames {n += u64(len(f.fields))}
	for f in w.staged {n += u64(len(f.fields))}
	for b in w.input_backup {n += u64(len(b.data) + len(b.tick) * 8 + len(b.scratch))}
	n += u64(size_of(Lane) + cap(l.tracked) * size_of(Tracked) + cap(l.entries) * size_of(Entry))
	for ic in l.inputs {n += u64(size_of(Input_Class) + len(ic.ring.ring.data) + len(ic.ring.ring.tick) * 8 + len(ic.scratch))}
	if w.network != nil {n += world_network_bytes(w.network)}
	return n
}
@(private)
world_capture_fields :: proc(w: ^World_History, dst: []u8) {
	for b in w.bindings {predict_capture(dst[b.offset:b.offset + b.size], b.entity, b.desc)}
}
@(private)
world_restore_fields :: proc(w: ^World_History, src: []u8) {
	for b in w.bindings {predict_restore(b.entity, b.desc, src[b.offset:b.offset + b.size])}
}
@(private)
world_record :: proc(w: ^World_History, tick: u64) -> ^World_Frame {
	f := &w.frames[tick % WORLD_HISTORY_FRAMES]
	return f.valid && f.tick == tick ? f : nil
}
@(private)
world_inputs_save :: proc(l: ^Lane) {
	for ic, i in l.inputs {b := &l.world.input_backup[i]; copy(b.data, ic.ring.ring.data); copy(b.tick, ic.ring.ring.tick); copy(b.scratch, ic.scratch); b.head = ic.ring.head; b.tail = ic.ring.tail}
}
@(private)
world_inputs_restore :: proc(l: ^Lane) {
	for &ic, i in l.inputs {b := &l.world.input_backup[i]; copy(ic.ring.ring.data, b.data); copy(ic.ring.ring.tick, b.tick); copy(ic.scratch, b.scratch); ic.ring.head = b.head; ic.ring.tail = b.tail}
}
@(private)
world_fields_free :: proc(w: ^World_History) {
	for &f in w.frames {if f.image != nil {w.provider.release(f.image)}; delete(f.fields)}
	for &f in w.staged {if f.image != nil {w.provider.release(f.image)}; delete(f.fields)}
	for b in w.input_backup {delete(b.data); delete(b.tick); delete(b.scratch)}
	delete(w.input_backup); delete(w.bindings); delete(w.live_backup)
}

// Register every proxy's full pointer-free value type. Tracking, owner changes,
// generated tick thunks and scheduled verbs stay unavailable while attached.
lane_world_attach :: proc(
	l: ^Lane,
	provider: World_Provider,
	types: []World_Field_Type,
	cfg := World_Config{},
) -> World_Error {
	if cfg.additional_owned_bytes > WORLD_MEMORY_BYTES ||
	   cfg.reservation_bytes > WORLD_MEMORY_BYTES {return .Budget}
	if l.world != nil ||
	   l.ses == nil ||
	   provider.initial_execution == nil ||
	   provider.asset_id == 0 ||
	   provider.side_type == nil ||
	   !world_value_supported(provider.side_type) ||
	   provider.capture == nil ||
	   provider.clone == nil ||
	   provider.equal == nil ||
	   provider.release == nil ||
	   provider.open == nil ||
	   provider.close == nil ||
	   provider.bind == nil ||
	   provider.publish == nil ||
	   provider.step == nil ||
	   provider.admit == nil ||
	   provider.admit_detached == nil {return .Invalid}
	if len(l.entries) > 35 ||
	   l.ticker.tick != 0 ||
	   l.slots != WORLD_HISTORY_FRAMES ||
	   abs(l.ticker.dt - 1.0 / 60.0) > 1e-12 ||
	   l.echo_on ||
	   l.tolerance != 0 ||
	   l.step_auth != nil ||
	   len(l.cmd_in) != 0 ||
	   len(l.cmd_out) != 0 ||
	   len(types) != len(l.entries) ||
	   len(l.pending) != 0 {return .Unsupported}
	for tr in l.tracked {if tr.watched || tr.tick != nil || tr.set != nil || tr.born != 0 {return .Unsupported}}
	for &e in l.entries {
		found := false
		for t in types {if t.id == e.id {
				if found || !world_value_supported(t.type) {return .Unsupported}
				for f in e.hist.desc.fields {if .Predicted in f.flags {if f.size <= 0 || f.offset > uintptr(type_info_of(t.type).size) || uintptr(f.size) > uintptr(type_info_of(t.type).size) - f.offset {return .Invalid}}}
				found = true
			}}
		if !found {return .Invalid}
	}
	field_bytes := 0
	estimate :=
		u64(size_of(World_History) + size_of(Lane)) +
		cfg.additional_owned_bytes +
		g_world_checkpoint_bytes
	for e in l.entries {
		if e.hist.size < 0 || e.hist.size > int(WORLD_MEMORY_BYTES / 256) {return .Budget}
		field_bytes += e.hist.size
		estimate += u64(
			size_of(World_Binding) + size_of(History) + len(e.hist.data) + 8 * len(e.hist.tick),
		)
	}
	estimate += u64(field_bytes) * u64(WORLD_HISTORY_FRAMES + WORLD_REPAIR_TICKS + 2)
	for ic in l.inputs {estimate += u64(size_of(Input_Class) + 2 * len(ic.ring.ring.data) + 16 * len(ic.ring.ring.tick) + 2 * len(ic.scratch) + size_of(World_Input_Backup))}
	estimate += u64(cap(l.tracked) * size_of(Tracked) + cap(l.entries) * size_of(Entry))
	if estimate > WORLD_MEMORY_BYTES {return .Budget}
	if status := provider.admit(
		provider.user,
		provider.initial_execution,
		World_Admission{additional_owned_bytes = estimate, reserved_bytes = cfg.reservation_bytes},
	); status != .Ok {return status}
	w, err := new(World_History, l.allocator); if err != nil {return .Allocation_Failed}
	w.allocator =
		l.allocator; w.provider = provider; w.config = cfg; w.published = provider.initial_execution
	w.head = l.ticker.tick; w.confirmed = w.head; w.epoch = 1; w.field_schema = 0xcbf29ce484222325
	allocation_failed := false
	w.bindings, err = make([]World_Binding, len(l.entries), l.allocator)
	if err != nil {free(w, l.allocator); return .Allocation_Failed}
	for e, i in l.entries {
		w.bindings[i] = {
			e.id,
			e.entity,
			e.hist.desc,
			e.hist,
			w.field_bytes,
			e.hist.size,
		}; w.field_bytes += e.hist.size
		w.field_schema =
			(w.field_schema ~ u64(e.id)) *
			0x100000001b3; w.field_schema = (w.field_schema ~ u64(e.hist.size)) * 0x100000001b3
		for t in types {if t.id ==
			   e.id {w.field_schema = (w.field_schema ~ u64(cast(uintptr)type_info_of(t.type))) * 0x100000001b3}}
		for f in e.hist.desc.fields {if .Predicted in f.flags {w.field_schema = (w.field_schema ~ u64(f.offset)) * 0x100000001b3; w.field_schema = (w.field_schema ~ u64(f.size)) * 0x100000001b3}}
	}
	if u64(w.field_bytes) >
	   WORLD_MEMORY_BYTES /
		   u64(
			   WORLD_HISTORY_FRAMES + WORLD_REPAIR_TICKS + 2,
		   ) {world_fields_free(w); free(w, l.allocator); return .Budget}
	w.live_backup, err = make([]u8, w.field_bytes, l.allocator); allocation_failed = err != nil
	for &f in w.frames {f.fields, err = make([]u8, w.field_bytes, l.allocator); allocation_failed = allocation_failed || err != nil}
	for &f in w.staged {f.fields, err = make([]u8, w.field_bytes, l.allocator); allocation_failed = allocation_failed || err != nil}
	w.input_backup, err = make(
		[]World_Input_Backup,
		len(l.inputs),
		l.allocator,
	); allocation_failed = allocation_failed || err != nil
	if !allocation_failed {for ic, i in l.inputs {
			b := &w.input_backup[i]
			b.data, err = make(
				[]u8,
				len(ic.ring.ring.data),
				l.allocator,
			); allocation_failed = allocation_failed || err != nil
			b.tick, err = make(
				[]u64,
				len(ic.ring.ring.tick),
				l.allocator,
			); allocation_failed = allocation_failed || err != nil
			b.scratch, err = make(
				[]u8,
				len(ic.scratch),
				l.allocator,
			); allocation_failed = allocation_failed || err != nil
		}}
	if allocation_failed {world_fields_free(w); free(w, l.allocator); return .Allocation_Failed}
	l.world = w
	request := World_Admission {
		additional_owned_bytes = world_external_bytes(l),
		reserved_bytes         = cfg.reservation_bytes,
	}
	status := provider.admit(provider.user, w.published, request)
	image: rawptr
	if status == .Ok {image, status = provider.capture(provider.user, w.published)}
	if status ==
	   .Ok {request.reserved_bytes = 0; status = provider.admit(provider.user, w.published, request)}
	if status !=
	   .Ok {if image != nil {provider.release(image)}; world_fields_free(w); free(w, l.allocator); l.world = nil; return status}
	f := &w.frames[w.head % WORLD_HISTORY_FRAMES]; f.tick = w.head; f.valid = true; f.image = image; world_capture_fields(w, f.fields)
	w.publishing = true
	for b in w.bindings {b.hist.write_guard = world_field_guard; b.hist.guard_user = w; history_note_bytes(b.hist, w.head, f.fields[b.offset:b.offset + b.size])}
	w.publishing = false
	provider.bind(
		provider.user,
		w.published,
	); provider.publish(provider.user, w.published); w.provider.initial_execution = nil
	l.anchored = true
	return .Ok
}

lane_world_detach :: proc(l: ^Lane) -> World_Error {
	if l.world == nil {return .Ok}
	w := l.world; if w.busy || w.presenting {return .Busy}
	_ = lane_world_network_detach(l)
	for b in w.bindings {b.hist.write_guard = nil; b.hist.guard_user = nil}
	world_fields_free(
		w,
	); w.provider.close(w.published); w.provider.bind(w.provider.user, nil); w.provider.publish(w.provider.user, nil)
	free(w, w.allocator); l.world = nil; return .Ok
}

lane_world_checkpoint :: proc(
	l: ^Lane,
	tick: u64,
) -> (
	checkpoint: World_Checkpoint,
	error: World_Error,
) {
	if l.world ==
	   nil {return {}, .Unsupported}; w := l.world; if w.busy || w.presenting {return {}, .Busy}
	f := world_record(w, tick); if f == nil {return {}, .History_Missing}
	charge := u64(len(f.fields) + size_of(World_Checkpoint))
	if g_world_checkpoint_bytes > WORLD_MEMORY_BYTES ||
	   charge > WORLD_MEMORY_BYTES - g_world_checkpoint_bytes {return {}, .Budget}
	if e := w.provider.admit_detached(
		g_world_checkpoint_bytes + charge,
		w.config.reservation_bytes,
	); e != .Ok {return {}, e}
	image, status := w.provider.clone(f.image); if status != .Ok {return {}, status}
	fields, err := make(
		[]u8,
		len(f.fields),
		w.allocator,
	); if err != nil {w.provider.release(image); return {}, .Allocation_Failed}; copy(fields, f.fields)
	checkpoint = {
		tick              = tick,
		asset_id          = w.provider.asset_id,
		field_schema      = w.field_schema,
		side_type         = w.provider.side_type,
		image             = image,
		fields            = fields,
		clone             = w.provider.clone,
		release           = w.provider.release,
		equal             = w.provider.equal,
		allocator         = w.allocator,
		admit_detached    = w.provider.admit_detached,
		effects_known     = true,
		effect_count      = f.effect_count,
		effects           = f.effects,
		charge_bytes      = charge,
		reservation_bytes = w.config.reservation_bytes,
	}
	g_world_checkpoint_bytes += charge
	if e := w.provider.admit_detached(g_world_checkpoint_bytes, 0);
	   e != .Ok {world_checkpoint_destroy(&checkpoint); return {}, e}
	return checkpoint, .Ok
}
world_checkpoint_clone :: proc(
	source: ^World_Checkpoint,
) -> (
	checkpoint: World_Checkpoint,
	error: World_Error,
) {
	if source == nil || source.image == nil || source.clone == nil {return {}, .Invalid}
	if g_world_checkpoint_bytes > WORLD_MEMORY_BYTES ||
	   source.charge_bytes > WORLD_MEMORY_BYTES - g_world_checkpoint_bytes {return {}, .Budget}
	if e := source.admit_detached(
		g_world_checkpoint_bytes + source.charge_bytes,
		source.reservation_bytes,
	); e != .Ok {return {}, e}
	image, status := source.clone(source.image); if status != .Ok {return {}, status}
	fields, err := make(
		[]u8,
		len(source.fields),
		source.allocator,
	); if err != nil {source.release(image); return {}, .Allocation_Failed}; copy(fields, source.fields)
	checkpoint = source^; checkpoint.image = image; checkpoint.fields = fields; g_world_checkpoint_bytes += checkpoint.charge_bytes
	if e := source.admit_detached(g_world_checkpoint_bytes, 0);
	   e != .Ok {world_checkpoint_destroy(&checkpoint); return {}, e}
	return checkpoint, .Ok
}
world_checkpoint_equal :: proc(left, right: ^World_Checkpoint) -> (bool, World_Error) {
	if left == nil ||
	   right == nil ||
	   left.image == nil ||
	   right.image == nil {return false, .Missing_Attachment}
	if left.tick != right.tick ||
	   left.asset_id != right.asset_id ||
	   left.side_type != right.side_type ||
	   left.field_schema != right.field_schema ||
	   len(left.fields) != len(right.fields) {return false, .Incompatible}
	if mem.compare(left.fields, right.fields) != 0 {return false, .Ok}
	if left.effects_known != right.effects_known ||
	   (left.effects_known &&
			   !world_effects_equal(
					   left.effects[:left.effect_count],
					   right.effects[:right.effect_count],
				   )) {return false, .Ok}
	return left.equal(left.image, right.image)
}
world_checkpoint_destroy :: proc(checkpoint: ^World_Checkpoint) {
	if checkpoint == nil || checkpoint.image == nil {return}
	context.allocator =
		checkpoint.allocator; checkpoint.release(checkpoint.image); delete(checkpoint.fields)
	assert(
		g_world_checkpoint_bytes >= checkpoint.charge_bytes,
	); g_world_checkpoint_bytes -= checkpoint.charge_bytes; checkpoint^ = {}
}
world_checkpoint_owned_bytes :: proc() -> u64 {return g_world_checkpoint_bytes}
// Read-only backend image for the concrete provider's immutable pose cache.
world_checkpoint_image :: proc(checkpoint: ^World_Checkpoint) -> rawptr {return(
		checkpoint != nil ? checkpoint.image : nil \
	)}

lane_world_emit :: proc(
	l: ^Lane,
	key: u64,
	fire: World_Effect_Proc,
	user: rawptr,
	args: []u8 = nil,
) -> World_Error {
	if l.world == nil || !l.world.busy || fire == nil || key == 0 {return .Invalid}
	w := l.world
	kind := u16(0)
	if w.network != nil {
		for def in w.network.effects {if def.fire == fire && def.user == user {
				if len(args) != def.codec.local_bytes {w.status = .Invalid; return .Invalid}
				canonical: [WORLD_EFFECT_BYTES]u8
				if error := def.codec.encode(
					def.codec.user,
					args,
					canonical[:def.codec.wire_bytes],
				); error != .Ok {w.status = error; return error}
				kind = def.kind; break}}
		if kind == 0 {w.status = .Unsupported; return .Unsupported}
	}
	if len(args) > WORLD_EFFECT_BYTES ||
	   w.current_effect_count >= WORLD_EFFECTS_PER_TICK {w.status = .Capacity; return .Capacity}
	for e in w.current_effects[:w.current_effect_count] {if e.key == key {w.status = .Invalid; return .Invalid}}
	e := &w.current_effects[w.current_effect_count]; e^ = {
		kind  = kind,
		key   = key,
		fire  = fire,
		user  = user,
		count = len(args),
	}; copy(e.args[:], args); w.current_effect_count += 1
	return .Ok
}

// Optional accepted-input/complete-state protocol. All local pointer-bearing
// codecs remain process-local. Only their canonical descriptors enter identity.
WORLD_NETWORK_REV :: u32(1)
WORLD_NETWORK_BYTES :: 1024 * 1024
WORLD_NETWORK_CHUNK :: 32 * 1024
WORLD_NETWORK_DRIVERS :: 16
WORLD_NETWORK_QUEUE :: 16
SIM_WORLD_INPUT :: u8(16)
SIM_WORLD_ACCEPTED :: u8(17)
SIM_WORLD_CHUNK :: u8(18)
SIM_WORLD_REQUEST :: u8(19)

World_Value_Codec :: struct {
	user:                    rawptr,
	local_bytes, wire_bytes: int,
	descriptor:              []u8, // canonical schema, no offsets/type_info addresses
	encode:                  proc(user: rawptr, local, wire: []u8) -> World_Error,
	decode:                  proc(user: rawptr, wire, local: []u8) -> World_Error,
}
World_Wire_Field :: struct {
	id:    knet.Net_Id,
	codec: World_Value_Codec,
}
World_Input_Prediction :: enum u8 {
	Hold,
	Neutral,
}
World_Wire_Input :: struct {
	class:      u16,
	codec:      World_Value_Codec,
	prediction: World_Input_Prediction,
}
World_Driver :: struct {
	player: knet.Player_Id,
	class:  u16,
}
World_Effect_Def :: struct {
	kind:  u16,
	fire:  World_Effect_Proc,
	user:  rawptr,
	codec: World_Value_Codec,
}
World_Wire_Codec :: struct {
	user:            rawptr,
	admit:           proc(user, execution: rawptr) -> (int, World_Error), // optional idle-execution probe; full writer fallback
	// Solver is the complete normalized logical dump; recovery_encode is the
	// separate canonical import attachment. Side and
	// Observations are canonical typed bytes; Game is composed by Kit.
	recovery_encode: proc(user, image: rawptr, out: []u8) -> (int, World_Error),
	encode:          proc(user, image: rawptr, part: bd.Part, out: []u8) -> (int, World_Error),
	decode:          proc(user: rawptr, solver, side, observations: []u8) -> (rawptr, World_Error),
	fields:          []World_Wire_Field,
	inputs:          []World_Wire_Input,
}
World_Network_Config :: struct {
	identity: bd.Identity,
	codec:    World_Wire_Codec,
	drivers:  []World_Driver, // immutable ordered roster, no AOI/contact filtering
	effects:  []World_Effect_Def,
	epoch:    u64,
}
World_Transfer_Mode :: enum u8 {
	Welcome,
	Correction,
	Reset,
}
World_Input_Origin :: enum u8 {
	Unknown,
	Submitted,
	Held,
	Authority,
}
World_Input_Row :: struct {
	tick:     u64,
	valid:    bool,
	sequence: [WORLD_NETWORK_DRIVERS]u64,
	origin:   [WORLD_NETWORK_DRIVERS]World_Input_Origin,
}
World_Net_Packet :: struct {
	from:  knet.Player_Id,
	kind:  u8,
	bytes: []u8,
}
World_Network :: struct {
	config:                                                 World_Network_Config,
	drivers:                                                []World_Driver,
	effects:                                                []World_Effect_Def,
	offsets:                                                [WORLD_NETWORK_DRIVERS]int,
	value_bytes:                                            int,
	// These are input ledgers, not another simulation/history runtime.
	accepted, proposed, used:                               [WORLD_HISTORY_FRAMES]World_Input_Row,
	accepted_data, proposed_data, used_data:                []u8,
	incoming:                                               [WORLD_REPAIR_TICKS]World_Input_Row,
	incoming_count:                                         int,
	check_signature:                                        bd.Signature,
	backup:                                                 [WORLD_HISTORY_FRAMES]World_Input_Row,
	backup_data:                                            []u8,
	staged:                                                 [WORLD_REPAIR_TICKS + 1]World_Input_Row,
	staged_data:                                            []u8,
	stage_count:                                            int,
	queue:                                                  [WORLD_NETWORK_QUEUE]World_Net_Packet,
	queue_count:                                            int,
	queue_bytes:                                            int,
	transfer:                                               []u8,
	transfer_seen:                                          [32]bool,
	transfer_hash:                                          bd.Digest,
	transfer_sequence, transfer_epoch, transfer_tick:       u64,
	transfer_mode:                                          World_Transfer_Mode,
	transfer_chunks, transfer_received:                     int,
	outbound_bytes:                                         u64,
	epoch, sequence, received_sequence, submitted_sequence: u64,
	ready, applying:                                        bool,
	authority:                                              bool,
	local_player:                                           knet.Player_Id,
	status:                                                 World_Error,
	last_signature:                                         bd.Signature,
	trace:                                                  bd.Trace,
	duplicates, conflicts, rejected, accepted_batches:      u64,
}
World_Network_Status :: struct {
	ready, needs_resync:                                                       bool,
	error:                                                                     World_Error,
	epoch, confirmed, head, accepted_batches, duplicates, conflicts, rejected: u64,
	owned_bytes:                                                               u64,
}
lane_world_network_status :: proc(l: ^Lane) -> World_Network_Status {
	if l == nil || l.world == nil || l.world.network == nil {return {error = .Unsupported}}
	w := l.world; n := w.network
	return {
		n.ready,
		w.resync,
		n.status,
		n.epoch,
		w.confirmed,
		w.head,
		n.accepted_batches,
		n.duplicates,
		n.conflicts,
		n.rejected,
		world_network_bytes(n),
	}
}

@(private)
world_effects_equal :: proc(a, b: []World_Effect) -> bool {
	if len(a) != len(b) {return false}
	for &x, i in a {y := &b[i]
		if x.kind != y.kind ||
		   x.key != y.key ||
		   x.count != y.count ||
		   mem.compare(x.args[:x.count], y.args[:y.count]) != 0 {return false}}
	return true
}

kit/sim/world_history.odin.text:
package kit_sim

import "core:math"
import "core:mem"
import "core:time"
import bd "godot:box3d/diagnostics"
import knet "godot:kit/net"
import ksess "godot:kit/session"

World_Commit_Gate :: struct {
	user:  rawptr,
	allow: proc(user: rawptr, tick: u64) -> bool,
}
World_Result :: struct {
	error: World_Error,
	tick:  u64,
	steps: int,
}

@(private)
world_admit :: proc(
	l: ^Lane,
	execution: rawptr,
	prediction, correction: u32,
	normal_ns, correction_ns: u64,
	reserve: bool,
) -> World_Error {
	w := l.world
	request := World_Admission {
		prediction,
		correction,
		world_external_bytes(l),
		reserve ? w.config.reservation_bytes : 0,
		normal_ns,
		correction_ns,
	}
	return w.provider.admit(w.provider.user, execution, request)
}
@(private)
world_stage_clear :: proc(w: ^World_History) {
	for &f in w.staged {if f.image != nil {w.provider.release(f.image)}; f.image = nil; f.valid = false; f.effect_count = 0}
	w.staged_count = 0
}
@(private)
world_stage_note :: proc(l: ^Lane, tick: u64) -> World_Error {
	w := l.world
	if w.staged_count >= len(w.staged) {return .Capacity}
	if error := world_admit(l, w.candidate, 0, 0, 0, 0, true); error != .Ok {return error}
	f := &w.staged[w.staged_count]
	image, error := w.provider.capture(w.provider.user, w.candidate)
	if error != .Ok {return error}
	f.image = image; f.tick = tick; f.valid = true; world_capture_fields(w, f.fields)
	f.effect_count = w.current_effect_count
	for i in 0 ..< f.effect_count {f.effects[i] = w.current_effects[i]}
	w.staged_count += 1
	if error := world_network_admit_image(l, image); error != .Ok {return error}
	return world_admit(l, w.candidate, 0, 0, 0, 0, false)
}

@(private)
world_publish :: proc(
	l: ^Lane,
	tick: u64,
	steps: int,
	confirm, reset_epoch: bool,
	started: time.Tick,
	normal: bool,
	confirm_to: u64 = 0,
) -> World_Result {
	w := l.world
	// No allocation, callback or fallible operation is permitted between owner
	// selection and committing fields/legacy ledgers. Effects are copied first.
	ready: [(WORLD_REPAIR_TICKS + 1) * WORLD_EFFECTS_PER_TICK]World_Effect
	ticks: [(WORLD_REPAIR_TICKS + 1) * WORLD_EFFECTS_PER_TICK]u64
	count := 0
	for &staged in w.staged[:w.staged_count] {
		old := world_record(w, staged.tick)
		for e in staged.effects[:staged.effect_count] {
			if reset_epoch {continue}
			seen := false
			if old !=
			   nil {for prior in old.effects[:old.effect_count] {if prior.key == e.key {seen = true; break}}}
			if !seen {ready[count] = e; ticks[count] = staged.tick; count += 1}
		}
	}
	retired := w.published
	w.publishing = true
	if reset_epoch {
		for &f in w.frames {if f.image != nil {w.provider.release(f.image)}; f.image = nil; f.valid = false; f.effect_count = 0}
		for b in w.bindings {mem.zero(raw_data(b.hist.tick), len(b.hist.tick) * 8)}
		for &ic in l.inputs {mem.zero(raw_data(ic.ring.ring.tick), len(ic.ring.ring.tick) * 8); ic.ring.head = 0; ic.ring.tail = 0; mem.zero(raw_data(ic.scratch), len(ic.scratch))}
		w.epoch += 1; w.confirmed = tick; l.ticker.acc = 0; clear(&l.pending); l.pending_tick = 0
	}
	w.provider.publish(w.provider.user, w.candidate)
	w.published = w.candidate; w.candidate = nil
	for &staged in w.staged[:w.staged_count] {
		f := &w.frames[staged.tick % WORLD_HISTORY_FRAMES]
		if f.image != nil {w.provider.release(f.image)}
		f.image =
			staged.image; staged.image = nil; f.tick = staged.tick; f.valid = true; copy(f.fields, staged.fields)
		f.effect_count = staged.effect_count
		for i in 0 ..< f.effect_count {f.effects[i] = staged.effects[i]}
		for b in w.bindings {history_note_bytes(b.hist, f.tick, f.fields[b.offset:b.offset + b.size])}
	}
	world_net_commit_inputs(l)
	w.head = tick; l.ticker.tick = tick
	if w.network != nil && l.ses.is_host {w.confirmed = tick}
	if confirm && !reset_epoch {w.confirmed = max(w.confirmed, w.staged[0].tick)}
	if confirm_to != 0 {w.confirmed = max(w.confirmed, confirm_to)}
	w.publishing = false; w.provider.bind(w.provider.user, w.published)
	w.provider.close(retired)
	elapsed := u64(max(i64(time.tick_since(started)), 0))
	if normal {w.work.normal_latest_ns = elapsed; w.work.normal_peak_ns = max(w.work.normal_peak_ns, elapsed)} else {w.work.correction_latest_ns = elapsed; w.work.correction_peak_ns = max(w.work.correction_peak_ns, elapsed)}
	w.status = .Ok; w.resync = false
	result := World_Result{.Ok, tick, steps}
	w.staged_count = 0
	// Release busy before effects, but a separate latch rejects reentrant lane
	// operations while irreversible presentation callbacks run after acceptance.
	w.busy = false; w.presenting = true
	for i in 0 ..< count {e := &ready[i]; e.fire(e.user, ticks[i], e.key, e.args[:e.count])}
	w.presenting = false
	return result
}

@(private)
world_operation :: proc(
	l: ^Lane,
	source: ^World_Frame,
	checkpoint: ^World_Checkpoint,
	head: u64,
	normal: bool,
	gate: World_Commit_Gate,
	reset_epoch := false,
	confirm_authority := true,
	verify_at: ^World_Checkpoint = nil,
	confirm_to: u64 = 0,
) -> (
	result: World_Result,
) {
	w := l.world
	if w == nil {return {.Unsupported, l.ticker.tick, 0}}
	context.allocator = w.allocator
	if w.busy || w.presenting {return {.Busy, w.head, 0}}
	if source == nil {return {.History_Missing, w.head, 0}}
	if head < source.tick ||
	   head - source.tick > WORLD_REPAIR_TICKS {return {.Repair_Limit, source.tick, 0}}
	correction := normal ? u32(0) : u32(head - source.tick)
	prediction := u32(0)
	if !l.ses.is_host && !reset_epoch {
		if head < w.confirmed ||
		   head - w.confirmed > WORLD_REPAIR_TICKS {return {.Prediction_Limit, head, 0}}
		prediction = u32(head - w.confirmed)
	}
	// Scheduled verbs have unmanaged patches/delta effects today. Do not run
	// them and pretend those effects are part of this transaction.
	if len(l.cmd_in) != 0 || len(l.cmd_out) != 0 {return {.Unsupported, w.head, 0}}
	for &ic in l.inputs {if ic.size > 0 && !normal {
			for offset in 0 ..< int(
				head - source.tick,
			) {tick := source.tick + u64(offset) + 1; if _, ok := input_read(&ic.ring, tick); !ok {return {.History_Missing, tick, 0}}}
		}}
	if error := world_admit(l, w.published, prediction, correction, 0, 0, true);
	   error != .Ok {return {error, w.head, 0}}
	started := time.tick_now()
	world_capture_fields(w, w.live_backup)
	world_inputs_save(l)
	old_resimming, old_step, old_auth := l.resimming, l.step_tick, l.in_auth
	success := false
	w.busy = true; w.status = .Ok; world_stage_clear(w)
	defer {
		l.resimming =
			old_resimming; l.step_tick = success ? w.head : old_step; l.in_auth = old_auth
		if !success {
			world_restore_fields(w, w.live_backup); world_inputs_restore(l)
			w.provider.bind(w.provider.user, w.published)
			if w.candidate != nil {w.provider.close(w.candidate); w.candidate = nil}
			world_stage_clear(w); w.busy = false
			w.status = result.error
			if result.error != .Rejected &&
			   result.error != .Allocation_Failed &&
			   result.error != .Step_Failed {w.resync = true}
		}
	}
	if error := world_net_operation_begin(l, source.tick);
	   error != .Ok {return {error, source.tick, 0}}
	execution, error := w.provider.open(w.provider.user, source.image)
	if error != .Ok {return {error, source.tick, 0}}
	w.candidate = execution; w.provider.bind(w.provider.user, execution)
	world_restore_fields(w, source.fields)
	if error := world_admit(l, execution, prediction, correction, 0, 0, true);
	   error != .Ok {return {error, source.tick, 0}}
	if !normal {
		// The authoritative predecessor is part of the accepted complete suffix,
		// even when every registered pose byte happens to match its prediction.
		f := &w.staged[0]
		f.image, error = w.provider.clone(source.image)
		if error != .Ok {return {error, source.tick, 0}}
		f.tick = source.tick; f.valid = true; f.effect_count = 0; copy(f.fields, source.fields)
		if old := world_record(w, source.tick);
		   old !=
		   nil {f.effect_count = old.effect_count; for i in 0 ..< f.effect_count {f.effects[i] = old.effects[i]}}
		if checkpoint != nil &&
		   checkpoint.effects_known {f.effect_count = checkpoint.effect_count; f.effects = checkpoint.effects}
		w.staged_count = 1
	}
	steps := 0
	l.resimming = true // generated/inline presentation never runs speculatively
	for offset in 0 ..< int(head - source.tick) {
		tick := source.tick + u64(offset) + 1
		if error := world_admit(l, execution, prediction, correction, 0, 0, true);
		   error != .Ok {return {error, tick, steps}}
		w.current_effect_count = 0
		if normal {sample_inputs(l, tick)}
		if error := world_net_prepare(l, tick); error != .Ok {return {error, tick, steps}}
		run_tick(l, tick)
		if w.status != .Ok {return {w.status, tick, steps}}
		steps += 1
		if error := world_stage_note(l, tick); error != .Ok {return {error, tick, steps}}
		if verify_at != nil && tick == verify_at.tick {
			actual := &w.staged[w.staged_count - 1]
			same, e := w.provider.equal(actual.image, verify_at.image)
			if e != .Ok {return {e, tick, steps}}
			if !same ||
			   mem.compare(actual.fields, verify_at.fields) != 0 ||
			   !world_effects_equal(
					   actual.effects[:actual.effect_count],
					   verify_at.effects[:verify_at.effect_count],
				   ) {
				if w.network !=
				   nil {world_network_trace_settled(l, w.network.check_signature, w.network.transfer, actual)}
				return {.Conflict, tick, steps}
			}
		}
	}
	elapsed := u64(max(i64(time.tick_since(started)), 0))
	// Diagnostic wall time is not causal admission state. OS preemption must
	// not turn a valid simulation into a sticky resync. P2 measures the4ms
	// targets in integration acceptance, outside deterministic simulation.
	if normal {w.work.normal_latest_ns = elapsed; w.work.normal_peak_ns = max(w.work.normal_peak_ns, elapsed)} else {w.work.correction_latest_ns = elapsed; w.work.correction_peak_ns = max(w.work.correction_peak_ns, elapsed)}
	if error := world_admit(l, execution, prediction, correction, 0, 0, false);
	   error != .Ok {return {error, head, steps}}
	if gate.allow != nil && !gate.allow(gate.user, head) {return {.Rejected, head, steps}}
	if gate.allow != nil {
		// Gates authorize; they do not gain permission to mutate the candidate.
		last := &w.staged[w.staged_count - 1]
		for b in w.bindings {if !predict_matches(b.entity, b.desc, last.fields[b.offset:b.offset + b.size]) {return {.Unsupported, head, steps}}}
		if error := world_admit(l, execution, prediction, correction, 0, 0, true);
		   error != .Ok {return {error, head, steps}}
		probe, error := w.provider.capture(
			w.provider.user,
			execution,
		); if error != .Ok {return {error, head, steps}}
		equal, compare_error := w.provider.equal(last.image, probe); w.provider.release(probe)
		if compare_error != .Ok {return {compare_error, head, steps}}
		if !equal {return {.Unsupported, head, steps}}
		if error := world_admit(l, execution, prediction, correction, 0, 0, false);
		   error != .Ok {return {error, head, steps}}
	}
	// A gate is outside simulation and may only authorize publication; changed
	// tracked/command structures must still fail rather than publish partial state.
	if w.status != .Ok {return {w.status, head, steps}}
	success = true
	return world_publish(
		l,
		head,
		steps,
		!normal && confirm_authority,
		reset_epoch,
		started,
		normal,
		confirm_to,
	)
}

@(private)
world_frame :: proc(l: ^Lane, dt: f64) -> int {
	w := l.world
	if w.busy || w.presenting {w.status = .Busy; return 0}
	if w.network != nil {world_network_ingest(l); if !w.network.ready {return 0}}
	if w.resync {return 0}
	if len(l.pending) != 0 {w.status = .Missing_Attachment; w.resync = true; return 0}
	if w.head == max(u64) {w.status = .Capacity; w.resync = true; return 0}
	if dt < 0 || math.is_nan(dt) || math.is_inf(dt) {w.status = .Invalid; return 0}
	total := l.ticker.acc + dt * l.ticker.scale
	if total >=
	   l.ticker.dt *
		   f64(MAX_CATCHUP_TICKS + 1) {w.status = .Repair_Limit; w.resync = true; return 0}
	trial := l.ticker; n := sim_ticker_advance(&trial, dt); accepted := 0
	if n == 0 {l.ticker.acc = total; return 0}
	for _ in 0 ..< n {
		source := world_record(w, w.head)
		result := world_operation(l, source, nil, w.head + 1, true, {})
		if result.error !=
		   .Ok {w.status = result.error; if result.error != .Rejected && result.error != .Allocation_Failed && result.error != .Step_Failed && result.error != .Busy {w.resync = true}; return accepted}
		accepted += 1; l.ticker.acc = total - f64(accepted) * l.ticker.dt
		if w.network != nil {world_network_after_tick(l)}
	}
	return accepted
}

// Reset is explicit complete-state recovery. It never manufactures missing
// history from live state or drops solver attachments. Exported checkpoints own
// their image/fields independently of the source Lane/provider lifetime.
lane_world_reset :: proc(
	l: ^Lane,
	checkpoint: ^World_Checkpoint,
	gate := World_Commit_Gate{},
) -> World_Result {
	return world_reconcile(l, checkpoint, true, gate)
}
@(private)
world_reconcile :: proc(
	l: ^Lane,
	checkpoint: ^World_Checkpoint,
	reset: bool,
	gate: World_Commit_Gate,
) -> World_Result {
	if l.world == nil {return {.Unsupported, l.ticker.tick, 0}}
	w := l.world
	if w.network != nil && !w.network.applying {return {.Rejected, w.head, 0}}
	if checkpoint == nil ||
	   checkpoint.image ==
		   nil {w.status = .Missing_Attachment; w.resync = true; return {.Missing_Attachment, w.head, 0}}
	if checkpoint.asset_id != w.provider.asset_id ||
	   checkpoint.side_type != w.provider.side_type ||
	   checkpoint.field_schema != w.field_schema ||
	   len(checkpoint.fields) !=
		   w.field_bytes {w.status = .Incompatible; w.resync = true; return {.Incompatible, checkpoint.tick, 0}}
	if w.busy || w.presenting {return {.Busy, w.head, 0}}
	if !reset &&
	   checkpoint.tick < w.confirmed {w.status = .Settled; return {.Settled, checkpoint.tick, 0}}
	if !reset && checkpoint.tick == w.confirmed {
		settled := world_record(w, w.confirmed)
		if settled ==
		   nil {w.status = .History_Missing; w.resync = true; return {.History_Missing, checkpoint.tick, 0}}
		equal, status := w.provider.equal(settled.image, checkpoint.image)
		if status != .Ok {w.status = status; return {status, checkpoint.tick, 0}}
		if !equal ||
		   (checkpoint.effects_known &&
				   !world_effects_equal(
						   settled.effects[:settled.effect_count],
						   checkpoint.effects[:checkpoint.effect_count],
					   )) ||
		   mem.compare(settled.fields, checkpoint.fields) !=
			   0 {w.status = .Conflict; w.resync = true; return {.Conflict, checkpoint.tick, 0}}
		w.status = .Ok; return {.Ok, w.head, 0}
	}
	if !reset &&
	   world_record(w, checkpoint.tick) ==
		   nil {w.status = .History_Missing; w.resync = true; return {.History_Missing, checkpoint.tick, 0}}
	if !reset &&
	   (checkpoint.tick > w.head ||
			   w.head - checkpoint.tick >
				   WORLD_REPAIR_TICKS) {w.status = .Repair_Limit; w.resync = true; return {.Repair_Limit, checkpoint.tick, 0}}
	frame := World_Frame {
		tick   = checkpoint.tick,
		valid  = true,
		image  = checkpoint.image,
		fields = checkpoint.fields,
	}
	head := reset ? checkpoint.tick : w.head
	if reset && w.epoch == max(u64) {return {.Capacity, checkpoint.tick, 0}}
	result := world_operation(l, &frame, checkpoint, head, false, gate, reset_epoch = reset)
	if result.error == .Ok &&
	   !reset {l.stat_reconciles += 1; l.stat_resims += result.steps; l.stat_resim_seconds += f64(w.work.correction_latest_ns) / 1e9}
	return result
}

@(private)
world_network_bytes :: proc(n: ^World_Network) -> u64 {
	if n == nil {return 0}
	return(
		u64(
			size_of(World_Network) +
			len(n.drivers) * size_of(World_Driver) +
			len(n.effects) * size_of(World_Effect_Def) +
			len(n.accepted_data) +
			len(n.proposed_data) +
			len(n.used_data) +
			len(n.backup_data) +
			len(n.staged_data) +
			len(n.transfer) +
			n.queue_bytes +
			len(n.trace.storage),
		) +
		n.outbound_bytes \
	)
}
// Must be installed after local participant/tracks and before stepping. Codecs
// and catalogs are immutable and must outlive this attachment. Driver roster is
// fixed for an epoch; a roster/content change requires a new explicit reset.
lane_world_network_attach :: proc(l: ^Lane, cfg: World_Network_Config) -> World_Error {
	if l == nil || l.world == nil {return .Unsupported}; w := l.world
	if w.busy || w.presenting {return .Busy}
	if w.network != nil ||
	   w.head != 0 ||
	   cfg.epoch == 0 ||
	   cfg.codec.encode == nil ||
	   cfg.codec.recovery_encode == nil ||
	   cfg.codec.decode == nil ||
	   len(cfg.drivers) > WORLD_NETWORK_DRIVERS ||
	   len(cfg.effects) > WORLD_EFFECTS_PER_TICK ||
	   len(cfg.codec.fields) != len(w.bindings) {return .Invalid}
	// Validate the mandatory shared identity through the native-free utility.
	probe, pe := bd.sign(
		{
			identity = cfg.identity,
			epoch = cfg.epoch,
			parts = {
				.Solver = {1},
				.Game = nil,
				.Side = nil,
				.Observations = nil,
				.Occurrences = nil,
			},
		},
	); _ = probe
	if pe != .None {return .Incompatible}
	bytes := 0
	for d, i in cfg.drivers {
		if d.player == knet.PLAYER_ID_INVALID {return .Invalid}
		for p in cfg.drivers[:i] {if p == d {return .Conflict}}
		found := false
		for c in cfg.codec.inputs {if c.class == d.class {
				if found ||
				   c.prediction > .Neutral ||
				   c.codec.encode == nil ||
				   c.codec.decode == nil ||
				   c.codec.local_bytes < 1 ||
				   c.codec.local_bytes > MAX_INPUT_SIZE ||
				   c.codec.wire_bytes < 1 ||
				   c.codec.wire_bytes > MAX_INPUT_SIZE ||
				   len(c.codec.descriptor) == 0 {return .Incompatible}
				ic := lane_class(
					l,
					d.class,
				); if ic == nil || ic.size != c.codec.local_bytes {return .Incompatible}
				bytes += c.codec.local_bytes; found = true
			}}
		if !found {return .Incompatible}
	}
	for b, index in w.bindings {
		if cfg.codec.fields[index].id != b.id {return .Incompatible}
		found := false
		for f in cfg.codec.fields {if f.id == b.id {
				if found ||
				   f.codec.local_bytes != b.size ||
				   f.codec.wire_bytes < 0 ||
				   f.codec.wire_bytes > WORLD_NETWORK_BYTES ||
				   len(f.codec.descriptor) == 0 ||
				   f.codec.encode == nil ||
				   f.codec.decode == nil {return .Incompatible}; found = true
			}}
		if !found {return .Incompatible}
	}
	for e, i in cfg.effects {if e.kind == 0 || e.fire == nil || e.codec.encode == nil || e.codec.decode == nil || e.codec.local_bytes < 0 || e.codec.local_bytes > WORLD_EFFECT_BYTES || e.codec.wire_bytes < 0 || e.codec.wire_bytes > WORLD_EFFECT_BYTES || len(e.codec.descriptor) == 0 {return .Invalid}; for p in cfg.effects[:i] {if p.kind == e.kind || (p.fire == e.fire && p.user == e.user) {return .Conflict}}}
	need := u64(
		size_of(World_Network) +
		len(cfg.drivers) * size_of(World_Driver) +
		len(cfg.effects) * size_of(World_Effect_Def) +
		(WORLD_HISTORY_FRAMES * 4 + WORLD_REPAIR_TICKS + 1) * bytes,
	)
	if need > WORLD_MEMORY_BYTES ||
	   world_external_bytes(l) > WORLD_MEMORY_BYTES - need {return .Budget}
	if err := w.provider.admit_detached(
		world_external_bytes(l) + need,
		w.config.reservation_bytes,
	); err != .Ok {return err}
	n, err := new(
		World_Network,
		w.allocator,
	); if err != nil || n == nil {return .Allocation_Failed}
	n.config =
		cfg; n.epoch = cfg.epoch; n.value_bytes = bytes; n.ready = l.ses.is_host; n.authority = l.ses.is_host; n.local_player = l.ses.me
	w.network = n
	ok := false; defer {if !ok {_ = lane_world_network_detach(l)}}
	n.drivers, err = make(
		[]World_Driver,
		len(cfg.drivers),
		w.allocator,
	); if err != nil || len(n.drivers) != len(cfg.drivers) {return .Allocation_Failed}; copy(n.drivers, cfg.drivers)
	n.effects, err = make(
		[]World_Effect_Def,
		len(cfg.effects),
		w.allocator,
	); if err != nil || len(n.effects) != len(cfg.effects) {return .Allocation_Failed}; copy(n.effects, cfg.effects)
	for d, i in n.drivers {if i > 0 {n.offsets[i] = n.offsets[i - 1] + world_net_input_codec(n, n.drivers[i - 1].class).local_bytes}; _ = d}
