	if error != .Ok {fmt.eprintf("KIT_NETWORK_ATTACH error=%v count=%d\n", error, count)}
	assert(error == .Ok)
}
destroy :: proc(box: ^Box) {
	assert(p.network_destroy(&box.network) == .Ok); assert(p.detach(&box.physics) == .Ok)
	p.codec_destroy(&box.control); p.codec_destroy(&box.action); p.codec_destroy(&box.proxy)
	k.lane_destroy(
		&box.lane,
	); for parcel in box.out {delete(parcel.bytes)}; delete(box.out); s.session_destroy(&box.ses)
}
